INSERT INTO paper (paper_id, openalex_id, doi, arxiv_id, title, abstract, publication_date, venue_id, work_type, open_access, oa_status, cited_by_count, paper_url) OVERRIDING SYSTEM VALUE
SELECT paper_id, openalex_id, doi, arxiv_id, title, abstract, publication_date, venue_id, work_type, open_access, oa_status, cited_by_count, paper_url FROM jsonb_populate_recordset(NULL::paper, $fx$[{"doi": "10.1038/nature14441", "title": "Training and operation of an integrated neuromorphic network based on metal-oxide memristors", "abstract": null, "arxiv_id": "1412.0611", "paper_id": 2, "venue_id": 2, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1038/nature14441", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W1542981317", "cited_by_count": 2998, "publication_date": "2015-05-01"}, {"doi": "10.1038/nmat4756", "title": "Memristors with diffusive dynamics as synaptic emulators for neuromorphic computing", "abstract": null, "arxiv_id": null, "paper_id": 4, "venue_id": 4, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1038/nmat4756", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2526646482", "cited_by_count": 2353, "publication_date": "2016-09-26"}, {"doi": "10.1038/s41928-017-0006-8", "title": "The future of electronics based on memristive systems", "abstract": null, "arxiv_id": null, "paper_id": 7, "venue_id": 5, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/s41928-017-0006-8", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2778935320", "cited_by_count": 2135, "publication_date": "2017-12-21"}, {"doi": "10.1038/nmat4856", "title": "A non-volatile organic electrochemical device as a low-voltage artificial synapse for neuromorphic computing", "abstract": null, "arxiv_id": null, "paper_id": 9, "venue_id": 4, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1038/nmat4856", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2591029953", "cited_by_count": 1864, "publication_date": "2017-02-20"}, {"doi": "10.1038/s41565-019-0501-3", "title": "Optoelectronic resistive random access memory for neuromorphic vision sensors", "abstract": null, "arxiv_id": null, "paper_id": 20, "venue_id": 13, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/s41565-019-0501-3", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2957921024", "cited_by_count": 1328, "publication_date": "2019-07-15"}, {"doi": "10.1038/nnano.2016.70", "title": "Stochastic phase-change neurons", "abstract": null, "arxiv_id": null, "paper_id": 32, "venue_id": 13, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nnano.2016.70", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2389556795", "cited_by_count": 1115, "publication_date": "2016-05-13"}, {"doi": "10.1002/adma.201902761", "title": "Bridging Biological and Artificial Neural Networks with Emerging Neuromorphic Devices: Fundamentals, Progress, and Challenges", "abstract": "As the research on artificial intelligence booms, there is broad interest in brain-inspired computing using novel neuromorphic devices. The potential of various emerging materials and devices for neuromorphic computing has attracted extensive research efforts, leading to a large number of publications. Going forward, in order to better emulate the brain's functions, its relevant fundamentals, working mechanisms, and resultant behaviors need to be re-visited, better understood, and connected to electronics. A systematic overview of biological and artificial neural systems is given, along with their related critical mechanisms. Recent progress in neuromorphic devices is reviewed and, more importantly, the existing challenges are highlighted to hopefully shed light on future research directions.", "arxiv_id": null, "paper_id": 54, "venue_id": 8, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1002/adma.201902761", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2976743137", "cited_by_count": 839, "publication_date": "2019-09-24"}, {"doi": "10.1145/3571155", "title": "Exploring Neuromorphic Computing Based on Spiking Neural Networks: Algorithms to Hardware", "abstract": "Neuromorphic Computing, a concept pioneered in the late 1980s, is receiving a lot of attention lately due to its promise of reducing the computational energy, latency, as well as learning complexity in artificial neural networks. Taking inspiration from neuroscience, this interdisciplinary field performs a multi-stack optimization across devices, circuits, and algorithms by providing an end-to-end approach to achieving brain-like efficiency in machine intelligence. On one side, neuromorphic computing introduces a new algorithmic paradigm, known as Spiking Neural Networks (SNNs), which is a significant shift from standard deep learning and transmits information as spikes (“1” or “0”) rather than analog values. This has opened up novel algorithmic research directions to formulate methods to represent data in spike-trains, develop neuron models that can process information over time, design learning algorithms for event-driven dynamical systems, and engineer network architectures amenable to sparse, asynchronous, event-driven computing to achieve lower power consumption. On the other side, a parallel research thrust focuses on development of efficient computing platforms for new algorithms. Standard accelerators that are amenable to deep learning workloads are not particularly suitable to handle processing across multiple timesteps efficiently. To that effect, researchers have designed neuromorphic hardware that rely on event-driven sparse computations as well as efficient matrix operations. While most large-scale neuromorphic systems have been explored based on CMOS technology, recently, Non-Volatile Memory (NVM) technologies show promise toward implementing bio-mimetic functionalities on single devices. In this article, we outline several strides that neuromorphic computing based on spiking neural networks (SNNs) has taken over the recent past, and we present our outlook on the challenges that this field needs to overcome to make the bio-plausibility route a successful one.", "arxiv_id": null, "paper_id": 311, "venue_id": 91, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1145/3571155", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4309618925", "cited_by_count": 269, "publication_date": "2022-11-17"}, {"doi": "10.1109/access.2020.3039858", "title": "Hardware and Software Optimizations for Accelerating Deep Neural Networks: Survey of Current Trends, Challenges, and the Road Ahead", "abstract": "Currently, Machine Learning (ML) is becoming ubiquitous in everyday life. Deep Learning (DL) is already present in many applications ranging from computer vision for medicine to autonomous driving of modern cars as well as other sectors in security, healthcare, and finance. However, to achieve impressive performance, these algorithms employ very deep networks, requiring a significant computational power, both during the training and inference time. A single inference of a DL model may require billions of multiply-and-accumulated operations, making the DL extremely compute- and energy-hungry. In a scenario where several sophisticated algorithms need to be executed with limited energy and low latency, the need for cost-effective hardware platforms capable of implementing energy-efficient DL execution arises. This paper first introduces the key properties of two brain-inspired models like Deep Neural Network (DNN), and Spiking Neural Network (SNN), and then analyzes techniques to produce efficient and high-performance designs. This work summarizes and compares the works for four leading platforms for the execution of algorithms such as CPU, GPU, FPGA and ASIC describing the main solutions of the state-of-the-art, giving much prominence to the last two solutions since they offer greater design flexibility and bear the potential of high energy-efficiency, especially for the inference process. In addition to hardware solutions, this paper discusses some of the important security issues that these DNN and SNN models may have during their execution, and offers a comprehensive section on benchmarking, explaining how to assess the quality of different networks and hardware systems designed for them.", "arxiv_id": "2012.11233", "paper_id": 404, "venue_id": 106, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/access.2020.3039858", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3108426037", "cited_by_count": 223, "publication_date": "2020-01-01"}, {"doi": "10.1109/tpami.2023.3275769", "title": "Fast-SNN: Fast Spiking Neural Network by Converting Quantized ANN", "abstract": "Spiking neural networks (SNNs) have shown advantages in computation and energy efficiency over traditional artificial neural networks (ANNs) thanks to their event-driven representations. SNNs also replace weight multiplications in ANNs with additions, which are more energy-efficient and less computationally intensive. However, it remains a challenge to train deep SNNs due to the discrete spiking function. A popular approach to circumvent this challenge is ANN-to-SNN conversion. However, due to the quantization error and accumulating error, it often requires lots of time steps (high inference latency) to achieve high performance, which negates SNN's advantages. To this end, this paper proposes Fast-SNN that achieves high performance with low latency. We demonstrate the equivalent mapping between temporal quantization in SNNs and spatial quantization in ANNs, based on which the minimization of the quantization error is transferred to quantized ANN training. With the minimization of the quantization error, we show that the sequential error is the primary cause of the accumulating error, which is addressed by introducing a signed IF neuron model and a layer-wise fine-tuning mechanism. Our method achieves state-of-the-art performance and low latency on various computer vision tasks, including image classification, object detection, and semantic segmentation. Codes are available at: https://github.com/yangfan-hu/Fast-SNN.", "arxiv_id": "2305.19868", "paper_id": 581, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2023.3275769", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4386825396", "cited_by_count": 111, "publication_date": "2023-09-18"}, {"doi": "10.17863/cam.48429", "title": "Graph Attention Networks", "abstract": "We present graph attention networks (GATs), novel neural network architectures that operate on graph-structured data, leveraging masked self-attentional layers to address the shortcomings of prior methods based on graph convolutions or their approximations. By stacking layers in which nodes are able to attend over their neighborhoods' features, we enable (implicitly) specifying different weights to different nodes in a neighborhood, without requiring any kind of costly matrix operation (such as inversion) or depending on knowing the graph structure upfront. In this way, we address several key challenges of spectral-based graph neural networks simultaneously, and make our model readily applicable to inductive as well as transductive problems. Our GAT models have achieved or matched state-of-the-art results across four established transductive and inductive graph benchmarks: the Cora, Citeseer and Pubmed citation network datasets, as well as a protein-protein interaction dataset (wherein test graphs remain unseen during training).", "arxiv_id": "1710.10903", "paper_id": 878, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1710.10903", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2766453196", "cited_by_count": 12101, "publication_date": "2017-10-30"}, {"doi": "10.1145/3505244", "title": "Transformers in Vision: A Survey", "abstract": "Astounding results from Transformer models on natural language tasks have intrigued the vision community to study their application to computer vision problems. Among their salient benefits, Transformers enable modeling long dependencies between input sequence elements and support parallel processing of sequence as compared to recurrent networks, e.g., Long short-term memory. Different from convolutional networks, Transformers require minimal inductive biases for their design and are naturally suited as set-functions. Furthermore, the straightforward design of Transformers allows processing multiple modalities (e.g., images, videos, text, and speech) using similar processing blocks and demonstrates excellent scalability to very large capacity networks and huge datasets. These strengths have led to exciting progress on a number of vision tasks using Transformer networks. This survey aims to provide a comprehensive overview of the Transformer models in the computer vision discipline. We start with an introduction to fundamental concepts behind the success of Transformers, i.e., self-attention, large-scale pre-training, and bidirectional feature encoding. We then cover extensive applications of transformers in vision including popular recognition tasks (e.g., image classification, object detection, action recognition, and segmentation), generative modeling, multi-modal tasks (e.g., visual-question answering, visual reasoning, and visual grounding), video processing (e.g., activity recognition, video forecasting), low-level vision (e.g., image super-resolution, image enhancement, and colorization), and three-dimensional analysis (e.g., point cloud classification and segmentation). We compare the respective advantages and limitations of popular techniques both in terms of architectural design and their experimental value. Finally, we provide an analysis on open research directions and possible future works. We hope this effort will ignite further interest in the community to solve current challenges toward the application of transformer models in computer vision.", "arxiv_id": "2101.01169", "paper_id": 885, "venue_id": 91, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1145/3505244", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3119997354", "cited_by_count": 3585, "publication_date": "2022-01-06"}, {"doi": "10.48550/arxiv.1906.05909", "title": "Stand-Alone Self-Attention in Vision Models", "abstract": "Convolutions are a fundamental building block of modern computer vision systems. Recent approaches have argued for going beyond convolutions in order to capture long-range dependencies. These efforts focus on augmenting convolutional models with content-based interactions, such as self-attention and non-local means, to achieve gains on a number of vision tasks. The natural question that arises is whether attention can be a stand-alone primitive for vision models instead of serving as just an augmentation on top of convolutions. In developing and testing a pure self-attention vision model, we verify that self-attention can indeed be an effective stand-alone layer. A simple procedure of replacing all instances of spatial convolutions with a form of self-attention applied to ResNet model produces a fully self-attentional model that outperforms the baseline on ImageNet classification with 12% fewer FLOPS and 29% fewer parameters. On COCO object detection, a pure self-attention model matches the mAP of a baseline RetinaNet while having 39% fewer FLOPS and 34% fewer parameters. Detailed ablation studies demonstrate that self-attention is especially impactful when used in later layers. These results establish that stand-alone self-attention is an important addition to the vision practitioner's toolbox.", "arxiv_id": "1906.05909", "paper_id": 921, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1906.05909", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2949718784", "cited_by_count": 977, "publication_date": "2019-06-13"}, {"doi": "10.1109/tpami.2022.3164083", "title": "Contextual Transformer Networks for Visual Recognition", "abstract": "Transformer with self-attention has led to the revolutionizing of natural language processing field, and recently inspires the emergence of Transformer-style architecture design with competitive results in numerous computer vision tasks. Nevertheless, most of existing designs directly employ self-attention over a 2D feature map to obtain the attention matrix based on pairs of isolated queries and keys at each spatial location, but leave the rich contexts among neighbor keys under-exploited. In this work, we design a novel Transformer-style module, i.e., Contextual Transformer (CoT) block, for visual recognition. Such design fully capitalizes on the contextual information among input keys to guide the learning of dynamic attention matrix and thus strengthens the capacity of visual representation. Technically, CoT block first contextually encodes input keys via a 3×3 convolution, leading to a static contextual representation of inputs. We further concatenate the encoded keys with input queries to learn the dynamic multi-head attention matrix through two consecutive 1×1 convolutions. The learnt attention matrix is multiplied by input values to achieve the dynamic contextual representation of inputs. The fusion of the static and dynamic contextual representations are finally taken as outputs. Our CoT block is appealing in the view that it can readily replace each 3×3 convolution in ResNet architectures, yielding a Transformer-style backbone named as Contextual Transformer Networks (CoTNet). Through extensive experiments over a wide range of applications (e.g., image recognition, object detection, instance segmentation, and semantic segmentation), we validate the superiority of CoTNet as a stronger backbone. Source code is available at https://github.com/JDAI-CV/CoTNet.", "arxiv_id": "2107.12292", "paper_id": 945, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2022.3164083", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3183430956", "cited_by_count": 755, "publication_date": "2022-04-01"}, {"doi": "10.1007/s13042-024-02443-6", "title": "A comprehensive survey on pretrained foundation models: a history from BERT to ChatGPT", "abstract": null, "arxiv_id": "2302.09419", "paper_id": 972, "venue_id": 201, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s13042-024-02443-6", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4404658388", "cited_by_count": 571, "publication_date": "2024-11-24"}, {"doi": "10.1109/tmm.2023.3243616", "title": "DilateFormer: Multi-Scale Dilated Transformer for Visual Recognition", "abstract": "As ade factosolution, the vanilla Vision Transformers (ViTs) are encouraged to model long-range dependencies between arbitrary image patches while the global attended receptive field leads to quadratic computational cost. Another branch of Vision Transformers exploits local attention inspired by CNNs, which only models the interactions between patches in small neighborhoods. Although such a solution reduces the computational cost, it naturally suffers from small attended receptive fields, which may limit the performance. In this work, we explore effective Vision Transformers to pursue a preferable trade-off between the computational complexity and size of the attended receptive field. By analyzing the patch interaction of global attention in ViTs, we observe two key properties in the shallow layers, namely locality and sparsity, indicating the redundancy of global dependency modeling in shallow layers of ViTs. Accordingly, we propose Multi-Scale Dilated Attention (MSDA) to modellocalandsparsepatch interaction within the sliding window. With a pyramid architecture, we construct a Multi-Scale Dilated Transformer (DilateFormer) by stacking MSDA blocks at low-level stages and global multi-head self-attention blocks at high-level stages. Our experiment results show that our DilateFormer achieves state-of-the-art performance on various vision tasks. On ImageNet-1 K classification task, DilateFormer achieves comparable performance with 70% fewer FLOPs compared with existing state-of-the-art models. Our DilateFormer-Base achieves 85.6% top-1 accuracy on ImageNet-1 K classification task, 53.5% box mAP/46.1% mask mAP on COCO object detection/instance segmentation task and 51.1% MS mIoU on ADE20 K semantic segmentation task.", "arxiv_id": "2302.01791", "paper_id": 1029, "venue_id": 225, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tmm.2023.3243616", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4319663728", "cited_by_count": 401, "publication_date": "2023-01-01"}, {"doi": "10.1109/tpami.2023.3329173", "title": "MetaFormer Baselines for Vision", "abstract": "MetaFormer, the abstracted architecture of Transformer, has been found to play a significant role in achieving competitive performance. In this paper, we further explore the capacity of MetaFormer, again, by migrating our focus away from the token mixer design: we introduce several baseline models under MetaFormer using the most basic or common mixers, and demonstrate their gratifying performance. We summarize our observations as follows: (1) MetaFormer ensures solid lower bound of performance. By merely adopting identity mapping as the token mixer, the MetaFormer model, termed IdentityFormer, achieves [Formula: see text]80% accuracy on ImageNet-1 K. (2) MetaFormer works well with arbitrary token mixers. When specifying the token mixer as even a random matrix to mix tokens, the resulting model RandFormer yields an accuracy of [Formula: see text]81%, outperforming IdentityFormer. Rest assured of MetaFormer's results when new token mixers are adopted. (3) MetaFormer effortlessly offers state-of-the-art results. With just conventional token mixers dated back five years ago, the models instantiated from MetaFormer already beat state of the art. (a) ConvFormer outperforms ConvNeXt. Taking the common depthwise separable convolutions as the token mixer, the model termed ConvFormer, which can be regarded as pure CNNs, outperforms the strong CNN model ConvNeXt. (b) CAFormer sets new record on ImageNet-1 K. By simply applying depthwise separable convolutions as token mixer in the bottom stages and vanilla self-attention in the top stages, the resulting model CAFormer sets a new record on ImageNet-1 K: it achieves an accuracy of 85.5% at 224 ×224 resolution, under normal supervised training without external data or distillation. In our expedition to probe MetaFormer, we also find that a new activation, StarReLU, reduces 71% FLOPs of activation compared with commonly-used GELU yet achieves better performance. Specifically, StarReLU is a variant of Squared ReLU dedicated to alleviating distribution shift. We expect StarReLU to find great potential in MetaFormer- like models alongside other neural networks. Code and models are available at https://github.com/sail-sg/metaformer.", "arxiv_id": "2210.13452", "paper_id": 1057, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2023.3329173", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4388145401", "cited_by_count": 342, "publication_date": "2023-11-01"}, {"doi": "10.1109/tpami.2022.3206108", "title": "VOLO: Vision Outlooker for Visual Recognition", "abstract": "Recently, Vision Transformers (ViTs) have been broadly explored in visual recognition. With low efficiency in encoding fine-level features, the performance of ViTs is still inferior to the state-of-the-art CNNs when trained from scratch on a midsize dataset like ImageNet. Through experimental analysis, we find it is because of two reasons: 1) the simple tokenization of input images fails to model the important local structure such as edges and lines, leading to low training sample efficiency; 2) the redundant attention backbone design of ViTs leads to limited feature richness for fixed computation budgets and limited training samples. To overcome such limitations, we present a new simple and generic architecture, termed Vision Outlooker (VOLO), which implements a novel outlook attention operation that dynamically conduct the local feature aggregation mechanism in a sliding window manner across the input image. Unlike self-attention that focuses on modeling global dependencies of local features at a coarse level, our outlook attention targets at encoding finer-level features, which is critical for recognition but ignored by self-attention. Outlook attention breaks the bottleneck of self-attention whose computation cost scales quadratically with the input spatial dimension, and thus is much more memory efficient. Compared to our Tokens-To-Token Vision Transformer (T2T-ViT), VOLO can more efficiently encode fine-level features that are essential for high-performance visual recognition. Experiments show that with only 26.6 M learnable parameters, VOLO achieves 84.2% top-1 accuracy on ImageNet-1 K without using extra training data, 2.7% better than T2T-ViT with a comparable number of parameters. When the model size is scaled up to 296 M parameters, its performance can be further improved to 87.1%, setting a new record for ImageNet-1 K classification. In addition, we also take the proposed VOLO as pretrained models and report superior performance on downstream tasks, such as semantic segmentation. Code is available at https://github.com/sail-sg/volo.", "arxiv_id": "2106.13112", "paper_id": 1093, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2022.3206108", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4295308583", "cited_by_count": 304, "publication_date": "2022-01-01"}, {"doi": "10.1007/s11263-022-01739-w", "title": "ViTAEv2: Vision Transformer Advanced by Exploring Inductive Bias for Image Recognition and Beyond", "abstract": null, "arxiv_id": "2202.10108", "paper_id": 1121, "venue_id": 22, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s11263-022-01739-w", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4315705623", "cited_by_count": 277, "publication_date": "2023-01-12"}, {"doi": "10.1109/tpami.2024.3434373", "title": "Transformer-Based Visual Segmentation: A Survey", "abstract": "Visual segmentation seeks to partition images, video frames, or point clouds into multiple segments or groups. This technique has numerous real-world applications, such as autonomous driving, image editing, robot sensing, and medical analysis. Over the past decade, deep learning-based methods have made remarkable strides in this area. Recently, transformers, a type of neural network based on self-attention originally designed for natural language processing, have considerably surpassed previous convolutional or recurrent approaches in various vision processing tasks. Specifically, vision transformers offer robust, unified, and even simpler solutions for various segmentation tasks. This survey provides a thorough overview of transformer-based visual segmentation, summarizing recent advancements. We first review the background, encompassing problem definitions, datasets, and prior convolutional methods. Next, we summarize a meta-architecture that unifies all recent transformer-based approaches. Based on this meta-architecture, we examine various method designs, including modifications to the meta-architecture and associated applications. We also present several specific subfields, including 3D point cloud segmentation, foundation model tuning, domain-aware segmentation, efficient segmentation, and medical segmentation. Additionally, we compile and re-evaluate the reviewed methods on several well-established datasets. Finally, we identify open challenges in this field and propose directions for future research.", "arxiv_id": "2304.09854", "paper_id": 1157, "venue_id": 3, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1109/tpami.2024.3434373", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4401070841", "cited_by_count": 245, "publication_date": "2024-07-29"}, {"doi": "10.48550/arxiv.2106.03348", "title": "ViTAE: Vision Transformer Advanced by Exploring Intrinsic Inductive Bias", "abstract": "Transformers have shown great potential in various computer vision tasks owing to their strong capability in modeling long-range dependency using the self-attention mechanism. Nevertheless, vision transformers treat an image as 1D sequence of visual tokens, lacking an intrinsic inductive bias (IB) in modeling local visual structures and dealing with scale variance. Alternatively, they require large-scale training data and longer training schedules to learn the IB implicitly. In this paper, we propose a novel Vision Transformer Advanced by Exploring intrinsic IB from convolutions, ie, ViTAE. Technically, ViTAE has several spatial pyramid reduction modules to downsample and embed the input image into tokens with rich multi-scale context by using multiple convolutions with different dilation rates. In this way, it acquires an intrinsic scale invariance IB and is able to learn robust feature representation for objects at various scales. Moreover, in each transformer layer, ViTAE has a convolution block in parallel to the multi-head self-attention module, whose features are fused and fed into the feed-forward network. Consequently, it has the intrinsic locality IB and is able to learn local features and global dependencies collaboratively. Experiments on ImageNet as well as downstream tasks prove the superiority of ViTAE over the baseline transformer and concurrent works. Source code and pretrained models will be available at GitHub.", "arxiv_id": "2106.03348", "paper_id": 1187, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/2106.03348", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W3175227919", "cited_by_count": 228, "publication_date": "2021-06-07"}, {"doi": "10.1109/tpami.2023.3243048", "title": "Conformer: Local Features Coupling Global Representations for Recognition and Detection", "abstract": "With convolution operations, Convolutional Neural Networks (CNNs) are good at extracting local features but experience difficulty to capture global representations. With cascaded self-attention modules, vision transformers can capture long-distance feature dependencies but unfortunately deteriorate local feature details. In this paper, we propose a hybrid network structure, termed Conformer, to take both advantages of convolution operations and self-attention mechanisms for enhanced representation learning. Conformer roots in feature coupling of CNN local features and transformer global representations under different resolutions in an interactive fashion. Conformer adopts a dual structure so that local details and global dependencies are retained to the maximum extent. We also propose a Conformer-based detector (ConformerDet), which learns to predict and refine object proposals, by performing region-level feature coupling in an augmented cross-attention fashion. Experiments on ImageNet and MS COCO datasets validate Conformer's superiority for visual recognition and object detection, demonstrating its potential to be a general backbone network.", "arxiv_id": null, "paper_id": 1269, "venue_id": 3, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tpami.2023.3243048", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4320009770", "cited_by_count": 189, "publication_date": "2023-02-07"}, {"doi": "10.1109/mgrs.2024.3383473", "title": "Vision-Language Models in Remote Sensing: Current progress and future trends", "abstract": "The remarkable achievements of ChatGPT and Generative Pre-trained Transformer 4 (GPT-4) have sparked a wave of interest and research in the field of large language models (LLMs) for artificial general intelligence (AGI). These models provide intelligent solutions that are closer to human thinking, enabling us to use general artificial intelligence (AI) to solve problems in various applications. However, in the field of remote sensing (RS), the scientific literature on the implementation of AGI remains relatively scant. Existing AI-related research in RS focuses primarily on visual-understanding tasks while neglecting the semantic understanding of the objects and their relationships. This is where vision-LMs (VLMs) excel as they enable reasoning about images and their associated textual descriptions, allowing for a deeper understanding of the underlying semantics. VLMs can go beyond visual recognition of RS images and can model semantic relationships as well as generate natural language descriptions of the image. This makes them better suited for tasks that require both visual and textual understanding, such as image captioning and visual question answering (VQA). This article provides a comprehensive review of the research on VLMs in RS, summarizing the latest progress, highlighting current challenges, and identifying potential research opportunities. Specifically, we review the application of VLMs in mainstream RS tasks, including image captioning, text-based image generation, text-based image retrieval (TBIR), VQA, scene classification, semantic segmentation, and object detection. For each task, we analyze representative works and discuss research progress. Finally, we summarize the limitations of existing works and provide possible directions for future development. This review aims to provide a comprehensive overview of the current research progress of VLMs in RS (see Figure 1), and to inspire further research in this exciting and promising field.", "arxiv_id": "2305.05726", "paper_id": 1277, "venue_id": 299, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/mgrs.2024.3383473", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4394966885", "cited_by_count": 185, "publication_date": "2024-04-19"}, {"doi": "10.1016/j.engappai.2024.108458", "title": "The evolution of object detection methods", "abstract": "Object detection is one of the most important domains in computer vision tasks, which is an important branch of artificial intelligence. It aims at finding and locating the accurate position of objects in given pictures or videos. With the development of deep learning techniques, more powerful and robust algorithms have emerged to deal with multi-scale, high-level features to overcome the limitations of traditional pipeline of object detectors. The popularity of transformer framework enables larger capacity datasets by processing self-attention mechanism, and the object detection methods have evolved into a new era. This paper first reviews traditional object detection pipeline and brief history of deep learning, afterwards it focuses on the classification of deep learning-based object detection methods covering Convolution Neural Network based and transformer-based methods. Commonly used datasets and metrics are also covered in the next part. The Convolution Neural Network based methods mainly contain two-stage and one-stage detectors, Convolution Neural Network is the underlying structure of these methods convolutional stages are fundamental parts. Transformer-based models convert traditional object detection issues into end-to-end detection, which is widely used in dealing with images. Finally, the promising future of object detection areas are listed to show guidance on future work.", "arxiv_id": null, "paper_id": 1480, "venue_id": 249, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1016/j.engappai.2024.108458", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4395030270", "cited_by_count": 132, "publication_date": "2024-04-23"}, {"doi": "10.48550/arxiv.1609.02907", "title": "Semi-Supervised Classification with Graph Convolutional Networks", "abstract": "We present a scalable approach for semi-supervised learning on graph-structured data that is based on an efficient variant of convolutional neural networks which operate directly on graphs. We motivate the choice of our convolutional architecture via a localized first-order approximation of spectral graph convolutions. Our model scales linearly in the number of graph edges and learns hidden layer representations that encode both local graph structure and features of nodes. In a number of experiments on citation networks and on a knowledge graph dataset we demonstrate that our approach outperforms related methods by a significant margin.", "arxiv_id": "1609.02907", "paper_id": 1514, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1609.02907", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2519887557", "cited_by_count": 16820, "publication_date": "2016-09-09"}, {"doi": "10.1109/tnnls.2020.2978386", "title": "A Comprehensive Survey on Graph Neural Networks", "abstract": "Deep learning has revolutionized many machine learning tasks in recent years, ranging from image classification and video processing to speech recognition and natural language understanding. The data in these tasks are typically represented in the Euclidean space. However, there is an increasing number of applications, where data are generated from non-Euclidean domains and are represented as graphs with complex relationships and interdependency between objects. The complexity of graph data has imposed significant challenges on the existing machine learning algorithms. Recently, many studies on extending deep learning approaches for graph data have emerged. In this article, we provide a comprehensive overview of graph neural networks (GNNs) in data mining and machine learning fields. We propose a new taxonomy to divide the state-of-the-art GNNs into four categories, namely, recurrent GNNs, convolutional GNNs, graph autoencoders, and spatial-temporal GNNs. We further discuss the applications of GNNs across various domains and summarize the open-source codes, benchmark data sets, and model evaluation of GNNs. Finally, we propose potential research directions in this rapidly growing field.", "arxiv_id": "1901.00596", "paper_id": 1515, "venue_id": 60, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tnnls.2020.2978386", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2907492528", "cited_by_count": 10955, "publication_date": "2020-03-24"}, {"doi": "10.1016/j.aiopen.2021.01.001", "title": "Graph neural networks: A review of methods and applications", "abstract": "Lots of learning tasks require dealing with graph data which contains rich relation information among elements. Modeling physics systems, learning molecular fingerprints, predicting protein interface, and classifying diseases demand a model to learn from graph inputs. In other domains such as learning from non-structural data like texts and images, reasoning on extracted structures (like the dependency trees of sentences and the scene graphs of images) is an important research topic which also needs graph reasoning models. Graph neural networks (GNNs) are neural models that capture the dependence of graphs via message passing between the nodes of graphs. In recent years, variants of GNNs such as graph convolutional network (GCN), graph attention network (GAT), graph recurrent network (GRN) have demonstrated ground-breaking performances on many deep learning tasks. In this survey, we propose a general design pipeline for GNN models and discuss the variants of each component, systematically categorize the applications, and propose four open problems for future research.", "arxiv_id": "1812.08434", "paper_id": 1516, "venue_id": 217, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1016/j.aiopen.2021.01.001", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3152893301", "cited_by_count": 6860, "publication_date": "2020-01-01"}, {"doi": "10.48550/arxiv.1511.05493", "title": "Gated Graph Sequence Neural Networks", "abstract": "Graph-structured data appears frequently in domains including chemistry, natural language semantics, social networks, and knowledge bases. In this work, we study feature learning techniques for graph-structured inputs. Our starting point is previous work on Graph Neural Networks (Scarselli et al., 2009), which we modify to use gated recurrent units and modern optimization techniques and then extend to output sequences. The result is a flexible and broadly useful class of neural network models that has favorable inductive biases relative to purely sequence-based models (e.g., LSTMs) when the problem is graph-structured. We demonstrate the capabilities on some simple AI (bAbI) and graph algorithm learning tasks. We then show it achieves state-of-the-art performance on a problem from program verification, in which subgraphs need to be matched to abstract data structures.", "arxiv_id": "1511.05493", "paper_id": 1520, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1511.05493", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2244807774", "cited_by_count": 2568, "publication_date": "2015-11-17"}, {"doi": "10.3390/cancers15143608", "title": "Deep Learning for Medical Image-Based Cancer Diagnosis", "abstract": "(1) Background: The application of deep learning technology to realize cancer diagnosis based on medical images is one of the research hotspots in the field of artificial intelligence and computer vision. Due to the rapid development of deep learning methods, cancer diagnosis requires very high accuracy and timeliness as well as the inherent particularity and complexity of medical imaging. A comprehensive review of relevant studies is necessary to help readers better understand the current research status and ideas. (2) Methods: Five radiological images, including X-ray, ultrasound (US), computed tomography (CT), magnetic resonance imaging (MRI), positron emission computed tomography (PET), and histopathological images, are reviewed in this paper. The basic architecture of deep learning and classical pretrained models are comprehensively reviewed. In particular, advanced neural networks emerging in recent years, including transfer learning, ensemble learning (EL), graph neural network, and vision transformer (ViT), are introduced. Five overfitting prevention methods are summarized: batch normalization, dropout, weight initialization, and data augmentation. The application of deep learning technology in medical image-based cancer analysis is sorted out. (3) Results: Deep learning has achieved great success in medical image-based cancer diagnosis, showing good results in image classification, image reconstruction, image detection, image segmentation, image registration, and image synthesis. However, the lack of high-quality labeled datasets limits the role of deep learning and faces challenges in rare cancer diagnosis, multi-modal image fusion, model explainability, and generalization. (4) Conclusions: There is a need for more public standard databases for cancer. The pre-training model based on deep neural networks has the potential to be improved, and special attention should be paid to the research of multimodal data fusion and supervised paradigm. Technologies such as ViT, ensemble learning, and few-shot learning will bring surprises to cancer diagnosis based on medical images.", "arxiv_id": null, "paper_id": 1605, "venue_id": 382, "oa_status": "GOLD", "paper_url": "https://doi.org/10.3390/cancers15143608", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4384341111", "cited_by_count": 351, "publication_date": "2023-07-13"}, {"doi": "10.1016/j.neunet.2024.106207", "title": "A Comprehensive Survey on Deep Graph Representation Learning", "abstract": null, "arxiv_id": "2304.05055", "paper_id": 1611, "venue_id": 11, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.neunet.2024.106207", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4392203343", "cited_by_count": 344, "publication_date": "2024-02-27"}, {"doi": "10.1145/3495161", "title": "Graph Neural Networks: Taxonomy, Advances, and Trends", "abstract": "Graph neural networks provide a powerful toolkit for embedding real-world graphs into low-dimensional spaces according to specific tasks. Up to now, there have been several surveys on this topic. However, they usually lay emphasis on different angles so that the readers cannot see a panorama of the graph neural networks. This survey aims to overcome this limitation and provide a systematic and comprehensive review on the graph neural networks. First of all, we provide a novel taxonomy for the graph neural networks, and then refer to up to 327 relevant literatures to show the panorama of the graph neural networks. All of them are classified into the corresponding categories. In order to drive the graph neural networks into a new stage, we summarize four future research directions so as to overcome the challenges faced. It is expected that more and more scholars can understand and exploit the graph neural networks and use them in their research community.", "arxiv_id": "2012.08752", "paper_id": 1784, "venue_id": 175, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1145/3495161", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3111440465", "cited_by_count": 161, "publication_date": "2022-01-10"}, {"doi": "10.1038/nature14539", "title": "Deep learning", "abstract": null, "arxiv_id": null, "paper_id": 2213, "venue_id": 2, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1038/nature14539", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2919115771", "cited_by_count": 83956, "publication_date": "2015-05-26"}, {"doi": "10.1109/tpami.2016.2577031", "title": "Faster R-CNN: Towards Real-Time Object Detection with Region Proposal Networks", "abstract": "State-of-the-art object detection networks depend on region proposal algorithms to hypothesize object locations. Advances like SPPnet [1] and Fast R-CNN [2] have reduced the running time of these detection networks, exposing region proposal computation as a bottleneck. In this work, we introduce a Region Proposal Network (RPN) that shares full-image convolutional features with the detection network, thus enabling nearly cost-free region proposals. An RPN is a fully convolutional network that simultaneously predicts object bounds and objectness scores at each position. The RPN is trained end-to-end to generate high-quality region proposals, which are used by Fast R-CNN for detection. We further merge RPN and Fast R-CNN into a single network by sharing their convolutional features-using the recently popular terminology of neural networks with 'attention' mechanisms, the RPN component tells the unified network where to look. For the very deep VGG-16 model [3] , our detection system has a frame rate of 5 fps (including all steps) on a GPU, while achieving state-of-the-art object detection accuracy on PASCAL VOC 2007, 2012, and MS COCO datasets with only 300 proposals per image. In ILSVRC and COCO 2015 competitions, Faster R-CNN and RPN are the foundations of the 1st-place winning entries in several tracks. Code has been made publicly available.", "arxiv_id": "1506.01497", "paper_id": 2214, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2016.2577031", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W639708223", "cited_by_count": 70700, "publication_date": "2016-06-06"}, {"doi": "10.1007/s11263-015-0816-y", "title": "ImageNet Large Scale Visual Recognition Challenge", "abstract": null, "arxiv_id": null, "paper_id": 2215, "venue_id": 22, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1007/s11263-015-0816-y", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2117539524", "cited_by_count": 38976, "publication_date": "2015-04-10"}, {"doi": "10.48550/arxiv.1502.03167", "title": "Batch Normalization: Accelerating Deep Network Training by Reducing Internal Covariate Shift", "abstract": "Training Deep Neural Networks is complicated by the fact that the distribution of each layer's inputs changes during training, as the parameters of the previous layers change. This slows down the training by requiring lower learning rates and careful parameter initialization, and makes it notoriously hard to train models with saturating nonlinearities. We refer to this phenomenon as internal covariate shift, and address the problem by normalizing layer inputs. Our method draws its strength from making normalization a part of the model architecture and performing the normalization for each training mini-batch. Batch Normalization allows us to use much higher learning rates and be less careful about initialization. It also acts as a regularizer, in some cases eliminating the need for Dropout. Applied to a state-of-the-art image classification model, Batch Normalization achieves the same accuracy with 14 times fewer training steps, and beats the original model by a significant margin. Using an ensemble of batch-normalized networks, we improve upon the best published result on ImageNet classification: reaching 4.9% top-5 validation error (and 4.8% test error), exceeding the accuracy of human raters.", "arxiv_id": "1502.03167", "paper_id": 2216, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1502.03167", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W1836465849", "cited_by_count": 27828, "publication_date": "2015-02-11"}, {"doi": "10.48550/arxiv.2010.11929", "title": "An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale", "abstract": "While the Transformer architecture has become the de-facto standard for natural language processing tasks, its applications to computer vision remain limited. In vision, attention is either applied in conjunction with convolutional networks, or used to replace certain components of convolutional networks while keeping their overall structure in place. We show that this reliance on CNNs is not necessary and a pure transformer applied directly to sequences of image patches can perform very well on image classification tasks. When pre-trained on large amounts of data and transferred to multiple mid-sized or small image recognition benchmarks (ImageNet, CIFAR-100, VTAB, etc.), Vision Transformer (ViT) attains excellent results compared to state-of-the-art convolutional networks while requiring substantially fewer computational resources to train.", "arxiv_id": "2010.11929", "paper_id": 2217, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/2010.11929", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W3094502228", "cited_by_count": 21342, "publication_date": "2020-10-22"}, {"doi": "10.48550/arxiv.1704.04861", "title": "MobileNets: Efficient Convolutional Neural Networks for Mobile Vision Applications", "abstract": "We present a class of efficient models called MobileNets for mobile and embedded vision applications. MobileNets are based on a streamlined architecture that uses depth-wise separable convolutions to build light weight deep neural networks. We introduce two simple global hyper-parameters that efficiently trade off between latency and accuracy. These hyper-parameters allow the model builder to choose the right sized model for their application based on the constraints of the problem. We present extensive experiments on resource and accuracy tradeoffs and show strong performance compared to other popular models on ImageNet classification. We then demonstrate the effectiveness of MobileNets across a wide range of applications and use cases including object detection, finegrain classification, face attributes and large scale geo-localization.", "arxiv_id": "1704.04861", "paper_id": 2218, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1704.04861", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2612445135", "cited_by_count": 19008, "publication_date": "2017-04-17"}, {"doi": "10.57702/o9raffed", "title": "Batch Normalization: Accelerating Deep Network Training by Reducing Internal Covariate Shift", "abstract": "Training Deep Neural Networks is complicated by the fact that the distribution of each layer's inputs changes during training, as the parameters of the previous layers change. This slows down the training by requiring lower learning rates and careful parameter initialization, and makes it notoriously hard to train models with saturating nonlinearities. We refer to this phenomenon as internal covariate shift, and address the problem by normalizing layer inputs. Our method draws its strength from making normalization a part of the model architecture and performing the normalization for each training mini-batch. Batch Normalization allows us to use much higher learning rates and be less careful about initialization. It also acts as a regularizer, in some cases eliminating the need for Dropout. Applied to a state-of-the-art image classification model, Batch Normalization achieves the same accuracy with 14 times fewer training steps, and beats the original model by a significant margin. Using an ensemble of batch-normalized networks, we improve upon the best published result on ImageNet classification: reaching 4.9% top-5 validation error (and 4.8% test error), exceeding the accuracy of human raters.", "arxiv_id": null, "paper_id": 2220, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://export.arxiv.org/pdf/1502.03167", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2949117887", "cited_by_count": 14211, "publication_date": "2024-01-01"}, {"doi": "10.1109/tpami.2015.2389824", "title": "Spatial Pyramid Pooling in Deep Convolutional Networks for Visual Recognition", "abstract": "Existing deep convolutional neural networks (CNNs) require a fixed-size (e.g., 224 × 224) input image. This requirement is \"artificial\" and may reduce the recognition accuracy for the images or sub-images of an arbitrary size/scale. In this work, we equip the networks with another pooling strategy, \"spatial pyramid pooling\", to eliminate the above requirement. The new network structure, called SPP-net, can generate a fixed-length representation regardless of image size/scale. Pyramid pooling is also robust to object deformations. With these advantages, SPP-net should in general improve all CNN-based image classification methods. On the ImageNet 2012 dataset, we demonstrate that SPP-net boosts the accuracy of a variety of CNN architectures despite their different designs. On the Pascal VOC 2007 and Caltech101 datasets, SPP-net achieves state-of-the-art classification results using a single full-image representation and no fine-tuning. The power of SPP-net is also significant in object detection. Using SPP-net, we compute the feature maps from the entire image only once, and then pool features in arbitrary regions (sub-images) to generate fixed-length representations for training the detectors. This method avoids repeatedly computing the convolutional features. In processing test images, our method is 24-102 × faster than the R-CNN method, while achieving better or comparable accuracy on Pascal VOC 2007. In ImageNet Large Scale Visual Recognition Challenge (ILSVRC) 2014, our methods rank #2 in object detection and #3 in image classification among all 38 teams. This manuscript also introduces the improvement made for this competition.", "arxiv_id": null, "paper_id": 2222, "venue_id": 3, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tpami.2015.2389824", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2109255472", "cited_by_count": 11954, "publication_date": "2015-01-09"}, {"doi": "10.48550/arxiv.2004.10934", "title": "YOLOv4: Optimal Speed and Accuracy of Object Detection", "abstract": "There are a huge number of features which are said to improve Convolutional Neural Network (CNN) accuracy. Practical testing of combinations of such features on large datasets, and theoretical justification of the result, is required. Some features operate on certain models exclusively and for certain problems exclusively, or only for small-scale datasets; while some features, such as batch-normalization and residual-connections, are applicable to the majority of models, tasks, and datasets. We assume that such universal features include Weighted-Residual-Connections (WRC), Cross-Stage-Partial-connections (CSP), Cross mini-Batch Normalization (CmBN), Self-adversarial-training (SAT) and Mish-activation. We use new features: WRC, CSP, CmBN, SAT, Mish activation, Mosaic data augmentation, CmBN, DropBlock regularization, and CIoU loss, and combine some of them to achieve state-of-the-art results: 43.5% AP (65.7% AP50) for the MS COCO dataset at a realtime speed of ~65 FPS on Tesla V100. Source code is at https://github.com/AlexeyAB/darknet", "arxiv_id": "2004.10934", "paper_id": 2225, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/2004.10934", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W3018757597", "cited_by_count": 10298, "publication_date": "2020-04-23"}, {"doi": "10.1109/tnnls.2018.2876865", "title": "Object Detection With Deep Learning: A Review", "abstract": "Due to object detection's close relationship with video analysis and image understanding, it has attracted much research attention in recent years. Traditional object detection methods are built on handcrafted features and shallow trainable architectures. Their performance easily stagnates by constructing complex ensembles that combine multiple low-level image features with high-level context from object detectors and scene classifiers. With the rapid development in deep learning, more powerful tools, which are able to learn semantic, high-level, deeper features, are introduced to address the problems existing in traditional architectures. These models behave differently in network architecture, training strategy, and optimization function. In this paper, we provide a review of deep learning-based object detection frameworks. Our review begins with a brief introduction on the history of deep learning and its representative tool, namely, the convolutional neural network. Then, we focus on typical generic object detection architectures along with some modifications and useful tricks to improve detection performance further. As distinct specific detection tasks exhibit different characteristics, we also briefly survey several specific tasks, including salient object detection, face detection, and pedestrian detection. Experimental analyses are also provided to compare various methods and draw some meaningful conclusions. Finally, several promising directions and tasks are provided to serve as guidelines for future work in both object detection and relevant neural network-based learning systems.", "arxiv_id": "1807.05511", "paper_id": 2232, "venue_id": 60, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tnnls.2018.2876865", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2884367402", "cited_by_count": 5539, "publication_date": "2019-01-28"}, {"doi": "10.1109/jproc.2023.3238524", "title": "Object Detection in 20 Years: A Survey", "abstract": "Object detection, as of one the most fundamental and challenging problems in computer vision, has received great attention in recent years. Over the past two decades, we have seen a rapid technological evolution of object detection and its profound impact on the entire computer vision field. If we consider today’s object detection technique as a revolution driven by deep learning, then, back in the 1990s, we would see the ingenious thinking and long-term perspective design of early computer vision. This article extensively reviews this fast-moving research field in the light of technical evolution, spanning over a quarter-century’s time (from the 1990s to 2022). A number of topics have been covered in this article, including the milestone detectors in history, detection datasets, metrics, fundamental building blocks of the detection system, speedup techniques, and recent state-of-the-art detection methods.", "arxiv_id": "1905.05055", "paper_id": 2244, "venue_id": 12, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/jproc.2023.3238524", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4320002812", "cited_by_count": 3673, "publication_date": "2023-01-27"}, {"doi": "10.1162/neco_a_00990", "title": "Deep Convolutional Neural Networks for Image Classification: A Comprehensive Review", "abstract": "Convolutional neural networks (CNNs) have been applied to visual tasks since the late 1980s. However, despite a few scattered applications, they were dormant until the mid-2000s when developments in computing power and the advent of large amounts of labeled data, supplemented by improved algorithms, contributed to their advancement and brought them to the forefront of a neural network renaissance that has seen rapid progression since 2012. In this review, which focuses on the application of CNNs to image classification tasks, we cover their development, from their predecessors up to recent state-of-the-art deep learning systems. Along the way, we analyze (1) their early successes, (2) their role in the deep learning renaissance, (3) selected symbolic works that have contributed to their recent popularity, and (4) several improvement attempts by reviewing contributions and challenges of over 300 publications. We also introduce some of their current trends and remaining challenges.", "arxiv_id": null, "paper_id": 2245, "venue_id": 46, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1162/neco_a_00990", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2622826443", "cited_by_count": 3503, "publication_date": "2017-06-09"}, {"doi": "10.1109/tpami.2019.2938758", "title": "Res2Net: A New Multi-Scale Backbone Architecture", "abstract": "Representing features at multiple scales is of great importance for numerous vision tasks. Recent advances in backbone convolutional neural networks (CNNs) continually demonstrate stronger multi-scale representation ability, leading to consistent performance gains on a wide range of applications. However, most existing methods represent the multi-scale features in a layer-wise manner. In this paper, we propose a novel building block for CNNs, namely Res2Net, by constructing hierarchical residual-like connections within one single residual block. The Res2Net represents multi-scale features at a granular level and increases the range of receptive fields for each network layer. The proposed Res2Net block can be plugged into the state-of-the-art backbone CNN models, e.g., ResNet, ResNeXt, and DLA. We evaluate the Res2Net block on all these models and demonstrate consistent performance gains over baseline models on widely-used datasets, e.g., CIFAR-100 and ImageNet. Further ablation studies and experimental results on representative computer vision tasks, i.e., object detection, class activation mapping, and salient object detection, further verify the superiority of the Res2Net over the state-of-the-art baseline methods. The source code and trained models are available on https://mmcheng.net/res2net/.", "arxiv_id": "1904.01169", "paper_id": 2248, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2019.2938758", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2928165649", "cited_by_count": 3400, "publication_date": "2019-08-30"}, {"doi": "10.3390/make5040083", "title": "A Comprehensive Review of YOLO Architectures in Computer Vision: From YOLOv1 to YOLOv8 and YOLO-NAS", "abstract": "YOLO has become a central real-time object detection system for robotics, driverless cars, and video monitoring applications. We present a comprehensive analysis of YOLO’s evolution, examining the innovations and contributions in each iteration from the original YOLO up to YOLOv8, YOLO-NAS, and YOLO with transformers. We start by describing the standard metrics and postprocessing; then, we discuss the major changes in network architecture and training tricks for each model. Finally, we summarize the essential lessons from YOLO’s development and provide a perspective on its future, highlighting potential research directions to enhance real-time object detection systems.", "arxiv_id": "2304.00501", "paper_id": 2254, "venue_id": 473, "oa_status": "GOLD", "paper_url": "https://doi.org/10.3390/make5040083", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4388823657", "cited_by_count": 3099, "publication_date": "2023-11-20"}, {"doi": "10.1007/s11263-019-01247-4", "title": "Deep Learning for Generic Object Detection: A Survey", "abstract": "Abstract Object detection, one of the most fundamental and challenging problems in computer vision, seeks to locate object instances from a large number of predefined categories in natural images. Deep learning techniques have emerged as a powerful strategy for learning feature representations directly from data and have led to remarkable breakthroughs in the field of generic object detection. Given this period of rapid evolution, the goal of this paper is to provide a comprehensive survey of the recent achievements in this field brought about by deep learning techniques. More than 300 research contributions are included in this survey, covering many aspects of generic object detection: detection frameworks, object feature representation, object proposal generation, context modeling, training strategies, and evaluation metrics. We finish the survey by identifying promising directions for future research.", "arxiv_id": "1809.02165", "paper_id": 2256, "venue_id": 22, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1007/s11263-019-01247-4", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2988916019", "cited_by_count": 2957, "publication_date": "2019-10-31"}, {"doi": "10.1016/j.neucom.2015.09.116", "title": "Deep learning for visual understanding: A review", "abstract": null, "arxiv_id": null, "paper_id": 2263, "venue_id": 108, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.neucom.2015.09.116", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2176950688", "cited_by_count": 2503, "publication_date": "2015-11-26"}, {"doi": "10.1016/j.isprsjprs.2019.11.023", "title": "Object detection in optical remote sensing images: A survey and a new benchmark", "abstract": null, "arxiv_id": "1909.00133", "paper_id": 2270, "venue_id": 277, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.isprsjprs.2019.11.023", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2992240579", "cited_by_count": 2301, "publication_date": "2019-12-04"}, {"doi": "10.1007/s11263-020-01316-z", "title": "The Open Images Dataset V4: Unified image classification, object detection, and visual relationship detection at scale", "abstract": "We present Open Images V4, a dataset of 9.2M images with unified annotations for image classification, object detection and visual relationship detection. The images have a Creative Commons Attribution license that allows to share and adapt the material, and they have been collected from Flickr without a predefined list of class names or tags, leading to natural class statistics and avoiding an initial design bias. Open Images V4 offers large scale across several dimensions: 30.1M image-level labels for 19.8k concepts, 15.4M bounding boxes for 600 object classes, and 375k visual relationship annotations involving 57 classes. For object detection in particular, we provide 15x more bounding boxes than the next largest datasets (15.4M boxes on 1.9M images). The images often show complex scenes with several objects (8 annotated objects per image on average). We annotated visual relationships between them, which support visual relationship detection, an emerging task that requires structured reasoning. We provide in-depth comprehensive statistics about the dataset, we validate the quality of the annotations, we study how the performance of several modern models evolves with increasing amounts of training data, and we demonstrate two applications made possible by having unified annotations of multiple types coexisting in the same images. We hope that the scale, quality, and variety of Open Images V4 will foster further research and innovation even beyond the areas of image classification, object detection, and visual relationship detection.", "arxiv_id": "1811.00982", "paper_id": 2280, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1811.00982", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W4288083516", "cited_by_count": 1914, "publication_date": "2018-11-02"}, {"doi": "10.1109/access.2019.2939201", "title": "A Survey of Deep Learning-Based Object Detection", "abstract": "Object detection is one of the most important and challenging branches of computer vision, which has been widely applied in people’s life, such as monitoring security, autonomous driving and so on, with the purpose of locating instances of semantic objects of a certain class. With the rapid development of deep learning algorithms for detection tasks, the performance of object detectors has been greatly improved. In order to understand the main development status of object detection pipeline thoroughly and deeply, in this survey, we analyze the methods of existing typical detection models and describe the benchmark datasets at first. Afterwards and primarily, we provide a comprehensive overview of a variety of object detection methods in a systematic manner, covering the one-stage and two-stage detectors. Moreover, we list the traditional and new applications. Some representative branches of object detection are analyzed as well. Finally, we discuss the architecture of exploiting these object detection methods to build an effective and efficient system and point out a set of development trends to better follow the state-of-the-art algorithms and further research.", "arxiv_id": "1907.09408", "paper_id": 2302, "venue_id": 106, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/access.2019.2939201", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2972006294", "cited_by_count": 1360, "publication_date": "2019-01-01"}, {"doi": "10.1007/s13748-019-00203-0", "title": "Convolutional neural network: a review of models, methodologies and applications to object detection", "abstract": null, "arxiv_id": null, "paper_id": 2331, "venue_id": 477, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1007/s13748-019-00203-0", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2996367417", "cited_by_count": 1117, "publication_date": "2019-12-20"}, {"doi": "10.1016/j.neucom.2020.01.085", "title": "Recent advances in deep learning for object detection", "abstract": null, "arxiv_id": "1908.03673", "paper_id": 2338, "venue_id": 108, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.neucom.2020.01.085", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3001083904", "cited_by_count": 1045, "publication_date": "2020-01-24"}, {"doi": "10.1016/j.dsp.2022.103514", "title": "A survey of modern deep learning based object detection models", "abstract": null, "arxiv_id": "2104.11892", "paper_id": 2346, "venue_id": 478, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.dsp.2022.103514", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3159196909", "cited_by_count": 983, "publication_date": "2022-03-08"}, {"doi": "10.1007/s10462-020-09854-1", "title": "Deep semantic segmentation of natural and medical images: a review", "abstract": null, "arxiv_id": "1910.07655", "paper_id": 2373, "venue_id": 220, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s10462-020-09854-1", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2981227223", "cited_by_count": 878, "publication_date": "2020-06-13"}, {"doi": "10.1016/j.mlwa.2021.100134", "title": "Deep learning in computer vision: A critical review of emerging techniques and application scenarios", "abstract": "Deep learning has been overwhelmingly successful in computer vision (CV), natural language processing, and video/speech recognition. In this paper, our focus is on CV. We provide a critical review of recent achievements in terms of techniques and applications. We identify eight emerging techniques, investigate their origins and updates, and finally emphasize their applications in four key scenarios, including recognition, visual tracking, semantic segmentation, and image restoration. We recognize three development stages in the past decade and emphasize research trends for future works. The summarizations, knowledge accumulations, and creations could benefit researchers in the academia and participators in the CV industries.", "arxiv_id": null, "paper_id": 2400, "venue_id": 302, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1016/j.mlwa.2021.100134", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3195997474", "cited_by_count": 754, "publication_date": "2021-08-13"}, {"doi": "10.1109/tpami.2023.3290594", "title": "Towards Large-Scale Small Object Detection: Survey and Benchmarks", "abstract": "With the rise of deep convolutional neural networks, object detection has achieved prominent advances in past years. However, such prosperity could not camouflage the unsatisfactory situation of Small Object Detection (SOD), one of the notoriously challenging tasks in computer vision, owing to the poor visual appearance and noisy representation caused by the intrinsic structure of small targets. In addition, large-scale dataset for benchmarking small object detection methods remains a bottleneck. In this paper, we first conduct a thorough review of small object detection. Then, to catalyze the development of SOD, we construct two large-scale Small Object Detection dAtasets (SODA), SODA-D and SODA-A, which focus on the Driving and Aerial scenarios respectively. SODA-D includes 24828 high-quality traffic images and 278433 instances of nine categories. For SODA-A, we harvest 2513 high resolution aerial images and annotate 872069 instances over nine classes. The proposed datasets, as we know, are the first-ever attempt to large-scale benchmarks with a vast collection of exhaustively annotated instances tailored for multi-category SOD. Finally, we evaluate the performance of mainstream methods on SODA. We expect the released benchmarks could facilitate the development of SOD and spawn more breakthroughs in this field.", "arxiv_id": "2207.14096", "paper_id": 2423, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2023.3290594", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4382568144", "cited_by_count": 677, "publication_date": "2023-01-01"}, {"doi": "10.1109/tpami.2020.2981890", "title": "Imbalance Problems in Object Detection: A Review", "abstract": "In this paper, we present a comprehensive review of the imbalance problems in object detection. To analyze the problems in a systematic manner, we introduce a problem-based taxonomy. Following this taxonomy, we discuss each problem in depth and present a unifying yet critical perspective on the solutions in the literature. In addition, we identify major open issues regarding the existing imbalance problems as well as imbalance problems that have not been discussed before. Moreover, in order to keep our review up to date, we provide an accompanying webpage which catalogs papers addressing imbalance problems, according to our problem-based taxonomy. Researchers can track newer studies on this webpage available at: https://github.com/kemaloksuz/ObjectDetectionImbalance.", "arxiv_id": "1909.00169", "paper_id": 2460, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2020.2981890", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2972231924", "cited_by_count": 601, "publication_date": "2020-03-19"}, {"doi": "10.1007/s11042-020-08976-6", "title": "A review of object detection based on deep learning", "abstract": null, "arxiv_id": null, "paper_id": 2470, "venue_id": 150, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1007/s11042-020-08976-6", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W3034745255", "cited_by_count": 583, "publication_date": "2020-06-12"}, {"doi": "10.1016/j.eswa.2023.121352", "title": "Large Separable Kernel Attention: Rethinking the Large Kernel Attention design in CNN", "abstract": null, "arxiv_id": null, "paper_id": 2479, "venue_id": 197, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.eswa.2023.121352", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4386319016", "cited_by_count": 574, "publication_date": "2023-08-31"}, {"doi": "10.48550/arxiv.1811.00982", "title": "The Open Images Dataset V4: Unified image classification, object detection, and visual relationship detection at scale", "abstract": "We present Open Images V4, a dataset of 9.2M images with unified annotations for image classification, object detection and visual relationship detection. The images have a Creative Commons Attribution license that allows to share and adapt the material, and they have been collected from Flickr without a predefined list of class names or tags, leading to natural class statistics and avoiding an initial design bias. Open Images V4 offers large scale across several dimensions: 30.1M image-level labels for 19.8k concepts, 15.4M bounding boxes for 600 object classes, and 375k visual relationship annotations involving 57 classes. For object detection in particular, we provide 15x more bounding boxes than the next largest datasets (15.4M boxes on 1.9M images). The images often show complex scenes with several objects (8 annotated objects per image on average). We annotated visual relationships between them, which support visual relationship detection, an emerging task that requires structured reasoning. We provide in-depth comprehensive statistics about the dataset, we validate the quality of the annotations, we study how the performance of several modern models evolves with increasing amounts of training data, and we demonstrate two applications made possible by having unified annotations of multiple types coexisting in the same images. We hope that the scale, quality, and variety of Open Images V4 will foster further research and innovation even beyond the areas of image classification, object detection, and visual relationship detection.", "arxiv_id": null, "paper_id": 2481, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1811.00982", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W3121480429", "cited_by_count": 573, "publication_date": "2018-11-02"}, {"doi": "10.1007/s13735-020-00195-x", "title": "A survey on instance segmentation: state of the art", "abstract": null, "arxiv_id": "2007.00047", "paper_id": 2488, "venue_id": 483, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s13735-020-00195-x", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3039368862", "cited_by_count": 566, "publication_date": "2020-07-03"}, {"doi": "10.1016/j.neucom.2019.02.003", "title": "Survey on semantic segmentation using deep learning techniques", "abstract": null, "arxiv_id": null, "paper_id": 2490, "venue_id": 108, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1016/j.neucom.2019.02.003", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2912327653", "cited_by_count": 560, "publication_date": "2019-02-10"}, {"doi": "10.1016/j.dsp.2022.103812", "title": "A comprehensive review of object detection with deep learning", "abstract": null, "arxiv_id": null, "paper_id": 2527, "venue_id": 478, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.dsp.2022.103812", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4308516693", "cited_by_count": 510, "publication_date": "2022-11-08"}, {"doi": "10.1016/j.ins.2020.02.067", "title": "DC-SPP-YOLO: Dense connection and spatial pyramid pooling based YOLO for object detection", "abstract": null, "arxiv_id": "1903.08589", "paper_id": 2653, "venue_id": 344, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.ins.2020.02.067", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2923837612", "cited_by_count": 379, "publication_date": "2020-03-02"}, {"doi": null, "title": "The Open Images Dataset V4", "abstract": "We present Open Images V4, a dataset of 9.2M images with unified annotations for image classification, object detection and visual relationship detection. The images have a Creative Commons Attribution license that allows to share and adapt the material, and they have been collected from Flickr without a predefined list of class names or tags, leading to natural class statistics and avoiding an initial design bias. Open Images V4 offers large scale across several dimensions: 30.1M image-level labels for 19.8k concepts, 15.4M bounding boxes for 600 object classes, and 375k visual relationship annotations involving 57 classes. For object detection in particular, we provide $$15\\times $$ more bounding boxes than the next largest datasets (15.4M boxes on 1.9M images). The images often show complex scenes with several objects (8 annotated objects per image on average). We annotated visual relationships between them, which support visual relationship detection, an emerging task that requires structured reasoning. We provide in-depth comprehensive statistics about the dataset, we validate the quality of the annotations, we study how the performance of several modern models evolves with increasing amounts of training data, and we demonstrate two applications made possible by having unified annotations of multiple types coexisting in the same images. We hope that the scale, quality, and variety of Open Images V4 will foster further research and innovation even beyond the areas of image classification, object detection, and visual relationship detection.", "arxiv_id": null, "paper_id": 2665, "venue_id": 22, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1007/s11263-020-01316-z", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2899505139", "cited_by_count": 368, "publication_date": "2020-03-13"}, {"doi": "10.3390/rs12101667", "title": "Object Detection and Image Segmentation with Deep Learning on Earth Observation Data: A Review-Part I: Evolution and Recent Trends", "abstract": "Deep learning (DL) has great influence on large parts of science and increasingly established itself as an adaptive method for new challenges in the field of Earth observation (EO). Nevertheless, the entry barriers for EO researchers are high due to the dense and rapidly developing field mainly driven by advances in computer vision (CV). To lower the barriers for researchers in EO, this review gives an overview of the evolution of DL with a focus on image segmentation and object detection in convolutional neural networks (CNN). The survey starts in 2012, when a CNN set new standards in image recognition, and lasts until late 2019. Thereby, we highlight the connections between the most important CNN architectures and cornerstones coming from CV in order to alleviate the evaluation of modern DL models. Furthermore, we briefly outline the evolution of the most popular DL frameworks and provide a summary of datasets in EO. By discussing well performing DL architectures on these datasets as well as reflecting on advances made in CV and their impact on future research in EO, we narrow the gap between the reviewed, theoretical concepts from CV and practical application in EO.", "arxiv_id": null, "paper_id": 2668, "venue_id": 279, "oa_status": "GOLD", "paper_url": "https://doi.org/10.3390/rs12101667", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3027542479", "cited_by_count": 367, "publication_date": "2020-05-22"}, {"doi": "10.1016/j.neucom.2023.01.056", "title": "A systematic review and analysis of deep learning-based underwater object detection", "abstract": null, "arxiv_id": null, "paper_id": 2687, "venue_id": 108, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.neucom.2023.01.056", "work_type": "REVIEW", "open_access": true, "openalex_id": "W4315498985", "cited_by_count": 326, "publication_date": "2023-01-11"}, {"doi": "10.1109/access.2023.3266093", "title": "Object Detection Using Deep Learning, CNNs and Vision Transformers: A Review", "abstract": "Detecting objects remains one of computer vision and image understanding applications’ most fundamental and challenging aspects. Significant advances in object detection have been achieved through improved object representation and the use of deep neural network models. This paper examines more closely how object detection has evolved in the era of deep learning over the past years. We present a literature review on various state-of-the-art object detection algorithms and the underlying concepts behind these methods. We classify these methods into three main groups: anchor-based, anchor-free, and transformer-based detectors. Those approaches are distinct in the way they identify objects in the image. We discuss the insights behind these algorithms and experimental analyses to compare quality metrics, speed/accuracy tradeoffs, and training methodologies. The survey compares the major convolutional neural networks for object detection. It also covers the strengths and limitations of each object detector model and draws significant conclusions. We provide simple graphical illustrations summarising the development of object detection methods under deep learning. Finally, we identify where future research will be conducted.", "arxiv_id": null, "paper_id": 2690, "venue_id": 106, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/access.2023.3266093", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4364323147", "cited_by_count": 323, "publication_date": "2023-01-01"}, {"doi": "10.1109/jstars.2023.3339235", "title": "Small Object Detection Algorithm Based on Improved YOLOv8 for Remote Sensing", "abstract": "Due to the limitations of small targets in remote sensing images such as background noise, poor information, and so on, the results of commonly used detection algorithms in small target detection is not satisfactory. To improve the accuracy of detection results, we develop an improved algorithm based on YOLOv8, called LAR-YOLOv8. First, in the feature extraction network, the local module is enhanced by using the dual-branch architecture attention mechanism, while the vision transformer block is used to maximize the representation of the feature map. Second, an attention-guided bi-directional feature pyramid network is designed to generate more discriminative information by efficiently extracting feature from the shallow network through a dynamic sparse attention mechanism, and adding top-down paths to guide the subsequent network modules for feature fusion. Finally, the RIOU loss function is proposed to avoid the failure of the loss function and improve the shape consistency between the predicted and ground truth box. Experimental results on NWPU VHR-10, RSOD and CARPK datasets verify that LAR-YOLOv8 achieves satisfactory results in terms of mAP (small), mAP, model parameters and FPS, and can prove that our modifications made to the original YOLOv8 model are effective.", "arxiv_id": null, "paper_id": 2692, "venue_id": 119, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/jstars.2023.3339235", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4389352554", "cited_by_count": 312, "publication_date": "2023-12-05"}, {"doi": "10.1109/tpami.2023.3292030", "title": "Sparse R-CNN: An End-to-End Framework for Object Detection", "abstract": "Object detection serves as one of most fundamental computer vision tasks. Existing works on object detection heavily rely on dense object candidates, such as k anchor boxes pre-defined on all grids of an image feature map of size H×W. In this paper, we present Sparse R-CNN, a very simple and sparse method for object detection in images. In our method, a fixed sparse set of learned object proposals ( N in total) are provided to the object recognition head to perform classification and localization. By replacing HWk (up to hundreds of thousands) hand-designed object candidates with N (e.g., 100) learnable proposals, Sparse R-CNN makes all efforts related to object candidates design and one-to-many label assignment completely obsolete. More importantly, Sparse R-CNN directly outputs predictions without the non-maximum suppression (NMS) post-processing procedure. Thus, it establishes an end-to-end object detection framework. Sparse R-CNN demonstrates highly competitive accuracy, run-time and training convergence performance with the well-established detector baselines on the challenging COCO dataset and CrowdHuman dataset. We hope that our work can inspire re-thinking the convention of dense prior in object detectors and designing new high-performance detectors.", "arxiv_id": null, "paper_id": 2823, "venue_id": 3, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tpami.2023.3292030", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4383113375", "cited_by_count": 132, "publication_date": "2023-07-04"}, {"doi": "10.1109/tpami.2023.3303397", "title": "CycleMLP: A MLP-Like Architecture for Dense Visual Predictions", "abstract": "This article presents a simple yet effective multilayer perceptron (MLP) architecture, namely CycleMLP, which is a versatile neural backbone network capable of solving various tasks of dense visual predictions such as object detection, segmentation, and human pose estimation. Compared to recent advanced MLP architectures such as MLP-Mixer (Tolstikhin et al. 2021), ResMLP (Touvron et al. 2021), and gMLP (Liu et al. 2021), whose architectures are sensitive to image size and are infeasible in dense prediction tasks, CycleMLP has two appealing advantages: 1) CycleMLP can cope with various spatial sizes of images; 2) CycleMLP achieves linear computational complexity with respect to the image size by using local windows. In contrast, previous MLPs have$O(N^{2})$computational complexity due to their full connections in space. 3) The relationship between convolution, multi-head self-attention in Transformer, and CycleMLP are discussed through an intuitive theoretical analysis. We build a family of models that can surpass state-of-the-art MLP and Transformer models e.g., Swin Transformer (Liu et al. 2021), while using fewer parameters and FLOPs. CycleMLP expands the MLP-like models’ applicability, making them versatile backbone networks that achieve competitive results on dense prediction tasks For example, CycleMLP-Tiny outperforms Swin-Tiny by 1.3% mIoU on ADE20 K dataset with fewer FLOPs. Moreover, CycleMLP also shows excellent zero-shot robustness on ImageNet-C dataset.", "arxiv_id": null, "paper_id": 2842, "venue_id": 3, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tpami.2023.3303397", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4385656546", "cited_by_count": 124, "publication_date": "2023-08-08"}, {"doi": "10.1109/tpami.2023.3263824", "title": "GFNet: Global Filter Networks for Visual Recognition", "abstract": "Recent advances in self-attention and pure multi-layer perceptrons (MLP) models for vision have shown great potential in achieving promising performance with fewer inductive biases. These models are generally based on learning interaction among spatial locations from raw data. The complexity of self-attention and MLP grows quadratically as the image size increases, which makes these models hard to scale up when high-resolution features are required. In this paper, we present the Global Filter Network (GFNet), a conceptually simple yet computationally efficient architecture, that learns long-term spatial dependencies in the frequency domain with log-linear complexity. Our architecture replaces the self-attention layer in vision Transformers with three key operations: a 2D discrete Fourier transform, an element-wise multiplication between frequency-domain features and learnable global filters, and a 2D inverse Fourier transform. Based on this basic design, we develop a series of isotropic models with a Transformer-style simple architecture and CNN-style hierarchical models with better performance. Isotropic GFNet models exhibit favorable accuracy/complexity trade-offs compared to recent vision Transformers and pure MLP models. Hierarchical GFNet models can inherit successful designs in CNNs and be easily scaled up with larger model sizes and more training data, showing strong performance on both image classification (e.g., 85.0% top-1 accuracy on ImageNet-1 k without any extra data or supervision, and 87.4% accuracy with ImageNet-21 k pre-training) and dense prediction tasks (e.g., 54.3 mIoU on ADE20 k val). Our results demonstrate that GFNet can be a very competitive alternative to Transformer-based models and CNNs in terms of efficiency, generalization ability and robustness. Code is available at https://github.com/raoyongming/GFNet.", "arxiv_id": null, "paper_id": 2880, "venue_id": 3, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tpami.2023.3263824", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4362496454", "cited_by_count": 116, "publication_date": "2023-04-03"}, {"doi": "10.1109/tits.2023.3258683", "title": "Object Detection in Traffic Videos: A Survey", "abstract": "Traffic video analytics has become one of the core components in the evolution of transportation systems. Artificially intelligent traffic management systems apply computer vision techniques to alleviate the monotony of manually monitoring the video feed from surveillance cameras. Locating the objects of interest is the most crucial step in the pipeline of such video analytics systems. An abundance of research has been conducted to find the location of the targets in traffic scenes. This paper presents a comprehensive review of different algorithms used for object detection in traffic surveillance applications in addition to the recent trends and future directions. Based on the approaches used in the related studies, we categorize the object detection methods into motion-based and appearance-based techniques. We further classify each group of techniques into a number of subcategories and analyze the advantages and disadvantages of each method. The major challenges, limitations, and potential solutions are also discussed along with the future scope and directions.", "arxiv_id": null, "paper_id": 2893, "venue_id": 134, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/tits.2023.3258683", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4361854625", "cited_by_count": 113, "publication_date": "2023-03-30"}, {"doi": "10.1016/j.jbi.2021.103980", "title": "Deep learning for temporal data representation in electronic health records: A systematic review of challenges and methodologies", "abstract": null, "arxiv_id": "2107.09951", "paper_id": 3215, "venue_id": 328, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1016/j.jbi.2021.103980", "work_type": "REVIEW", "open_access": true, "openalex_id": "W3183848791", "cited_by_count": 156, "publication_date": "2021-12-30"}, {"doi": "10.1007/s10916-019-1243-3", "title": "RETRACTED ARTICLE: LSTM Model for Prediction of Heart Failure in Big Data", "abstract": null, "arxiv_id": null, "paper_id": 3228, "venue_id": 515, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1007/s10916-019-1243-3", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2922594471", "cited_by_count": 152, "publication_date": "2019-03-19"}, {"doi": "10.1038/nature14236", "title": "Human-level control through deep reinforcement learning", "abstract": null, "arxiv_id": null, "paper_id": 3535, "venue_id": 2, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nature14236", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2145339207", "cited_by_count": 30294, "publication_date": "2015-02-24"}, {"doi": "10.1038/nature16961", "title": "Mastering the game of Go with deep neural networks and tree search", "abstract": null, "arxiv_id": null, "paper_id": 3537, "venue_id": 2, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nature16961", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2257979135", "cited_by_count": 15594, "publication_date": "2016-01-26"}, {"doi": "10.48550/arxiv.1509.02971", "title": "Continuous control with deep reinforcement learning", "abstract": "We adapt the ideas underlying the success of Deep Q-Learning to the continuous action domain. We present an actor-critic, model-free algorithm based on the deterministic policy gradient that can operate over continuous action spaces. Using the same learning algorithm, network architecture and hyper-parameters, our algorithm robustly solves more than 20 simulated physics tasks, including classic problems such as cartpole swing-up, dexterous manipulation, legged locomotion and car driving. Our algorithm is able to find policies whose performance is competitive with those found by a planning algorithm with full access to the dynamics of the domain and its derivatives. We further demonstrate that for many of the tasks the algorithm can learn policies end-to-end: directly from raw pixel inputs.", "arxiv_id": "1509.02971", "paper_id": 3538, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1509.02971", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2173248099", "cited_by_count": 10782, "publication_date": "2015-09-09"}, {"doi": "10.4230/oasics.dx.2024.16", "title": "Diagnosing Non-Intermittent Anomalies in Reinforcement Learning Policy Executions (Short Paper)", "abstract": "Due to the safety risks and training sample inefficiency, it is often preferred to develop controllers in simulation. However, minor differences between the simulation and the real world can cause a significant sim-to-real gap. This gap can reduce the effectiveness of the developed controller. In this paper, we examine a case study of transferring an octorotor reinforcement learning controller from simulation to the real world. First, we quantify the effectiveness of the real-world transfer by examining safety metrics. We find that although there is a noticeable (around 100%) increase in deviation in real flights, this deviation may not be considered unsafe, as it will be within > 2m safety corridors. Then, we estimate the densities of the measurement distributions and compare the Jensen-Shannon divergences of simulated and real measurements. From this, we show that the vehicle’s orientation is significantly different between simulated and real flights. We attribute this to a different flight mode in real flights where the vehicle turns to face the next waypoint. We also find that the reinforcement learning controller actions appear to correctly counteract disturbance forces. Then, we analyze the errors of a measurement autoencoder and state transition model neural network applied to real data. We find that these models further reinforce the difference between the simulated and real attitude control, showing the errors directly on the flight paths. Finally, we discuss important lessons learned in the sim-to-real transfer of our controller.", "arxiv_id": "1707.06347", "paper_id": 3539, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1707.06347", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2736601468", "cited_by_count": 10626, "publication_date": "2017-07-20"}, {"doi": "10.48550/arxiv.1312.5602", "title": "Playing Atari with Deep Reinforcement Learning", "abstract": "We present the first deep learning model to successfully learn control policies directly from high-dimensional sensory input using reinforcement learning. The model is a convolutional neural network, trained with a variant of Q-learning, whose input is raw pixels and whose output is a value function estimating future rewards. We apply our method to seven Atari 2600 games from the Arcade Learning Environment, with no adjustment of the architecture or learning algorithm. We find that it outperforms all previous approaches on six of the games and surpasses a human expert on three of them.", "arxiv_id": "1312.5602", "paper_id": 3540, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1312.5602", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W1757796397", "cited_by_count": 9472, "publication_date": "2013-12-19"}, {"doi": "10.48550/arxiv.1602.01783", "title": "Asynchronous Methods for Deep Reinforcement Learning", "abstract": "We propose a conceptually simple and lightweight framework for deep reinforcement learning that uses asynchronous gradient descent for optimization of deep neural network controllers. We present asynchronous variants of four standard reinforcement learning algorithms and show that parallel actor-learners have a stabilizing effect on training allowing all four methods to successfully train neural network controllers. The best performing method, an asynchronous variant of actor-critic, surpasses the current state-of-the-art on the Atari domain while training for half the time on a single multi-core CPU instead of a GPU. Furthermore, we show that asynchronous actor-critic succeeds on a wide variety of continuous motor control problems as well as on a new task of navigating random 3D mazes using a visual input.", "arxiv_id": "1602.01783", "paper_id": 3542, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1602.01783", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2260756217", "cited_by_count": 7131, "publication_date": "2016-02-04"}, {"doi": "10.3390/electronics8030292", "title": "A State-of-the-Art Survey on Deep Learning Theory and Architectures", "abstract": "In recent years, deep learning has garnered tremendous success in a variety of application domains. This new field of machine learning has been growing rapidly and has been applied to most traditional application domains, as well as some new areas that present more opportunities. Different methods have been proposed based on different categories of learning, including supervised, semi-supervised, and un-supervised learning. Experimental results show state-of-the-art performance using deep learning when compared to traditional machine learning approaches in the fields of image processing, computer vision, speech recognition, machine translation, art, medical imaging, medical information processing, robotics and control, bioinformatics, natural language processing, cybersecurity, and many others. This survey presents a brief survey on the advances that have occurred in the area of Deep Learning (DL), starting with the Deep Neural Network (DNN). The survey goes on to cover Convolutional Neural Network (CNN), Recurrent Neural Network (RNN), including Long Short-Term Memory (LSTM) and Gated Recurrent Units (GRU), Auto-Encoder (AE), Deep Belief Network (DBN), Generative Adversarial Network (GAN), and Deep Reinforcement Learning (DRL). Additionally, we have discussed recent developments, such as advanced variant DL techniques based on these DL approaches. This work considers most of the papers published after 2012 from when the history of deep learning began. Furthermore, DL approaches that have been explored and evaluated in different application domains are also included in this survey. We also included recently developed frameworks, SDKs, and benchmark datasets that are used for implementing and evaluating deep learning approaches. There are some surveys that have been published on DL using neural networks and a survey on Reinforcement Learning (RL). However, those papers have not discussed individual advanced techniques for training large-scale deep learning models and the recently developed method of generative models.", "arxiv_id": null, "paper_id": 3571, "venue_id": 87, "oa_status": "GOLD", "paper_url": "https://doi.org/10.3390/electronics8030292", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2919358988", "cited_by_count": 1621, "publication_date": "2019-03-05"}, {"doi": "10.1007/s10462-021-10061-9", "title": "Deep reinforcement learning in computer vision: a comprehensive survey", "abstract": null, "arxiv_id": "2108.11510", "paper_id": 3991, "venue_id": 220, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s10462-021-10061-9", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3202546516", "cited_by_count": 262, "publication_date": "2021-09-29"}, {"doi": "10.1016/j.cosrev.2024.100645", "title": "Backbones-review: Feature extractor networks for deep learning and deep reinforcement learning approaches in computer vision", "abstract": null, "arxiv_id": "2206.08016", "paper_id": 4045, "venue_id": 521, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.cosrev.2024.100645", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4399419713", "cited_by_count": 170, "publication_date": "2024-06-07"}, {"doi": "10.1016/j.irfa.2018.09.003", "title": "RETRACTED: Cryptocurrencies as a financial asset: A systematic analysis", "abstract": null, "arxiv_id": null, "paper_id": 4269, "venue_id": 851, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.irfa.2018.09.003", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2799345028", "cited_by_count": 1170, "publication_date": "2018-09-12"}, {"doi": "10.1016/j.future.2018.04.051", "title": "RETRACTED: Internet of Things (IoT) and its impact on supply chain: A framework for building smart, secure and efficient systems", "abstract": null, "arxiv_id": null, "paper_id": 4271, "venue_id": 358, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.future.2018.04.051", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2802538926", "cited_by_count": 428, "publication_date": "2018-04-30"}, {"doi": "10.1371/journal.pone.0259283", "title": "Application of local fully Convolutional Neural Network combined with YOLO v5 algorithm in small target detection of remote sensing image", "abstract": "This exploration primarily aims to jointly apply the local FCN (fully convolution neural network) and YOLO-v5 (You Only Look Once-v5) to the detection of small targets in remote sensing images. Firstly, the application effects of R-CNN (Region-Convolutional Neural Network), FRCN (Fast Region-Convolutional Neural Network), and R-FCN (Region-Based-Fully Convolutional Network) in image feature extraction are analyzed after introducing the relevant region proposal network. Secondly, YOLO-v5 algorithm is established on the basis of YOLO algorithm. Besides, the multi-scale anchor mechanism of Faster R-CNN is utilized to improve the detection ability of YOLO-v5 algorithm for small targets in the image in the process of image detection, and realize the high adaptability of YOLO-v5 algorithm to different sizes of images. Finally, the proposed detection method YOLO-v5 algorithm + R-FCN is compared with other algorithms in NWPU VHR-10 data set and Vaihingen data set. The experimental results show that the YOLO-v5 + R-FCN detection method has the optimal detection ability among many algorithms, especially for small targets in remote sensing images such as tennis courts, vehicles, and storage tanks. Moreover, the YOLO-v5 + R-FCN detection method can achieve high recall rates for different types of small targets. Furthermore, due to the deeper network architecture, the YOL v5 + R-FCN detection method has a stronger ability to extract the characteristics of image targets in the detection of remote sensing images. Meanwhile, it can achieve more accurate feature recognition and detection performance for the densely arranged target images in remote sensing images. This research can provide reference for the application of remote sensing technology in China, and promote the application of satellites for target detection tasks in related fields.", "arxiv_id": null, "paper_id": 4272, "venue_id": 257, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1371/journal.pone.0259283", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3209586559", "cited_by_count": 414, "publication_date": "2021-10-29"}, {"doi": "10.1007/s10311-023-01617-y", "title": "RETRACTED ARTICLE: Artificial intelligence-based solutions for climate change: a review", "abstract": "Abstract Climate change is a major threat already causing system damage to urban and natural systems, and inducing global economic losses of over $500 billion. These issues may be partly solved by artificial intelligence because artificial intelligence integrates internet resources to make prompt suggestions based on accurate climate change predictions. Here we review recent research and applications of artificial intelligence in mitigating the adverse effects of climate change, with a focus on energy efficiency, carbon sequestration and storage, weather and renewable energy forecasting, grid management, building design, transportation, precision agriculture, industrial processes, reducing deforestation, and resilient cities. We found that enhancing energy efficiency can significantly contribute to reducing the impact of climate change. Smart manufacturing can reduce energy consumption, waste, and carbon emissions by 30–50% and, in particular, can reduce energy consumption in buildings by 30–50%. About 70% of the global natural gas industry utilizes artificial intelligence technologies to enhance the accuracy and reliability of weather forecasts. Combining smart grids with artificial intelligence can optimize the efficiency of power systems, thereby reducing electricity bills by 10–20%. Intelligent transportation systems can reduce carbon dioxide emissions by approximately 60%. Moreover, the management of natural resources and the design of resilient cities through the application of artificial intelligence can further promote sustainability.", "arxiv_id": null, "paper_id": 4274, "venue_id": 852, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1007/s10311-023-01617-y", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4380628716", "cited_by_count": 389, "publication_date": "2023-06-13"}, {"doi": "10.1007/s11831-021-09622-6", "title": "RETRACTED ARTICLE: A Review and State of Art of Internet of Things (IoT)", "abstract": null, "arxiv_id": null, "paper_id": 4275, "venue_id": 476, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1007/s11831-021-09622-6", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W3178180748", "cited_by_count": 388, "publication_date": "2021-07-14"}, {"doi": "10.1093/rfs/hhaa113", "title": "Risks and Returns of Cryptocurrency", "abstract": "Abstract We establish that cryptocurrency returns are driven and can be predicted by factors that are specific to cryptocurrency markets. Cryptocurrency returns are exposed to cryptocurrency network factors but not cryptocurrency production factors. We construct the network factors to capture the user adoption of cryptocurrencies and the production factors to proxy for the costs of cryptocurrency production. Moreover, there is a strong time-series momentum effect, and proxies for investor attention strongly forecast future cryptocurrency returns.", "arxiv_id": null, "paper_id": 4308, "venue_id": 862, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1093/rfs/hhaa113", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3124611303", "cited_by_count": 959, "publication_date": "2020-09-12"}, {"doi": "10.1016/j.frl.2020.101554", "title": "The contagion effects of the COVID-19 pandemic: Evidence from gold and cryptocurrencies", "abstract": "At the beginning of the 2020 global COVID-2019 pandemic, Chinese financial markets acted as the epicentre of both physical and financial contagion. Our results indicate that a number of characteristics expected during a \"flight to safety\" were present during the period analysed. The volatility relationship between the main Chinese stock markets and Bitcoin evolved significantly during this period of enormous financial stress. We provide a number of observations as to why this situation occurred. Such dynamic correlations during periods of stress present further evidence to cautiously support the validity of the development of this new financial product within mainstream portfolio design through the diversification benefits provided.", "arxiv_id": null, "paper_id": 4309, "venue_id": 863, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1016/j.frl.2020.101554", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3019724901", "cited_by_count": 878, "publication_date": "2020-05-14"}, {"doi": "10.1016/j.frl.2020.101607", "title": "Safe haven or risky hazard? Bitcoin during the Covid-19 bear market", "abstract": "The Covid-19 bear market presents the first acute market losses since active trading of Bitcoin began. This market downturn provides a timely test of the frequently expounded safe haven properties of Bitcoin. In this paper, we show that Bitcoin does not act as a safe haven, instead decreasing in price in lockstep with the S&P 500 as the crisis develops. When held alongside the S&P 500, even a small allocation to Bitcoin substantially increases portfolio downside risk. Our empirical findings cast doubt on the ability of Bitcoin to provide shelter from turbulence in traditional markets.", "arxiv_id": null, "paper_id": 4310, "venue_id": 863, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1016/j.frl.2020.101607", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3022908605", "cited_by_count": 832, "publication_date": "2020-05-24"}, {"doi": "10.1016/j.ribaf.2020.101248", "title": "Are cryptocurrencies a safe haven for equity markets? An international perspective from the COVID-19 pandemic", "abstract": "The COVID-19 pandemic provided the first widespread bear market conditions since the inception of cryptocurrencies. We test the widely mooted safe haven properties of Bitcoin, Ethereum and Tether from the perspective of international equity index investors. Bitcoin and Ethereum are not a safe haven for the majority of international equity markets examined, with their inclusion adding to portfolio downside risk. Only investors in the Chinese CSI 300 index realized modest downside risk benefits (contingent on very limited allocations to Bitcoin or Ethereum). As Tether successfully maintained its peg to the US dollar during the COVID-19 turmoil, it acted as a safe haven investment for all of the international indices examined. We caveat the latter findings with a warning that Tether's dollar peg has not always been maintained, with evidence of impaired downside risk hedging properties earlier in our sample.", "arxiv_id": null, "paper_id": 4311, "venue_id": 864, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1016/j.ribaf.2020.101248", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3033445019", "cited_by_count": 603, "publication_date": "2020-06-04"}, {"doi": "10.1016/j.irfa.2019.02.009", "title": "Is Bitcoin a Hedge or Safe-Haven for Currencies? An Intraday Analysis", "abstract": null, "arxiv_id": null, "paper_id": 4312, "venue_id": 851, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.irfa.2019.02.009", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2900898792", "cited_by_count": 551, "publication_date": "2018-01-01"}, {"doi": "10.1016/j.irfa.2018.08.012", "title": "Volatility connectedness in the cryptocurrency market: Is Bitcoin a dominant cryptocurrency?", "abstract": null, "arxiv_id": null, "paper_id": 4313, "venue_id": 851, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.irfa.2018.08.012", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2888832810", "cited_by_count": 436, "publication_date": "2018-09-01"}, {"doi": "10.1016/j.techfore.2020.120382", "title": "Time and frequency domain connectedness and spill-over among fintech, green bonds and cryptocurrencies in the age of the fourth industrial revolution", "abstract": null, "arxiv_id": null, "paper_id": 4314, "venue_id": 865, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.techfore.2020.120382", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3093016099", "cited_by_count": 422, "publication_date": "2020-10-16"}, {"doi": "10.1186/s40854-021-00321-6", "title": "Cryptocurrency trading: a comprehensive survey", "abstract": "Abstract In recent years, the tendency of the number of financial institutions to include cryptocurrencies in their portfolios has accelerated. Cryptocurrencies are the first pure digital assets to be included by asset managers. Although they have some commonalities with more traditional assets, they have their own separate nature and their behaviour as an asset is still in the process of being understood. It is therefore important to summarise existing research papers and results on cryptocurrency trading, including available trading platforms, trading signals, trading strategy research and risk management. This paper provides a comprehensive survey of cryptocurrency trading research, by covering 146 research papers on various aspects of cryptocurrency trading ( e . g ., cryptocurrency trading systems, bubble and extreme condition, prediction of volatility and return, crypto-assets portfolio construction and crypto-assets, technical trading and others). This paper also analyses datasets, research trends and distribution among research objects (contents/properties) and technologies, concluding with some promising opportunities that remain open in cryptocurrency trading.", "arxiv_id": null, "paper_id": 4315, "venue_id": 866, "oa_status": "DIAMOND", "paper_url": "https://doi.org/10.1186/s40854-021-00321-6", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4210404112", "cited_by_count": 421, "publication_date": "2022-02-06"}, {"doi": "10.1016/j.econlet.2018.11.007", "title": "Does twitter predict Bitcoin?", "abstract": null, "arxiv_id": null, "paper_id": 4316, "venue_id": 867, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.econlet.2018.11.007", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2899685556", "cited_by_count": 381, "publication_date": "2018-11-10"}, {"doi": "10.1016/j.techfore.2020.120188", "title": "Diversification in the age of the 4th industrial revolution: The role of artificial intelligence, green bonds and cryptocurrencies", "abstract": null, "arxiv_id": null, "paper_id": 4317, "venue_id": 865, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.techfore.2020.120188", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3041481953", "cited_by_count": 337, "publication_date": "2020-07-14"}, {"doi": "10.1016/j.irfa.2018.12.010", "title": "Does global economic uncertainty matter for the volatility and hedging effectiveness of Bitcoin?", "abstract": null, "arxiv_id": null, "paper_id": 4318, "venue_id": 851, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.irfa.2018.12.010", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2898449608", "cited_by_count": 317, "publication_date": "2018-12-26"}, {"doi": "10.1016/j.gfj.2022.100719", "title": "Static and Dynamic Connectedness Between NFTs, Defi and Other Assets: Portfolio Implication", "abstract": null, "arxiv_id": null, "paper_id": 4319, "venue_id": 868, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.gfj.2022.100719", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4220790190", "cited_by_count": 314, "publication_date": "2021-01-01"}, {"doi": "10.1016/j.frl.2018.08.010", "title": "What can explain the price, volatility and trading volume of Bitcoin?", "abstract": null, "arxiv_id": null, "paper_id": 4320, "venue_id": 863, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.frl.2018.08.010", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2760878790", "cited_by_count": 306, "publication_date": "2018-08-16"}, {"doi": "10.1016/j.frl.2019.03.009", "title": "Volatility spillover effects in leading cryptocurrencies: A BEKK-MGARCH analysis", "abstract": null, "arxiv_id": null, "paper_id": 4321, "venue_id": 863, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.frl.2019.03.009", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2922466487", "cited_by_count": 305, "publication_date": "2019-03-07"}, {"doi": "10.1016/j.econlet.2021.110068", "title": "Tail dependence between bitcoin and green financial assets", "abstract": "The high power consumption of Bitcoin transactions has raised environmental and sustainable concerns of green investors and regulatory bodies. We utilize the time-varying optimal copula (TVOC) approach to showcase the dependence structure between bitcoin and green financial assets. We find multiple tail-dependence regimes characterize the extreme dependence between bitcoin and green financial assets, and the dependence structure is mainly asymmetric and time-varying. Finally, the hedging effectiveness of green financial assets for bitcoin revealed that all green assets, especially clean energy, are effective hedges for bitcoin.", "arxiv_id": null, "paper_id": 4322, "venue_id": 867, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1016/j.econlet.2021.110068", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3196544268", "cited_by_count": 300, "publication_date": "2021-09-08"}, {"doi": "10.1080/00207543.2020.1743896", "title": "Information and digital technologies of Industry 4.0 and Lean supply chain management: a systematic literature review", "abstract": "The purpose of this paper is to provide an overview of the current state of research and the key aspects and implications of the relationships between Information and Digital Technologies (IDT) of Industry 4.0 and Lean Supply Chain Management (LSCM), with the identification of the lines of research developed and an analysis of the main findings. A Systematic Literature Review methodology has been used for the identification, selection, and evaluation of the published research. A set of 78 papers deduced from the most relevant scientific databases, including Web of Science, Scopus, and ABI/Inform, from 1996 to December 2019, has been analyzed and synthesized. The analysis and evaluation of these papers has enabled a new classification of the literature to be offered that identifies four lines of research based on the Life Cycle of Technology: obsolete IDT in LSCM; mature IDT in LSCM; emerging IDT in LSCM; and an Information Systems and IDT general approach in LSCM. The paper goes on to discuss the gaps found in the literature and proposes new opportunities and challenges for future research. A series of implications are presented intended to be useful from not only an academic point-of-view but also from a management focus, including recommendations for industrial managers and policymakers. Núñez-Merino, Miguel; Maqueira-Marín, Juan Manuel; Moyano-Fuentes, José; Martínez-Jurado, Pedro José", "arxiv_id": null, "paper_id": 4338, "venue_id": 870, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1080/00207543.2020.1743896", "work_type": "REVIEW", "open_access": true, "openalex_id": "W3017162204", "cited_by_count": 382, "publication_date": "2020-04-14"}, {"doi": "10.1016/j.iot.2019.100129", "title": "A survey on internet of things security: Requirements, challenges, and solutions", "abstract": null, "arxiv_id": null, "paper_id": 4339, "venue_id": 413, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.iot.2019.100129", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2986458967", "cited_by_count": 370, "publication_date": "2019-11-08"}, {"doi": "10.1109/access.2019.2940227", "title": "Blockchain-Driven IoT for Food Traceability With an Integrated Consensus Mechanism", "abstract": "Food traceability has been one of the emerging blockchain applications in recent years, for improving the areas of anti-counterfeiting and quality assurance. Existing food traceability systems do not guarantee a high level of system reliability, scalability, and information accuracy. Moreover, the traceability process is time-consuming and complicated in modern supply chain networks. To alleviate these concerns, blockchain technology is promising to create a new ontology for supply chain traceability. However, most consensus mechanisms and data flow in blockchain are developed for cryptocurrency, not for supply chain traceability; hence, simply applying blockchain technology to food traceability is impractical. In this paper, a blockchain-IoT-based food traceability system (BIFTS) is proposed to integrate the novel deployment of blockchain, IoT technology, and fuzzy logic into a total traceability shelf life management system for managing perishable food. To address the needs for food traceability, lightweight and vaporized characteristics are deployed in the blockchain, while an integrated consensus mechanism that considers shipment transit time, stakeholder assessment, and shipment volume is developed. The data flow of blockchain is then aligned to the deployment of IoT technologies according to the level of traceable resource units. Subsequently, the decision support can be established in the food supply chain by using reliable and accurate data for shelf life adjustment, and by using fuzzy logic for quality decay evaluation.", "arxiv_id": null, "paper_id": 4340, "venue_id": 106, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/access.2019.2940227", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2972955472", "cited_by_count": 338, "publication_date": "2019-01-01"}, {"doi": "10.1016/j.jmsy.2022.06.011", "title": "Deep learning methods for object detection in smart manufacturing: A survey", "abstract": null, "arxiv_id": null, "paper_id": 4823, "venue_id": 399, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1016/j.jmsy.2022.06.011", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4283714674", "cited_by_count": 177, "publication_date": "2022-06-29"}, {"doi": "10.1109/cvpr.2016.90", "title": "Deep Residual Learning for Image Recognition", "abstract": "Deeper neural networks are more difficult to train. We present a residual learning framework to ease the training of networks that are substantially deeper than those used previously. We explicitly reformulate the layers as learning residual functions with reference to the layer inputs, instead of learning unreferenced functions. We provide comprehensive empirical evidence showing that these residual networks are easier to optimize, and can gain accuracy from considerably increased depth. On the ImageNet dataset we evaluate residual nets with a depth of up to 152 layers - 8× deeper than VGG nets [40] but still having lower complexity. An ensemble of these residual nets achieves 3.57% error on the ImageNet test set. This result won the 1st place on the ILSVRC 2015 classification task. We also present analysis on CIFAR-10 with 100 and 1000 layers. The depth of representations is of central importance for many visual recognition tasks. Solely due to our extremely deep representations, we obtain a 28% relative improvement on the COCO object detection dataset. Deep residual nets are foundations of our submissions to ILSVRC & COCO 2015 competitions1, where we also won the 1st places on the tasks of ImageNet detection, ImageNet localization, COCO detection, and COCO segmentation.", "arxiv_id": null, "paper_id": 4897, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2016.90", "work_type": "OTHER", "open_access": true, "openalex_id": "W2194775991", "cited_by_count": 234936, "publication_date": "2016-06-01"}, {"doi": "10.1145/3065386", "title": "ImageNet classification with deep convolutional neural networks", "abstract": "We trained a large, deep convolutional neural network to classify the 1.2 million high-resolution images in the ImageNet LSVRC-2010 contest into the 1000 different classes. On the test data, we achieved top-1 and top-5 error rates of 37.5% and 17.0%, respectively, which is considerably better than the previous state-of-the-art. The neural network, which has 60 million parameters and 650,000 neurons, consists of five convolutional layers, some of which are followed by max-pooling layers, and three fully connected layers with a final 1000-way softmax. To make training faster, we used non-saturating neurons and a very efficient GPU implementation of the convolution operation. To reduce overfitting in the fully connected layers we employed a recently developed regularization method called \"dropout\" that proved to be very effective. We also entered a variant of this model in the ILSVRC-2012 competition and achieved a winning top-5 test error rate of 15.3%, compared to 26.2% achieved by the second-best entry.", "arxiv_id": null, "paper_id": 4898, "venue_id": 474, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1145/3065386", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2163605009", "cited_by_count": 112122, "publication_date": "2017-05-24"}, {"doi": "10.1162/neco.1997.9.8.1735", "title": "Long Short-Term Memory", "abstract": "Learning to store information over extended time intervals by recurrent backpropagation takes a very long time, mostly because of insufficient, decaying error backflow. We briefly review Hochreiter's (1991) analysis of this problem, then address it by introducing a novel, efficient, gradient-based method called long short-term memory (LSTM). Truncating the gradient where this does not do harm, LSTM can learn to bridge minimal time lags in excess of 1000 discrete-time steps by enforcing constant error flow through constant error carousels within special units. Multiplicative gate units learn to open and close access to the constant error flow. LSTM is local in space and time; its computational complexity per time step and weight is O(1). Our experiments with artificial data involve local, distributed, real-valued, and noisy pattern representations. In comparisons with real-time recurrent learning, back propagation through time, recurrent cascade correlation, Elman nets, and neural sequence chunking, LSTM leads to many more successful runs, and learns much faster. LSTM also solves complex, artificial long-time-lag tasks that have never been solved by previous recurrent network algorithms.", "arxiv_id": null, "paper_id": 4899, "venue_id": 46, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1162/neco.1997.9.8.1735", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2064675550", "cited_by_count": 102073, "publication_date": "1997-11-01"}, {"doi": "10.1007/978-3-319-24574-4_28", "title": "U-Net: Convolutional Networks for Biomedical Image Segmentation", "abstract": null, "arxiv_id": null, "paper_id": 4900, "venue_id": 1036, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1007/978-3-319-24574-4_28", "work_type": "OTHER", "open_access": true, "openalex_id": "W1901129140", "cited_by_count": 99143, "publication_date": "2015-01-01"}, {"doi": "10.4230/lipics.itp.2023.19", "title": "Exploiting Generative AI to Scale up Intelligent Tutoring Systems", "abstract": "As a present to Mizar on its 50th anniversary, we develop an AI/TP system that automatically proves about 60% of the Mizar theorems in the hammer setting. We also automatically prove 75% of the Mizar theorems when the automated provers are helped by using only the premises used in the human-written Mizar proofs. We describe the methods and large-scale experiments leading to these results. This includes in particular the E and Vampire provers, their ENIGMA and Deepire learning modifications, a number of learning-based premise selection methods, and the incremental loop that interleaves growing a corpus of millions of ATP proofs with training increasingly strong AI/TP systems on them. We also present a selection of Mizar problems that were proved automatically.", "arxiv_id": null, "paper_id": 4901, "venue_id": 247, "oa_status": "GREEN", "paper_url": "https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ITP.2023.19", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W4385245566", "cited_by_count": 76645, "publication_date": "2023-01-01"}, {"doi": "10.1109/cvpr.2009.5206848", "title": "ImageNet: A large-scale hierarchical image database", "abstract": "The explosion of image data on the Internet has the potential to foster more sophisticated and robust models and algorithms to index, retrieve, organize and interact with images and multimedia data. But exactly how such data can be harnessed and organized remains a critical problem. We introduce here a new database called “ImageNet”, a large-scale ontology of images built upon the backbone of the WordNet structure. ImageNet aims to populate the majority of the 80,000 synsets of WordNet with an average of 500–1000 clean and full resolution images. This will result in tens of millions of annotated images organized by the semantic hierarchy of WordNet. This paper offers a detailed analysis of ImageNet in its current state: 12 subtrees with 5247 synsets and 3.2 million images in total. We show that ImageNet is much larger in scale and diversity and much more accurate than the current image datasets. Constructing such a large-scale database is a challenging task. We describe the data collection scheme with Amazon Mechanical Turk. Lastly, we illustrate the usefulness of ImageNet through three simple applications in object recognition, image classification and automatic object clustering. We hope that the scale, accuracy, diversity and hierarchical structure of ImageNet can offer unparalleled opportunities to researchers in the computer vision community and beyond.", "arxiv_id": null, "paper_id": 4902, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2009.5206848", "work_type": "OTHER", "open_access": false, "openalex_id": "W2108598243", "cited_by_count": 65256, "publication_date": "2009-06-01"}, {"doi": "10.1109/5.726791", "title": "Gradient-based learning applied to document recognition", "abstract": "Multilayer neural networks trained with the back-propagation algorithm constitute the best example of a successful gradient based learning technique. Given an appropriate network architecture, gradient-based learning algorithms can be used to synthesize a complex decision surface that can classify high-dimensional patterns, such as handwritten characters, with minimal preprocessing. This paper reviews various methods applied to handwritten character recognition and compares them on a standard handwritten digit recognition task. Convolutional neural networks, which are specifically designed to deal with the variability of 2D shapes, are shown to outperform all other techniques. Real-life document recognition systems are composed of multiple modules including field extraction, segmentation recognition, and language modeling. A new learning paradigm, called graph transformer networks (GTN), allows such multimodule systems to be trained globally using gradient-based methods so as to minimize an overall performance measure. Two systems for online handwriting recognition are described. Experiments demonstrate the advantage of global training, and the flexibility of graph transformer networks. A graph transformer network for reading a bank cheque is also described. It uses convolutional neural network character recognizers combined with global training techniques to provide record accuracy on business and personal cheques. It is deployed commercially and reads several million cheques per day.", "arxiv_id": null, "paper_id": 4903, "venue_id": 12, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/5.726791", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2112796928", "cited_by_count": 58716, "publication_date": "1998-01-01"}, {"doi": "10.1109/cvpr.2016.91", "title": "You Only Look Once: Unified, Real-Time Object Detection", "abstract": "We present YOLO, a new approach to object detection. Prior work on object detection repurposes classifiers to perform detection. Instead, we frame object detection as a regression problem to spatially separated bounding boxes and associated class probabilities. A single neural network predicts bounding boxes and class probabilities directly from full images in one evaluation. Since the whole detection pipeline is a single network, it can be optimized end-to-end directly on detection performance. Our unified architecture is extremely fast. Our base YOLO model processes images in real-time at 45 frames per second. A smaller version of the network, Fast YOLO, processes an astounding 155 frames per second while still achieving double the mAP of other real-time detectors. Compared to state-of-the-art detection systems, YOLO makes more localization errors but is less likely to predict false positives on background. Finally, YOLO learns very general representations of objects. It outperforms other detection methods, including DPM and R-CNN, when generalizing from natural images to other domains like artwork.", "arxiv_id": "1506.02640", "paper_id": 4904, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2016.91", "work_type": "OTHER", "open_access": true, "openalex_id": "W1483870316", "cited_by_count": 53127, "publication_date": "2016-06-01"}, {"doi": "10.1109/cvpr.2017.243", "title": "Densely Connected Convolutional Networks", "abstract": "Recent work has shown that convolutional networks can be substantially deeper, more accurate, and efficient to train if they contain shorter connections between layers close to the input and those close to the output. In this paper, we embrace this observation and introduce the Dense Convolutional Network (DenseNet), which connects each layer to every other layer in a feed-forward fashion. Whereas traditional convolutional networks with L layers have L connections-one between each layer and its subsequent layer-our network has L(L+1)/2 direct connections. For each layer, the feature-maps of all preceding layers are used as inputs, and its own feature-maps are used as inputs into all subsequent layers. DenseNets have several compelling advantages: they alleviate the vanishing-gradient problem, strengthen feature propagation, encourage feature reuse, and substantially reduce the number of parameters. We evaluate our proposed architecture on four highly competitive object recognition benchmark tasks (CIFAR-10, CIFAR-100, SVHN, and ImageNet). DenseNets obtain significant improvements over the state-of-the-art on most of them, whilst requiring less memory and computation to achieve high performance. Code and pre-trained models are available at https://github.com/liuzhuang13/DenseNet.", "arxiv_id": "1608.06993", "paper_id": 4905, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2017.243", "work_type": "OTHER", "open_access": true, "openalex_id": "W2963446712", "cited_by_count": 48491, "publication_date": "2017-07-01"}, {"doi": "10.18653/v1/n19-1423", "title": "BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding", "abstract": "Jacob Devlin, Ming-Wei Chang, Kenton Lee, Kristina Toutanova. Proceedings of the 2019 Conference of the North American Chapter of the Association for Computational Linguistics: Human Language Technologies, Volume 1 (Long and Short Papers). 2019.", "arxiv_id": null, "paper_id": 4906, "venue_id": 1037, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.18653/v1/n19-1423", "work_type": "OTHER", "open_access": true, "openalex_id": "W2963341956", "cited_by_count": 48336, "publication_date": "2019-01-01"}, {"doi": "10.1109/cvpr.2015.7298594", "title": "Going deeper with convolutions", "abstract": "We propose a deep convolutional neural network architecture codenamed Inception that achieves the new state of the art for classification and detection in the ImageNet Large-Scale Visual Recognition Challenge 2014 (ILSVRC14). The main hallmark of this architecture is the improved utilization of the computing resources inside the network. By a carefully crafted design, we increased the depth and width of the network while keeping the computational budget constant. To optimize quality, the architectural decisions were based on the Hebbian principle and the intuition of multi-scale processing. One particular incarnation used in our submission for ILSVRC14 is called GoogLeNet, a 22 layers deep network, the quality of which is assessed in the context of classification and detection.", "arxiv_id": null, "paper_id": 4907, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2015.7298594", "work_type": "OTHER", "open_access": false, "openalex_id": "W2097117768", "cited_by_count": 48195, "publication_date": "2015-06-01"}, {"doi": "10.4230/oasics.dx.2026.15", "title": "AutoResearch Lite: a reproducible paper-inspired experiment runner (Adam mechanism reproduction and convergence-speed comparison)", "abstract": "A dependency-free experiment runner that turns a paper's research question into a configuration-driven, verifiable experiment task. The bundled reproduction maps the first/second moment estimates and bias correction of Adam (Kingma & Ba, arXiv:1412.6980) into runnable Python and compares them against fixed-learning-rate SGD under fixed seeds and epoch budgets. A second experiment measures convergence speed (epochs to reach a target training loss) against SGD with heavy-ball momentum, AdaGrad and RMSProp, with every optimizer family tuned by the same coarse learning-rate sweep. In that experiment Adam is not the fastest; the negative result is reported in full. Every reported number is pinned in an expected-values file with explicit tolerances and checked by one command that also runs the unit tests, and the checking harness is validated against deliberately broken implementations (negative controls). The repository also ships a task contract that expresses the reproduction as a repeatable, scoreable task for an automated research loop.", "arxiv_id": "2108.04578", "paper_id": 4908, "venue_id": 247, "oa_status": "GREEN", "paper_url": "https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.DNA.28.4", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2964121744", "cited_by_count": 45787, "publication_date": "2026-01-01"}, {"doi": "10.1007/978-3-319-10602-1_48", "title": "Microsoft COCO: Common Objects in Context", "abstract": null, "arxiv_id": null, "paper_id": 4909, "venue_id": 1036, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1007/978-3-319-10602-1_48", "work_type": "OTHER", "open_access": true, "openalex_id": "W1861492603", "cited_by_count": 45370, "publication_date": "2014-01-01"}, {"doi": "10.1109/cvpr.2015.7298965", "title": "Fully convolutional networks for semantic segmentation", "abstract": "Convolutional networks are powerful visual models that yield hierarchies of features. We show that convolutional networks by themselves, trained end-to-end, pixels-to-pixels, exceed the state-of-the-art in semantic segmentation. Our key insight is to build “fully convolutional” networks that take input of arbitrary size and produce correspondingly-sized output with efficient inference and learning. We define and detail the space of fully convolutional networks, explain their application to spatially dense prediction tasks, and draw connections to prior models. We adapt contemporary classification networks (AlexNet [20], the VGG net [31], and GoogLeNet [32]) into fully convolutional networks and transfer their learned representations by fine-tuning [3] to the segmentation task. We then define a skip architecture that combines semantic information from a deep, coarse layer with appearance information from a shallow, fine layer to produce accurate and detailed segmentations. Our fully convolutional network achieves state-of-the-art segmentation of PASCAL VOC (20% relative improvement to 62.2% mean IU on 2012), NYUDv2, and SIFT Flow, while inference takes less than one fifth of a second for a typical image.", "arxiv_id": null, "paper_id": 4910, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2015.7298965", "work_type": "OTHER", "open_access": false, "openalex_id": "W1903029394", "cited_by_count": 38793, "publication_date": "2015-06-01"}, {"doi": "10.1109/iccv48922.2021.00986", "title": "Swin Transformer: Hierarchical Vision Transformer using Shifted Windows", "abstract": "This paper presents a new vision Transformer, called Swin Transformer, that capably serves as a general-purpose backbone for computer vision. Challenges in adapting Transformer from language to vision arise from differences between the two domains, such as large variations in the scale of visual entities and the high resolution of pixels in images compared to words in text. To address these differences, we propose a hierarchical Transformer whose representation is computed with Shifted windows. The shifted windowing scheme brings greater efficiency by limiting self-attention computation to non-overlapping local windows while also allowing for cross-window connection. This hierarchical architecture has the flexibility to model at various scales and has linear computational complexity with respect to image size. These qualities of Swin Transformer make it compatible with a broad range of vision tasks, including image classification (87.3 top-1 accuracy on ImageNet-1K) and dense prediction tasks such as object detection (58.7 box AP and 51.1 mask AP on COCO test-dev) and semantic segmentation (53.5 mIoU on ADE20K val). Its performance surpasses the previous state-of-the-art by a large margin of +2.7 box AP and +2.6 mask AP on COCO, and +3.2 mIoU on ADE20K, demonstrating the potential of Transformer-based models as vision backbones. The hierarchical design and the shifted window approach also prove beneficial for all-MLP architectures. The code and models are publicly available at https://github.com/microsoft/Swin-Transformer.", "arxiv_id": "2103.14030", "paper_id": 4911, "venue_id": 1038, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/iccv48922.2021.00986", "work_type": "OTHER", "open_access": true, "openalex_id": "W3138516171", "cited_by_count": 35323, "publication_date": "2021-10-01"}, {"doi": null, "title": "Dropout: a simple way to prevent neural networks from overfitting", "abstract": "Deep neural nets with a large number of parameters are very powerful machine learning systems. However, overfitting is a serious problem in such networks. Large networks are also slow to use, making it difficult to deal with overfitting by combining the predictions of many different large neural nets at test time. Dropout is a technique for addressing this problem. The key idea is to randomly drop units (along with their connections) from the neural network during training. This prevents units from co-adapting too much. During training, dropout samples from an exponential number of different “thinned ” networks. At test time, it is easy to approximate the effect of averaging the predictions of all these thinned networks by simply using a single unthinned network that has smaller weights. This significantly reduces overfitting and gives major improvements over other regularization methods. We show that dropout improves the performance of neural networks on supervised learning tasks in vision, speech recognition, document classification and computational biology, obtaining state-of-the-art results on many benchmark data sets.", "arxiv_id": null, "paper_id": 4912, "venue_id": null, "oa_status": "CLOSED", "paper_url": "http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.669.8604", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2095705004", "cited_by_count": 33412, "publication_date": "2014-01-01"}, {"doi": "10.1109/cvpr.2014.81", "title": "Rich Feature Hierarchies for Accurate Object Detection and Semantic Segmentation", "abstract": "Object detection performance, as measured on the canonical PASCAL VOC dataset, has plateaued in the last few years. The best-performing methods are complex ensemble systems that typically combine multiple low-level image features with high-level context. In this paper, we propose a simple and scalable detection algorithm that improves mean average precision (mAP) by more than 30% relative to the previous best result on VOC 2012 -- achieving a mAP of 53.3%. Our approach combines two key insights: (1) one can apply high-capacity convolutional neural networks (CNNs) to bottom-up region proposals in order to localize and segment objects and (2) when labeled training data is scarce, supervised pre-training for an auxiliary task, followed by domain-specific fine-tuning, yields a significant performance boost. Since we combine region proposals with CNNs, we call our method R-CNN: Regions with CNN features. We also present experiments that provide insight into what the network learns, revealing a rich hierarchy of image features. Source code for the complete system is available at http://www.cs.berkeley.edu/~rbg/rcnn.", "arxiv_id": "1311.2524", "paper_id": 4913, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2014.81", "work_type": "OTHER", "open_access": true, "openalex_id": "W2102605133", "cited_by_count": 32652, "publication_date": "2014-06-01"}, {"doi": "10.1109/cvpr.2016.308", "title": "Rethinking the Inception Architecture for Computer Vision", "abstract": "Convolutional networks are at the core of most state of-the-art computer vision solutions for a wide variety of tasks. Since 2014 very deep convolutional networks started to become mainstream, yielding substantial gains in various benchmarks. Although increased model size and computational cost tend to translate to immediate quality gains for most tasks (as long as enough labeled data is provided for training), computational efficiency and low parameter count are still enabling factors for various use cases such as mobile vision and big-data scenarios. Here we are exploring ways to scale up networks in ways that aim at utilizing the added computation as efficiently as possible by suitably factorized convolutions and aggressive regularization. We benchmark our methods on the ILSVRC 2012 classification challenge validation set demonstrate substantial gains over the state of the art: 21:2% top-1 and 5:6% top-5 error for single frame evaluation using a network with a computational cost of 5 billion multiply-adds per inference and with using less than 25 million parameters. With an ensemble of 4 models and multi-crop evaluation, we report 3:5% top-5 error and 17:3% top-1 error on the validation set and 3:6% top-5 error on the official test set.", "arxiv_id": null, "paper_id": 4914, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2016.308", "work_type": "OTHER", "open_access": false, "openalex_id": "W2183341477", "cited_by_count": 32098, "publication_date": "2016-06-01"}, {"doi": null, "title": "SSD: Single Shot MultiBox Detector", "abstract": "We present a method for detecting objects in images us-ing a single deep neural network. Our approach, named SSD, discretizes the output space of bounding boxes into a set of bounding box priors over different aspect ratios and scales per feature map location. At prediction time, the network generates confidences that each prior corre-sponds to objects of interest and produces adjustments to the prior to better match the object shape. Additionally, the network combines predictions from multiple feature maps with different resolutions to naturally handle objects of var-ious sizes. Our SSD model is simple relative to methods that requires object proposals, such as R-CNN and Multi-Box, because it completely discards the proposal generation step and encapsulates all the computation in a single net-work. This makes SSD easy to train and straightforward to integrate into systems that require a detection component. Experimental results on ILSVRC DET and PASCAL VOC dataset confirm that SSD has comparable performance with methods that utilize an additional object proposal step and yet is 100-1000 × faster. Compared to other single stage methods, SSD has similar or better performance, while pro-viding a unified framework for both training and inference. 1.", "arxiv_id": null, "paper_id": 4915, "venue_id": null, "oa_status": "CLOSED", "paper_url": "http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.717.8707", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W3106250896", "cited_by_count": 31590, "publication_date": "2016-01-16"}, {"doi": "10.1109/cvpr.2017.106", "title": "Feature Pyramid Networks for Object Detection", "abstract": "Feature pyramids are a basic component in recognition systems for detecting objects at different scales. But pyramid representations have been avoided in recent object detectors that are based on deep convolutional networks, partially because they are slow to compute and memory intensive. In this paper, we exploit the inherent multi-scale, pyramidal hierarchy of deep convolutional networks to construct feature pyramids with marginal extra cost. A top-down architecture with lateral connections is developed for building high-level semantic feature maps at all scales. This architecture, called a Feature Pyramid Network (FPN), shows significant improvement as a generic feature extractor in several applications. Using a basic Faster R-CNN system, our method achieves state-of-the-art single-model results on the COCO detection benchmark without bells and whistles, surpassing all existing single-model entries including those from the COCO 2016 challenge winners. In addition, our method can run at 5 FPS on a GPU and thus is a practical and accurate solution to multi-scale object detection. Code will be made publicly available.", "arxiv_id": null, "paper_id": 4916, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2017.106", "work_type": "OTHER", "open_access": false, "openalex_id": "W2565639579", "cited_by_count": 30832, "publication_date": "2017-07-01"}, {"doi": "10.1109/iccv.2017.324", "title": "Focal Loss for Dense Object Detection", "abstract": "The highest accuracy object detectors to date are based on a two-stage approach popularized by R-CNN, where a classifier is applied to a sparse set of candidate object locations. In contrast, one-stage detectors that are applied over a regular, dense sampling of possible object locations have the potential to be faster and simpler, but have trailed the accuracy of two-stage detectors thus far. In this paper, we investigate why this is the case. We discover that the extreme foreground-background class imbalance encountered during training of dense detectors is the central cause. We propose to address this class imbalance by reshaping the standard cross entropy loss such that it down-weights the loss assigned to well-classified examples. Our novel Focal Loss focuses training on a sparse set of hard examples and prevents the vast number of easy negatives from overwhelming the detector during training. To evaluate the effectiveness of our loss, we design and train a simple dense detector we call RetinaNet. Our results show that when trained with the focal loss, RetinaNet is able to match the speed of previous one-stage detectors while surpassing the accuracy of all existing state-of-the-art two-stage detectors.", "arxiv_id": null, "paper_id": 4917, "venue_id": 1039, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/iccv.2017.324", "work_type": "OTHER", "open_access": false, "openalex_id": "W2963351448", "cited_by_count": 30298, "publication_date": "2017-10-01"}, {"doi": "10.1109/iccv.2017.322", "title": "Mask R-CNN", "abstract": "We present a conceptually simple, flexible, and general framework for object instance segmentation. Our approach efficiently detects objects in an image while simultaneously generating a high-quality segmentation mask for each instance. The method, called Mask R-CNN, extends Faster R-CNN by adding a branch for predicting an object mask in parallel with the existing branch for bounding box recognition. Mask R-CNN is simple to train and adds only a small overhead to Faster R-CNN, running at 5 fps. Moreover, Mask R-CNN is easy to generalize to other tasks, e.g., allowing us to estimate human poses in the same framework. We show top results in all three tracks of the COCO suite of challenges, including instance segmentation, bounding-box object detection, and person keypoint detection. Without tricks, Mask R-CNN outperforms all existing, single-model entries on every task, including the COCO 2016 challenge winners. We hope our simple and effective approach will serve as a solid baseline and help ease future research in instance-level recognition. Code will be made available.", "arxiv_id": null, "paper_id": 4918, "venue_id": 1039, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/iccv.2017.322", "work_type": "OTHER", "open_access": true, "openalex_id": "W2963150697", "cited_by_count": 29079, "publication_date": "2017-10-01"}, {"doi": "10.1109/iccv.2015.169", "title": "Fast R-CNN", "abstract": "This paper proposes a Fast Region-based Convolutional Network method (Fast R-CNN) for object detection. Fast R-CNN builds on previous work to efficiently classify object proposals using deep convolutional networks. Compared to previous work, Fast R-CNN employs several innovations to improve training and testing speed while also increasing detection accuracy. Fast R-CNN trains the very deep VGG16 network 9x faster than R-CNN, is 213x faster at test-time, and achieves a higher mAP on PASCAL VOC 2012. Compared to SPPnet, Fast R-CNN trains VGG16 3x faster, tests 10x faster, and is more accurate. Fast R-CNN is implemented in Python and C++ (using Caffe) and is available under the open-source MIT License at https://github.com/rbgirshick/fast-rcnn.", "arxiv_id": null, "paper_id": 4919, "venue_id": 1039, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/iccv.2015.169", "work_type": "OTHER", "open_access": false, "openalex_id": "W1536680647", "cited_by_count": 28067, "publication_date": "2015-12-01"}, {"doi": "10.1109/tnn.1998.712192", "title": "Reinforcement Learning: An Introduction", "abstract": null, "arxiv_id": null, "paper_id": 4920, "venue_id": 1040, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tnn.1998.712192", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W4214717370", "cited_by_count": 27198, "publication_date": "1998-09-01"}, {"doi": "10.1109/tnn.2004.842673", "title": "Reinforcement Learning: An Introduction", "abstract": "An account of key ideas and algorithms in reinforcement learning. The discussion ranges from the history of the field's intellectual foundations to recent developments and applications. Areas studied include reinforcement learning problems in terms of Markov decision problems and solution methods.", "arxiv_id": null, "paper_id": 4921, "venue_id": 1040, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1109/tnn.2004.842673", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2121863487", "cited_by_count": 24493, "publication_date": "2005-01-01"}, {"doi": "10.57702/zp44cu3g", "title": "Learning Multiple Layers of Features from Tiny Images", "abstract": "April 8, 2009Groups at MIT and NYU have collected a dataset of millions of tiny colour images from the web. It is, in principle, an excellent dataset for unsupervised training of deep generative models, but previous researchers who have tried this have found it di cult to learn a good set of lters from the images. We show how to train a multi-layer generative model that learns to extract meaningful features which resemble those found in the human visual cortex. Using a novel parallelization algorithm to distribute the work among multiple machines connected on a network, we show how training such a model can be done in reasonable time. A second problematic aspect of the tiny images dataset is that there are no reliable class labels which makes it hard to use for object recognition experiments. We created two sets of reliable labels. The CIFAR-10 set has 6000 examples of each of 10 classes and the CIFAR-100 set has 600 examples of each of 100 non-overlapping classes. Using these labels, we show that object recognition is signi cantly", "arxiv_id": null, "paper_id": 4922, "venue_id": null, "oa_status": "GREEN", "paper_url": "http://citeseerx.ist.psu.edu/viewdoc/summary?doi=10.1.1.222.9220", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W3118608800", "cited_by_count": 23383, "publication_date": "2024-01-01"}, {"doi": "10.1109/tpami.2017.2699184", "title": "DeepLab: Semantic Image Segmentation with Deep Convolutional Nets, Atrous Convolution, and Fully Connected CRFs", "abstract": "In this work we address the task of semantic image segmentation with Deep Learning and make three main contributions that are experimentally shown to have substantial practical merit. First, we highlight convolution with upsampled filters, or 'atrous convolution', as a powerful tool in dense prediction tasks. Atrous convolution allows us to explicitly control the resolution at which feature responses are computed within Deep Convolutional Neural Networks. It also allows us to effectively enlarge the field of view of filters to incorporate larger context without increasing the number of parameters or the amount of computation. Second, we propose atrous spatial pyramid pooling (ASPP) to robustly segment objects at multiple scales. ASPP probes an incoming convolutional feature layer with filters at multiple sampling rates and effective fields-of-views, thus capturing objects as well as image context at multiple scales. Third, we improve the localization of object boundaries by combining methods from DCNNs and probabilistic graphical models. The commonly deployed combination of max-pooling and downsampling in DCNNs achieves invariance but has a toll on localization accuracy. We overcome this by combining the responses at the final DCNN layer with a fully connected Conditional Random Field (CRF), which is shown both qualitatively and quantitatively to improve localization performance. Our proposed \"DeepLab\" system sets the new state-of-art at the PASCAL VOC-2012 semantic image segmentation task, reaching 79.7 percent mIOU in the test set, and advances the results on three other datasets: PASCAL-Context, PASCAL-Person-Part, and Cityscapes. All of our code is made publicly available online.", "arxiv_id": "1606.00915", "paper_id": 4923, "venue_id": 3, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tpami.2017.2699184", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2412782625", "cited_by_count": 22360, "publication_date": "2017-04-27"}, {"doi": "10.1109/cvpr.2017.690", "title": "YOLO9000: Better, Faster, Stronger", "abstract": "We introduce YOLO9000, a state-of-the-art, real-time object detection system that can detect over 9000 object categories. First we propose various improvements to the YOLO detection method, both novel and drawn from prior work. The improved model, YOLOv2, is state-of-the-art on standard detection tasks like PASCAL VOC and COCO. Using a novel, multi-scale training method the same YOLOv2 model can run at varying sizes, offering an easy tradeoff between speed and accuracy. At 67 FPS, YOLOv2 gets 76.8 mAP on VOC 2007. At 40 FPS, YOLOv2 gets 78.6 mAP, outperforming state-of-the-art methods like Faster RCNN with ResNet and SSD while still running significantly faster. Finally we propose a method to jointly train on object detection and classification. Using this method we train YOLO9000 simultaneously on the COCO detection dataset and the ImageNet classification dataset. Our joint training allows YOLO9000 to predict detections for object classes that dont have labelled detection data. We validate our approach on the ImageNet detection task. YOLO9000 gets 19.7 mAP on the ImageNet detection validation set despite only having detection data for 44 of the 200 classes. On the 156 classes not in COCO, YOLO9000 gets 16.0 mAP. YOLO9000 predicts detections for more than 9000 different object categories, all in real-time.", "arxiv_id": null, "paper_id": 4924, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2017.690", "work_type": "OTHER", "open_access": false, "openalex_id": "W2570343428", "cited_by_count": 19881, "publication_date": "2017-07-01"}, {"doi": "10.1007/s11263-009-0275-4", "title": "The Pascal Visual Object Classes (VOC) Challenge", "abstract": null, "arxiv_id": null, "paper_id": 4925, "venue_id": 22, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s11263-009-0275-4", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2031489346", "cited_by_count": 19538, "publication_date": "2009-09-08"}, {"doi": "10.1007/978-3-030-58452-8_13", "title": "End-to-End Object Detection with Transformers", "abstract": null, "arxiv_id": "2005.12872", "paper_id": 4926, "venue_id": 1036, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/978-3-030-58452-8_13", "work_type": "OTHER", "open_access": true, "openalex_id": "W3030520226", "cited_by_count": 18178, "publication_date": "2020-01-01"}, {"doi": "10.4230/lipics.ecoop.2025.6", "title": "Detecting Functionality-Specific Vulnerabilities via Retrieving Individual Functionality-Equivalent APIs in Open-Source Repositories", "abstract": "Functionality-specific vulnerabilities, which mainly occur in Application Programming Interfaces (APIs) with specific functionalities, are crucial for software developers to detect and avoid. When detecting individual functionality-specific vulnerabilities, the existing two categories of approaches are ineffective because they consider only the API bodies and are unable to handle diverse implementations of functionality-equivalent APIs. To effectively detect functionality-specific vulnerabilities, we propose APISS, the first approach to utilize API doc strings and signatures instead of API bodies. APISS first retrieves functionality-equivalent APIs for APIs with existing vulnerabilities and then migrates Proof-of-Concepts (PoCs) of the existing vulnerabilities for newly detected vulnerable APIs. To retrieve functionality-equivalent APIs, we leverage a Large Language Model for API embedding to improve the accuracy and address the effectiveness and scalability issues suffered by the existing approaches. To migrate PoCs of the existing vulnerabilities for newly detected vulnerable APIs, we design a semi-automatic schema to substantially reduce manual costs. We conduct a comprehensive evaluation to empirically compare APISS with four state-of-the-art approaches of detecting vulnerabilities and two state-of-the-art approaches of retrieving functionality-equivalent APIs. The evaluation subjects include 180 widely used Java repositories using 10 existing vulnerabilities, along with their PoCs. The results show that APISS effectively retrieves functionality-equivalent APIs, achieving a Top-1 Accuracy of 0.81 while the best of the baselines under comparison achieves only 0.55. APISS is highly efficient: the manual costs are within 10 minutes per vulnerability and the end-to-end runtime overhead of testing one candidate API is less than 2 hours. APISS detects 179 new vulnerabilities and receives 60 new CVE IDs, bringing high value to security practice.", "arxiv_id": null, "paper_id": 4927, "venue_id": 1041, "oa_status": "DIAMOND", "paper_url": "https://doi.org/10.4230/lipics.ecoop.2025.6", "work_type": "OTHER", "open_access": true, "openalex_id": "W2964015378", "cited_by_count": 15256, "publication_date": "2025-01-01"}, {"doi": "10.1109/cvpr.2017.634", "title": "Aggregated Residual Transformations for Deep Neural Networks", "abstract": "We present a simple, highly modularized network architecture for image classification. Our network is constructed by repeating a building block that aggregates a set of transformations with the same topology. Our simple design results in a homogeneous, multi-branch architecture that has only a few hyper-parameters to set. This strategy exposes a new dimension, which we call cardinality (the size of the set of transformations), as an essential factor in addition to the dimensions of depth and width. On the ImageNet-1K dataset, we empirically show that even under the restricted condition of maintaining complexity, increasing cardinality is able to improve classification accuracy. Moreover, increasing cardinality is more effective than going deeper or wider when we increase the capacity. Our models, named ResNeXt, are the foundations of our entry to the ILSVRC 2016 classification task in which we secured 2nd place. We further investigate ResNeXt on an ImageNet-5K set and the COCO detection set, also showing better results than its ResNet counterpart. The code and models are publicly available online.", "arxiv_id": "1611.05431", "paper_id": 4928, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2017.634", "work_type": "OTHER", "open_access": true, "openalex_id": "W2549139847", "cited_by_count": 12322, "publication_date": "2017-07-01"}, {"doi": "10.1038/nature06932", "title": "The missing memristor found", "abstract": null, "arxiv_id": null, "paper_id": 4929, "venue_id": 2, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nature06932", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2112181056", "cited_by_count": 11707, "publication_date": "2008-04-30"}, {"doi": "10.1109/cvpr.2018.00813", "title": "Non-local Neural Networks", "abstract": "Both convolutional and recurrent operations are building blocks that process one local neighborhood at a time. In this paper, we present non-local operations as a generic family of building blocks for capturing long-range dependencies. Inspired by the classical non-local means method in computer vision, our non-local operation computes the response at a position as a weighted sum of the features at all positions. This building block can be plugged into many computer vision architectures. On the task of video classification, even without any bells and whistles, our non-local models can compete or outperform current competition winners on both Kinetics and Charades datasets. In static image recognition, our non-local models improve object detection/segmentation and pose estimation on the COCO suite of tasks. Code is available at https://github.com/facebookresearch/video-nonlocal-net .", "arxiv_id": "1711.07971", "paper_id": 4930, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2018.00813", "work_type": "OTHER", "open_access": true, "openalex_id": "W2963091558", "cited_by_count": 11573, "publication_date": "2018-06-01"}, {"doi": "10.1109/tct.1971.1083337", "title": "Memristor-The missing circuit element", "abstract": "A new two-terminal circuit element-called the memristorcharacterized by a relationship between the chargeq(t)\\equiv \\int_{-\\infty}^{t} i(\\tau) d \\tauand the flux-linkage\\varphi(t)\\equiv \\int_{- \\infty}^{t} v(\\tau) d \\tauis introduced as the fourth basic circuit element. An electromagnetic field interpretation of this relationship in terms of a quasi-static expansion of Maxwell's equations is presented. Many circuit-theoretic properties of memistors are derived. It is shown that this element exhibits some peculiar behavior different from that exhibited by resistors, inductors, or capacitors. These properties lead to a number of unique applications which cannot be realized withRLCnetworks alone. Although a physical memristor device without internal power supply has not yet been discovered, operational laboratory models have been built with the help of active circuits. Experimental results are presented to demonstrate the properties and potential applications of memristors.", "arxiv_id": null, "paper_id": 4931, "venue_id": 1042, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tct.1971.1083337", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2162651880", "cited_by_count": 10256, "publication_date": "1971-01-01"}, {"doi": "10.1109/tnn.2008.2005605", "title": "The Graph Neural Network Model", "abstract": "Many underlying relationships among data in several areas of science and engineering, e.g., computer vision, molecular chemistry, molecular biology, pattern recognition, and data mining, can be represented in terms of graphs. In this paper, we propose a new neural network model, called graph neural network (GNN) model, that extends existing neural network methods for processing the data represented in graph domains. This GNN model, which can directly process most of the practically useful types of graphs, e.g., acyclic, cyclic, directed, and undirected, implements a function tau(G,n) is an element of IR(m) that maps a graph G and one of its nodes n into an m-dimensional Euclidean space. A supervised learning algorithm is derived to estimate the parameters of the proposed GNN model. The computational cost of the proposed algorithm is also considered. Some experimental results are shown to validate the proposed learning algorithm, and to demonstrate its generalization capabilities.", "arxiv_id": null, "paper_id": 4932, "venue_id": 1040, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/tnn.2008.2005605", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2116341502", "cited_by_count": 9555, "publication_date": "2008-12-10"}, {"doi": "10.1021/nl904092h", "title": "Nanoscale Memristor Device as Synapse in Neuromorphic Systems", "abstract": "A memristor is a two-terminal electronic device whose conductance can be precisely modulated by charge or flux through it. Here we experimentally demonstrate a nanoscale silicon-based memristor device and show that a hybrid system composed of complementary metal-oxide semiconductor neurons and memristor synapses can support important synaptic functions such as spike timing dependent plasticity. Using memristors as synapses in neuromorphic circuits can potentially offer both high connectivity and high density required for efficient computing.", "arxiv_id": null, "paper_id": 4933, "venue_id": 38, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1021/nl904092h", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2016922062", "cited_by_count": 4176, "publication_date": "2010-03-01"}, {"doi": "10.1126/science.1254642", "title": "A million spiking-neuron integrated circuit with a scalable communication network and interface", "abstract": "Inspired by the brain's structure, we have developed an efficient, scalable, and flexible non-von Neumann architecture that leverages contemporary silicon technology. To demonstrate, we built a 5.4-billion-transistor chip with 4096 neurosynaptic cores interconnected via an intrachip network that integrates 1 million programmable spiking neurons and 256 million configurable synapses. Chips can be tiled in two dimensions via an interchip communication interface, seamlessly scaling the architecture to a cortexlike sheet of arbitrary size. The architecture is well suited to many applications that use complex neural networks in real time, for example, multiobject detection and classification. With 400-pixel-by-240-pixel video input at 30 frames per second, the chip consumes 63 milliwatts.", "arxiv_id": null, "paper_id": 4934, "venue_id": 27, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1126/science.1254642", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2138913040", "cited_by_count": 4153, "publication_date": "2014-08-07"}, {"doi": "10.1038/nnano.2012.240", "title": "Memristive devices for computing", "abstract": null, "arxiv_id": null, "paper_id": 4935, "venue_id": 13, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nnano.2012.240", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2018774711", "cited_by_count": 3882, "publication_date": "2012-12-27"}, {"doi": "10.1038/nmat3054", "title": "Short-term plasticity and long-term potentiation mimicked in single inorganic synapses", "abstract": null, "arxiv_id": null, "paper_id": 4936, "venue_id": 4, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nmat3054", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2071947829", "cited_by_count": 1794, "publication_date": "2011-06-26"}, {"doi": "10.48550/arxiv.1412.6980", "title": "Adam: A Method for Stochastic Optimization", "abstract": "We introduce Adam, an algorithm for first-order gradient-based optimization of stochastic objective functions, based on adaptive estimates of lower-order moments. The method is straightforward to implement, is computationally efficient, has little memory requirements, is invariant to diagonal rescaling of the gradients, and is well suited for problems that are large in terms of data and/or parameters. The method is also appropriate for non-stationary objectives and problems with very noisy and/or sparse gradients. The hyper-parameters have intuitive interpretations and typically require little tuning. Some connections to related algorithms, on which Adam was inspired, are discussed. We also analyze the theoretical convergence properties of the algorithm and provide a regret bound on the convergence rate that is comparable to the best known results under the online convex optimization framework. Empirical results demonstrate that Adam works well in practice and compares favorably to other stochastic optimization methods. Finally, we discuss AdaMax, a variant of Adam based on the infinity norm.", "arxiv_id": "1412.6980", "paper_id": 4937, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1412.6980", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W1522301498", "cited_by_count": 99043, "publication_date": "2014-12-22"}, {"doi": "10.48550/arxiv.1409.1556", "title": "Very Deep Convolutional Networks for Large-Scale Image Recognition", "abstract": "In this work we investigate the effect of the convolutional network depth on its accuracy in the large-scale image recognition setting. Our main contribution is a thorough evaluation of networks of increasing depth using an architecture with very small (3x3) convolution filters, which shows that a significant improvement on the prior-art configurations can be achieved by pushing the depth to 16-19 weight layers. These findings were the basis of our ImageNet Challenge 2014 submission, where our team secured the first and the second places in the localisation and classification tracks respectively. We also show that our representations generalise well to other datasets, where they achieve state-of-the-art results. We have made our two best-performing ConvNet models publicly available to facilitate further research on the use of deep visual representations in computer vision.", "arxiv_id": "1409.1556", "paper_id": 4938, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1409.1556", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W1686810756", "cited_by_count": 88465, "publication_date": "2014-09-04"}, {"doi": "10.65215/2q58a426", "title": "Attention Is All You Need", "abstract": "The dominant sequence transduction models are based on complex recurrent or convolutional neural networks in an encoder-decoder configuration. The best performing models also connect the encoder and decoder through an attention mechanism. We propose a new simple network architecture, the Transformer, based solely on attention mechanisms, dispensing with recurrence and convolutions entirely. Experiments on two machine translation tasks show these models to be superior in quality while being more parallelizable and requiring significantly less time to train. Our model achieves 28.4 BLEU on the WMT 2014 English-to-German translation task, improving over the existing best results, including ensembles by over 2 BLEU. On the WMT 2014 English-to-French translation task, our model establishes a new single-model state-of-the-art BLEU score of 41.8 after training for 3.5 days on eight GPUs, a small fraction of the training costs of the best models from the literature. We show that the Transformer generalizes well to other tasks by applying it successfully to English constituency parsing both with large and limited training data.", "arxiv_id": "1706.03762", "paper_id": 4939, "venue_id": null, "oa_status": "GOLD", "paper_url": "https://doi.org/10.65215/2q58a426", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2626778328", "cited_by_count": 78297, "publication_date": "2025-08-23"}, {"doi": "10.4230/lipics.cosit.2022.18", "title": "AI-Assisted Pipeline for Dynamic Generation of Trustworthy Health Supplement Content at Scale", "abstract": "Although geospatial question answering systems have received increasing attention in recent years, existing prototype systems struggle to properly answer qualitative spatial questions. In this work, we propose a unique framework for answering qualitative spatial questions, which comprises three main components: a geoparser that takes the input questions and extracts place semantic information from text, a reasoning system which is embedded with a crisp reasoner, and finally, answer extraction, which refines the solution space and generates final answers. We present an experimental design to evaluate our framework for point-based cardinal direction calculus (CDC) relations by developing an automated approach for generating three types of synthetic qualitative spatial questions. The initial evaluations of generated answers in our system are promising because a high proportion of answers were labelled correct.", "arxiv_id": "1810.04805", "paper_id": 4940, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1810.04805", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2896457183", "cited_by_count": 44726, "publication_date": "2018-10-11"}, {"doi": "10.48550/arxiv.2005.14165", "title": "Language Models are Few-Shot Learners", "abstract": "Recent work has demonstrated substantial gains on many NLP tasks and benchmarks by pre-training on a large corpus of text followed by fine-tuning on a specific task. While typically task-agnostic in architecture, this method still requires task-specific fine-tuning datasets of thousands or tens of thousands of examples. By contrast, humans can generally perform a new language task from only a few examples or from simple instructions - something which current NLP systems still largely struggle to do. Here we show that scaling up language models greatly improves task-agnostic, few-shot performance, sometimes even reaching competitiveness with prior state-of-the-art fine-tuning approaches. Specifically, we train GPT-3, an autoregressive language model with 175 billion parameters, 10x more than any previous non-sparse language model, and test its performance in the few-shot setting. For all tasks, GPT-3 is applied without any gradient updates or fine-tuning, with tasks and few-shot demonstrations specified purely via text interaction with the model. GPT-3 achieves strong performance on many NLP datasets, including translation, question-answering, and cloze tasks, as well as several tasks that require on-the-fly reasoning or domain adaptation, such as unscrambling words, using a novel word in a sentence, or performing 3-digit arithmetic. At the same time, we also identify some datasets where GPT-3's few-shot learning still struggles, as well as some datasets where GPT-3 faces methodological issues related to training on large web corpora. Finally, we find that GPT-3 can generate samples of news articles which human evaluators have difficulty distinguishing from articles written by humans. We discuss broader societal impacts of this finding and of GPT-3 in general.", "arxiv_id": "2005.14165", "paper_id": 4941, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/2005.14165", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W3030163527", "cited_by_count": 16451, "publication_date": "2020-05-28"}, {"doi": "10.48550/arxiv.1706.02216", "title": "Inductive Representation Learning on Large Graphs", "abstract": "Low-dimensional embeddings of nodes in large graphs have proved extremely useful in a variety of prediction tasks, from content recommendation to identifying protein functions. However, most existing approaches require that all nodes in the graph are present during training of the embeddings; these previous approaches are inherently transductive and do not naturally generalize to unseen nodes. Here we present GraphSAGE, a general, inductive framework that leverages node feature information (e.g., text attributes) to efficiently generate node embeddings for previously unseen data. Instead of training individual embeddings for each node, we learn a function that generates embeddings by sampling and aggregating features from a node's local neighborhood. Our algorithm outperforms strong baselines on three inductive node-classification benchmarks: we classify the category of unseen nodes in evolving information graphs based on citation and Reddit post data, and we show that our algorithm generalizes to completely unseen graphs using a multi-graph dataset of protein-protein interactions.", "arxiv_id": "1706.02216", "paper_id": 4942, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1706.02216", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2624431344", "cited_by_count": 9516, "publication_date": "2017-06-07"}, {"doi": "10.1038/sdata.2016.35", "title": "MIMIC-III, a freely accessible critical care database", "abstract": "MIMIC-III ('Medical Information Mart for Intensive Care') is a large, single-center database comprising information relating to patients admitted to critical care units at a large tertiary care hospital. Data includes vital signs, medications, laboratory measurements, observations and notes charted by care providers, fluid balance, procedure codes, diagnostic codes, imaging reports, hospital length of stay, survival data, and more. The database supports applications including academic and industrial research, quality improvement initiatives, and higher education coursework.", "arxiv_id": null, "paper_id": 4943, "venue_id": 1028, "oa_status": "GOLD", "paper_url": "https://doi.org/10.1038/sdata.2016.35", "work_type": "OTHER", "open_access": true, "openalex_id": "W2396881363", "cited_by_count": 8046, "publication_date": "2016-05-24"}, {"doi": "10.48550/arxiv.1704.01212", "title": "Neural Message Passing for Quantum Chemistry", "abstract": "Supervised learning on molecules has incredible potential to be useful in chemistry, drug discovery, and materials science. Luckily, several promising and closely related neural network models invariant to molecular symmetries have already been described in the literature. These models learn a message passing algorithm and aggregation procedure to compute a function of their entire input graph. At this point, the next step is to find a particularly effective variant of this general approach and apply it to chemical prediction benchmarks until we either solve them or reach the limits of the approach. In this paper, we reformulate existing models into a single common framework we call Message Passing Neural Networks (MPNNs) and explore additional novel variations within this framework. Using MPNNs we demonstrate state of the art results on an important molecular property prediction benchmark; these results are strong enough that we believe future work should focus on datasets with larger molecules or more accurate ground truth labels.", "arxiv_id": "1704.01212", "paper_id": 4944, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1704.01212", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2606780347", "cited_by_count": 5064, "publication_date": "2017-04-04"}, {"doi": "10.5281/zenodo.1286817", "title": "Advances In Deep Learning On Graphs (Gsp'18 Workshop)", "abstract": "Lecture at the EPFL master course A Network Tour of Data Science (https://github.com/mdeff/ntds_2016).", "arxiv_id": null, "paper_id": 4945, "venue_id": 454, "oa_status": "GREEN", "paper_url": "https://figshare.com/articles/Deep_Learning_on_Graphs_NTDS_16_/11494446", "work_type": "DATASET", "open_access": true, "openalex_id": "W2964321699", "cited_by_count": 4614, "publication_date": "2016-11-22"}, {"doi": "10.1109/cvpr.2018.00745", "title": "Squeeze-and-Excitation Networks", "abstract": "Convolutional neural networks are built upon the convolution operation, which extracts informative features by fusing spatial and channel-wise information together within local receptive fields. In order to boost the representational power of a network, several recent approaches have shown the benefit of enhancing spatial encoding. In this work, we focus on the channel relationship and propose a novel architectural unit, which we term the \"Squeeze-and-Excitation\" (SE) block, that adaptively recalibrates channel-wise feature responses by explicitly modelling interdependencies between channels. We demonstrate that by stacking these blocks together, we can construct SENet architectures that generalise extremely well across challenging datasets. Crucially, we find that SE blocks produce significant performance improvements for existing state-of-the-art deep architectures at minimal additional computational cost. SENets formed the foundation of our ILSVRC 2017 classification submission which won first place and significantly reduced the top-5 error to 2.251%, achieving a ~25% relative improvement over the winning entry of 2016. Code and models are available at https://github.com/hujie-frank/SENet.", "arxiv_id": null, "paper_id": 4948, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2018.00745", "work_type": "OTHER", "open_access": false, "openalex_id": "W2752782242", "cited_by_count": 35554, "publication_date": "2018-06-01"}, {"doi": "10.3115/v1/d14-1162", "title": "Glove: Global Vectors for Word Representation", "abstract": "Recent methods for learning vector space representations of words have succeeded in capturing fine-grained semantic and syntactic regularities using vector arith-metic, but the origin of these regularities has remained opaque. We analyze and make explicit the model properties needed for such regularities to emerge in word vectors. The result is a new global log-bilinear regression model that combines the advantages of the two major model families in the literature: global matrix factorization and local context window methods. Our model efficiently leverages statistical information by training only on the nonzero elements in a word-word co-occurrence matrix, rather than on the en-tire sparse matrix or on individual context windows in a large corpus. The model pro-duces a vector space with meaningful sub-structure, as evidenced by its performance of 75 % on a recent word analogy task. It also outperforms related models on simi-larity tasks and named entity recognition. 1", "arxiv_id": null, "paper_id": 4949, "venue_id": 1044, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.3115/v1/d14-1162", "work_type": "OTHER", "open_access": false, "openalex_id": "W2250539671", "cited_by_count": 33591, "publication_date": "2014-01-01"}, {"doi": "10.1109/cvpr.2005.177", "title": "Histograms of Oriented Gradients for Human Detection", "abstract": "We study the question of feature sets for robust visual object recognition; adopting linear SVM based human detection as a test case. After reviewing existing edge and gradient based descriptors, we show experimentally that grids of histograms of oriented gradient (HOG) descriptors significantly outperform existing feature sets for human detection. We study the influence of each stage of the computation on performance, concluding that fine-scale gradients, fine orientation binning, relatively coarse spatial binning, and high-quality local contrast normalization in overlapping descriptor blocks are all important for good results. The new approach gives near-perfect separation on the original MIT pedestrian database, so we introduce a more challenging dataset containing over 1800 annotated human images with a large range of pose variations and backgrounds.", "arxiv_id": null, "paper_id": 4950, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2005.177", "work_type": "OTHER", "open_access": true, "openalex_id": "W2161969291", "cited_by_count": 33581, "publication_date": "2005-07-27"}, {"doi": null, "title": "Visualizing Data using t-SNE", "abstract": "We present a new technique called “t-SNE” that visualizes high-dimensional data by giving each datapoint a location in a two or three-dimensional map. The technique is a variation of Stochastic Neighbor Embedding (Hinton and Roweis, 2002) that is much easier to optimize, and produces significantly better visualizations by reducing the tendency to crowd points together in the center of the map. t-SNE is better than existing techniques at creating a single map that reveals structure at many different scales. This is particularly important for high-dimensional data that lie on several different, but related, low-dimensional manifolds, such as images of objects from multiple classes seen from multiple viewpoints. For visualizing the structure of very large datasets, we show how t-SNE can use random walks on neighborhood graphs to allow the implicit structure of all of the data to influence the way in which a subset of the data is displayed. We illustrate the performance of t-SNE on a wide variety of datasets and compare it with many other non-parametric visualization techniques, including Sammon mapping, Isomap, and Locally Linear Embedding. The visualizations produced by t-SNE are significantly better than those produced by the other techniques on almost all of the datasets.", "arxiv_id": null, "paper_id": 4951, "venue_id": 769, "oa_status": "CLOSED", "paper_url": "http://isplab.tudelft.nl/sites/default/files/vandermaaten08a.pdf", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2187089797", "cited_by_count": 33046, "publication_date": "2008-01-01"}, {"doi": "10.1038/323533a0", "title": "Learning representations by back-propagating errors", "abstract": null, "arxiv_id": null, "paper_id": 4952, "venue_id": 2, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/323533a0", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W1498436455", "cited_by_count": 31834, "publication_date": "1986-10-01"}, {"doi": "10.1109/cvpr.2018.00474", "title": "MobileNetV2: Inverted Residuals and Linear Bottlenecks", "abstract": "In this paper we describe a new mobile architecture, MobileNetV2, that improves the state of the art performance of mobile models on multiple tasks and benchmarks as well as across a spectrum of different model sizes. We also describe efficient ways of applying these mobile models to object detection in a novel framework we call SSDLite. Additionally, we demonstrate how to build mobile semantic segmentation models through a reduced form of DeepLabv3 which we call Mobile DeepLabv3. is based on an inverted residual structure where the shortcut connections are between the thin bottleneck layers. The intermediate expansion layer uses lightweight depthwise convolutions to filter features as a source of non-linearity. Additionally, we find that it is important to remove non-linearities in the narrow layers in order to maintain representational power. We demonstrate that this improves performance and provide an intuition that led to this design. Finally, our approach allows decoupling of the input/output domains from the expressiveness of the transformation, which provides a convenient framework for further analysis. We measure our performance on ImageNet [1] classification, COCO object detection [2], VOC image segmentation [3]. We evaluate the trade-offs between accuracy, and number of operations measured by multiply-adds (MAdd), as well as actual latency, and the number of parameters.", "arxiv_id": "1801.04381", "paper_id": 4953, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2018.00474", "work_type": "OTHER", "open_access": true, "openalex_id": "W2963163009", "cited_by_count": 28685, "publication_date": "2018-06-01"}, {"doi": "10.3115/v1/d14-1179", "title": "Learning Phrase Representations using RNN Encoder–Decoder for Statistical Machine Translation", "abstract": "Kyunghyun Cho, Bart van Merriënboer, Caglar Gulcehre, Dzmitry Bahdanau, Fethi Bougares, Holger Schwenk, Yoshua Bengio. Proceedings of the 2014 Conference on Empirical Methods in Natural Language Processing (EMNLP). 2014.", "arxiv_id": null, "paper_id": 4955, "venue_id": 1044, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.3115/v1/d14-1179", "work_type": "OTHER", "open_access": true, "openalex_id": "W2157331557", "cited_by_count": 25486, "publication_date": "2014-01-01"}, {"doi": "10.1109/cvpr.2017.195", "title": "Xception: Deep Learning with Depthwise Separable Convolutions", "abstract": "We present an interpretation of Inception modules in convolutional neural networks as being an intermediate step in-between regular convolution and the depthwise separable convolution operation (a depthwise convolution followed by a pointwise convolution). In this light, a depthwise separable convolution can be understood as an Inception module with a maximally large number of towers. This observation leads us to propose a novel deep convolutional neural network architecture inspired by Inception, where Inception modules have been replaced with depthwise separable convolutions. We show that this architecture, dubbed Xception, slightly outperforms Inception V3 on the ImageNet dataset (which Inception V3 was designed for), and significantly outperforms Inception V3 on a larger image classification dataset comprising 350 million images and 17,000 classes. Since the Xception architecture has the same number of parameters as Inception V3, the performance gains are not due to increased capacity but rather to a more efficient use of model parameters.", "arxiv_id": null, "paper_id": 4958, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2017.195", "work_type": "OTHER", "open_access": false, "openalex_id": "W2531409750", "cited_by_count": 20346, "publication_date": "2017-07-01"}, {"doi": "10.1109/iccv.2015.123", "title": "Delving Deep into Rectifiers: Surpassing Human-Level Performance on ImageNet Classification", "abstract": "Rectified activation units (rectifiers) are essential for state-of-the-art neural networks. In this work, we study rectifier neural networks for image classification from two aspects. First, we propose a Parametric Rectified Linear Unit (PReLU) that generalizes the traditional rectified unit. PReLU improves model fitting with nearly zero extra computational cost and little overfitting risk. Second, we derive a robust initialization method that particularly considers the rectifier nonlinearities. This method enables us to train extremely deep rectified models directly from scratch and to investigate deeper or wider network architectures. Based on the learnable activation and advanced initialization, we achieve 4.94% top-5 test error on the ImageNet 2012 classification dataset. This is a 26% relative improvement over the ILSVRC 2014 winner (GoogLeNet, 6.66% [33]). To our knowledge, our result is the first to surpass the reported human-level performance (5.1%, [26]) on this dataset.", "arxiv_id": "1502.01852", "paper_id": 4959, "venue_id": 1039, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/iccv.2015.123", "work_type": "OTHER", "open_access": true, "openalex_id": "W1677182931", "cited_by_count": 19725, "publication_date": "2015-12-01"}, {"doi": "10.3156/jsoft.29.5_177_2", "title": "GAN（Generative Adversarial Nets）", "abstract": "We propose a new framework for estimating generative models via an adversarial process, in which we simultaneously train two models: a generative model G that captures the data distribution, and a discriminative model D that estimates the probability that a sample came from the training data rather than G. The training procedure for G is to maximize the probability of D making a mistake. This framework corresponds to a minimax two-player game. In the space of arbitrary functions G and D, a unique solution exists, with G recovering the training data distribution and D equal to ½ everywhere. In the case where G and D are defined by multilayer perceptrons, the entire system can be trained with backpropagation. There is no need for any Markov chains or unrolled approximate inference networks during either training or generation of samples. Experiments demonstrate the potential of the framework through qualitative and quantitative evaluation of the generated samples.", "arxiv_id": null, "paper_id": 4960, "venue_id": 1046, "oa_status": "DIAMOND", "paper_url": "https://doi.org/10.3156/jsoft.29.5_177_2", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2099471712", "cited_by_count": 19266, "publication_date": "2017-10-15"}, {"doi": "10.1109/cvpr.2017.660", "title": "Pyramid Scene Parsing Network", "abstract": "Scene parsing is challenging for unrestricted open vocabulary and diverse scenes. In this paper, we exploit the capability of global context information by different-region-based context aggregation through our pyramid pooling module together with the proposed pyramid scene parsing network (PSPNet). Our global prior representation is effective to produce good quality results on the scene parsing task, while PSPNet provides a superior framework for pixel-level prediction. The proposed approach achieves state-of-the-art performance on various datasets. It came first in ImageNet scene parsing challenge 2016, PASCAL VOC 2012 benchmark and Cityscapes benchmark. A single PSPNet yields the new record of mIoU accuracy 85.4% on PASCAL VOC 2012 and accuracy 80.2% on Cityscapes.", "arxiv_id": null, "paper_id": 4961, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr.2017.660", "work_type": "OTHER", "open_access": false, "openalex_id": "W2560023338", "cited_by_count": 16318, "publication_date": "2017-07-01"}, {"doi": "10.1007/978-3-319-10590-1_53", "title": "Visualizing and Understanding Convolutional Networks", "abstract": null, "arxiv_id": null, "paper_id": 4962, "venue_id": 1036, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1007/978-3-319-10590-1_53", "work_type": "OTHER", "open_access": true, "openalex_id": "W1849277567", "cited_by_count": 15825, "publication_date": "2014-01-01"}, {"doi": "10.18653/v1/n18-1202", "title": "Deep Contextualized Word Representations", "abstract": "Matthew E. Peters, Mark Neumann, Mohit Iyyer, Matt Gardner, Christopher Clark, Kenton Lee, Luke Zettlemoyer. Proceedings of the 2018 Conference of the North American Chapter of the Association for Computational Linguistics: Human Language Technologies, Volume 1 (Long Papers). 2018.", "arxiv_id": "1802.05365", "paper_id": 4964, "venue_id": 1037, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.18653/v1/n18-1202", "work_type": "OTHER", "open_access": true, "openalex_id": "W2787560479", "cited_by_count": 11990, "publication_date": "2018-01-01"}, {"doi": "10.1145/2939672.2939754", "title": "node2vec", "abstract": "Prediction tasks over nodes and edges in networks require careful effort in engineering features used by learning algorithms. Recent research in the broader field of representation learning has led to significant progress in automating prediction by learning the features themselves. However, present feature learning approaches are not expressive enough to capture the diversity of connectivity patterns observed in networks. Here we propose node2vec, an algorithmic framework for learning continuous feature representations for nodes in networks. In node2vec, we learn a mapping of nodes to a low-dimensional space of features that maximizes the likelihood of preserving network neighborhoods of nodes. We define a flexible notion of a node's network neighborhood and design a biased random walk procedure, which efficiently explores diverse neighborhoods. Our algorithm generalizes prior work which is based on rigid notions of network neighborhoods, and we argue that the added flexibility in exploring neighborhoods is the key to learning richer representations.", "arxiv_id": null, "paper_id": 4965, "venue_id": 1047, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1145/2939672.2939754", "work_type": "OTHER", "open_access": false, "openalex_id": "W2962756421", "cited_by_count": 10760, "publication_date": "2016-08-08"}, {"doi": "10.1145/2623330.2623732", "title": "DeepWalk", "abstract": "We present DeepWalk, a novel approach for learning latent representations of vertices in a network. These latent representations encode social relations in a continuous vector space, which is easily exploited by statistical models. DeepWalk generalizes recent advancements in language modeling and unsupervised feature learning (or deep learning) from sequences of words to graphs.", "arxiv_id": "1403.6652", "paper_id": 4966, "venue_id": 1047, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1145/2623330.2623732", "work_type": "OTHER", "open_access": true, "openalex_id": "W2154851992", "cited_by_count": 10114, "publication_date": "2014-08-22"}, {"doi": "10.1109/cvpr.2018.00644", "title": "Cascade R-CNN: Delving Into High Quality Object Detection", "abstract": "In object detection, an intersection over union (IoU) threshold is required to define positives and negatives. An object detector, trained with low IoU threshold, e.g. 0.5, usually produces noisy detections. However, detection performance tends to degrade with increasing the IoU thresholds. Two main factors are responsible for this: 1) overfitting during training, due to exponentially vanishing positive samples, and 2) inference-time mismatch between the IoUs for which the detector is optimal and those of the input hypotheses. A multi-stage object detection architecture, the Cascade R-CNN, is proposed to address these problems. It consists of a sequence of detectors trained with increasing IoU thresholds, to be sequentially more selective against close false positives. The detectors are trained stage by stage, leveraging the observation that the output of a detector is a good distribution for training the next higher quality detector. The resampling of progressively improved hypotheses guarantees that all detectors have a positive set of examples of equivalent size, reducing the overfitting problem. The same cascade procedure is applied at inference, enabling a closer match between the hypotheses and the detector quality of each stage. A simple implementation of the Cascade R-CNN is shown to surpass all single-model object detectors on the challenging COCO dataset. Experiments also show that the Cascade R-CNN is widely applicable across detector architectures, achieving consistent gains independently of the baseline detector strength. The code is available at https://github.com/zhaoweicai/cascade-rcnn.", "arxiv_id": "1712.00726", "paper_id": 4967, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2018.00644", "work_type": "OTHER", "open_access": true, "openalex_id": "W2964241181", "cited_by_count": 7345, "publication_date": "2018-06-01"}, {"doi": "10.1007/bf00992696", "title": "Simple statistical gradient-following algorithms for connectionist reinforcement learning", "abstract": null, "arxiv_id": null, "paper_id": 4968, "venue_id": 785, "oa_status": "BRONZE", "paper_url": "https://doi.org/10.1007/bf00992696", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2119717200", "cited_by_count": 7002, "publication_date": "1992-05-01"}, {"doi": "10.1007/s11263-013-0620-5", "title": "Selective Search for Object Recognition", "abstract": null, "arxiv_id": null, "paper_id": 4969, "venue_id": 22, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1007/s11263-013-0620-5", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2088049833", "cited_by_count": 5978, "publication_date": "2013-04-01"}, {"doi": "10.1109/iccv48922.2021.00061", "title": "Pyramid Vision Transformer: A Versatile Backbone for Dense Prediction without Convolutions", "abstract": "Although convolutional neural networks (CNNs) have achieved great success in computer vision, this work investigates a simpler, convolution-free backbone network use-fid for many dense prediction tasks. Unlike the recently-proposed Vision Transformer (ViT) that was designed for image classification specifically, we introduce the Pyramid Vision Transformer (PVT), which overcomes the difficulties of porting Transformer to various dense prediction tasks. PVT has several merits compared to current state of the arts. (1) Different from ViT that typically yields low-resolution outputs and incurs high computational and memory costs, PVT not only can be trained on dense partitions of an image to achieve high output resolution, which is important for dense prediction, but also uses a progressive shrinking pyramid to reduce the computations of large feature maps. (2) PVT inherits the advantages of both CNN and Transformer, making it a unified backbone for various vision tasks without convolutions, where it can be used as a direct replacement for CNN backbones. (3) We validate PVT through extensive experiments, showing that it boosts the performance of many downstream tasks, including object detection, instance and semantic segmentation. For example, with a comparable number of parameters, PVT+RetinaNet achieves 40.4 AP on the COCO dataset, surpassing ResNet50+RetinNet (36.3 AP) by 4.1 absolute AP (see Figure 2). We hope that PVT could, serre as an alternative and useful backbone for pixel-level predictions and facilitate future research.", "arxiv_id": null, "paper_id": 4971, "venue_id": 1038, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/iccv48922.2021.00061", "work_type": "OTHER", "open_access": false, "openalex_id": "W3131500599", "cited_by_count": 5244, "publication_date": "2021-10-01"}, {"doi": "10.1146/annurev.physiol.64.092501.114547", "title": "Short-Term Synaptic Plasticity", "abstract": "Synaptic transmission is a dynamic process. Postsynaptic responses wax and wane as presynaptic activity evolves. This prominent characteristic of chemical synaptic transmission is a crucial determinant of the response properties of synapses and, in turn, of the stimulus properties selected by neural networks and of the patterns of activity generated by those networks. This review focuses on synaptic changes that result from prior activity in the synapse under study, and is restricted to short-term effects that last for at most a few minutes. Forms of synaptic enhancement, such as facilitation, augmentation, and post-tetanic potentiation, are usually attributed to effects of a residual elevation in presynaptic [Ca(2+)]i, acting on one or more molecular targets that appear to be distinct from the secretory trigger responsible for fast exocytosis and phasic release of transmitter to single action potentials. We discuss the evidence for this hypothesis, and the origins of the different kinetic phases of synaptic enhancement, as well as the interpretation of statistical changes in transmitter release and roles played by other factors such as alterations in presynaptic Ca(2+) influx or postsynaptic levels of [Ca(2+)]i. Synaptic depression dominates enhancement at many synapses. Depression is usually attributed to depletion of some pool of readily releasable vesicles, and various forms of the depletion model are discussed. Depression can also arise from feedback activation of presynaptic receptors and from postsynaptic processes such as receptor desensitization. In addition, glial-neuronal interactions can contribute to short-term synaptic plasticity. Finally, we summarize the recent literature on putative molecular players in synaptic plasticity and the effects of genetic manipulations and other modulatory influences.", "arxiv_id": null, "paper_id": 4972, "venue_id": 1048, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1146/annurev.physiol.64.092501.114547", "work_type": "REVIEW", "open_access": false, "openalex_id": "W2112927743", "cited_by_count": 5052, "publication_date": "2002-03-01"}, {"doi": "10.1523/jneurosci.18-24-10464.1998", "title": "Synaptic Modifications in Cultured Hippocampal Neurons: Dependence on Spike Timing, Synaptic Strength, and Postsynaptic Cell Type", "abstract": "In cultures of dissociated rat hippocampal neurons, persistent potentiation and depression of glutamatergic synapses were induced by correlated spiking of presynaptic and postsynaptic neurons. The relative timing between the presynaptic and postsynaptic spiking determined the direction and the extent of synaptic changes. Repetitive postsynaptic spiking within a time window of 20 msec after presynaptic activation resulted in long-term potentiation (LTP), whereas postsynaptic spiking within a window of 20 msec before the repetitive presynaptic activation led to long-term depression (LTD). Significant LTP occurred only at synapses with relatively low initial strength, whereas the extent of LTD did not show obvious dependence on the initial synaptic strength. Both LTP and LTD depended on the activation of NMDA receptors and were absent in cases in which the postsynaptic neurons were GABAergic in nature. Blockade of L-type calcium channels with nimodipine abolished the induction of LTD and reduced the extent of LTP. These results underscore the importance of precise spike timing, synaptic strength, and postsynaptic cell type in the activity-induced modification of central synapses and suggest that Hebb's rule may need to incorporate a quantitative consideration of spike timing that reflects the narrow and asymmetric window for the induction of synaptic modification.", "arxiv_id": null, "paper_id": 4973, "venue_id": 1049, "oa_status": "HYBRID", "paper_url": "https://doi.org/10.1523/jneurosci.18-24-10464.1998", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2147101007", "cited_by_count": 4742, "publication_date": "1998-12-15"}, {"doi": "10.1109/5.58356", "title": "Neuromorphic electronic systems", "abstract": "It is shown that for many problems, particularly those in which the input data are ill-conditioned and the computation can be specified in a relative manner, biological solutions are many orders of magnitude more effective than those using digital methods. This advantage can be attributed principally to the use of elementary physical phenomena as computational primitives, and to the representation of information by the relative values of analog signals rather than by the absolute values of digital signals. This approach requires adaptive techniques to mitigate the effects of component differences. This kind of adaptation leads naturally to systems that learn about their environment. Large-scale adaptive analog systems are more robust to component degradation and failure than are more conventional systems, and they use far less power. For this reason, adaptive analog technology can be expected to utilize the full potential of wafer-scale silicon fabrication.>", "arxiv_id": null, "paper_id": 4975, "venue_id": 12, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/5.58356", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2163630896", "cited_by_count": 2369, "publication_date": "1990-01-01"}, {"doi": "10.1126/science.aao0098", "title": "A bioinspired flexible organic artificial afferent nerve", "abstract": "The distributed network of receptors, neurons, and synapses in the somatosensory system efficiently processes complex tactile information. We used flexible organic electronics to mimic the functions of a sensory nerve. Our artificial afferent nerve collects pressure information (1 to 80 kilopascals) from clusters of pressure sensors, converts the pressure information into action potentials (0 to 100 hertz) by using ring oscillators, and integrates the action potentials from multiple ring oscillators with a synaptic transistor. Biomimetic hierarchical structures can detect movement of an object, combine simultaneous pressure inputs, and distinguish braille characters. Furthermore, we connected our artificial afferent nerve to motor nerves to construct a hybrid bioelectronic reflex arc to actuate muscles. Our system has potential applications in neurorobotics and neuroprosthetics.", "arxiv_id": null, "paper_id": 4978, "venue_id": 27, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1126/science.aao0098", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2807551379", "cited_by_count": 1459, "publication_date": "2018-06-01"}, {"doi": "10.1021/nl201040y", "title": "Nanoelectronic Programmable Synapses Based on Phase Change Materials for Brain-Inspired Computing", "abstract": "Brain-inspired computing is an emerging field, which aims to extend the capabilities of information technology beyond digital logic. A compact nanoscale device, emulating biological synapses, is needed as the building block for brain-like computational systems. Here, we report a new nanoscale electronic synapse based on technologically mature phase change materials employed in optical data storage and nonvolatile memory applications. We utilize continuous resistance transitions in phase change materials to mimic the analog nature of biological synapses, enabling the implementation of a synaptic learning rule. We demonstrate different forms of spike-timing-dependent plasticity using the same nanoscale synapse with picojoule level energy consumption.", "arxiv_id": null, "paper_id": 4979, "venue_id": 38, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1021/nl201040y", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2334364695", "cited_by_count": 1264, "publication_date": "2011-06-14"}, {"doi": "10.1038/nmat3510", "title": "A scalable neuristor built with Mott memristors", "abstract": null, "arxiv_id": null, "paper_id": 4980, "venue_id": 4, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1038/nmat3510", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2129610161", "cited_by_count": 1038, "publication_date": "2012-12-14"}, {"doi": "10.48550/arxiv.1912.01703", "title": "PyTorch: An Imperative Style, High-Performance Deep Learning Library", "abstract": "Deep learning frameworks have often focused on either usability or speed, but not both. PyTorch is a machine learning library that shows that these two goals are in fact compatible: it provides an imperative and Pythonic programming style that supports code as a model, makes debugging easy and is consistent with other popular scientific computing libraries, while remaining efficient and supporting hardware accelerators such as GPUs. In this paper, we detail the principles that drove the implementation of PyTorch and how they are reflected in its architecture. We emphasize that every aspect of PyTorch is a regular Python program under the full control of its user. We also explain how the careful and pragmatic implementation of the key components of its runtime enables them to work together to achieve compelling performance. We demonstrate the efficiency of individual subsystems, as well as the overall speed of PyTorch on several common benchmarks.", "arxiv_id": "1912.01703", "paper_id": 4982, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1912.01703", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2970971581", "cited_by_count": 31493, "publication_date": "2019-12-03"}, {"doi": "10.48550/arxiv.1310.4546", "title": "Distributed Representations of Words and Phrases and their Compositionality", "abstract": "The recently introduced continuous Skip-gram model is an efficient method for learning high-quality distributed vector representations that capture a large number of precise syntactic and semantic word relationships. In this paper we present several extensions that improve both the quality of the vectors and the training speed. By subsampling of the frequent words we obtain significant speedup and also learn more regular word representations. We also describe a simple alternative to the hierarchical softmax called negative sampling. An inherent limitation of word representations is their indifference to word order and their inability to represent idiomatic phrases. For example, the meanings of \"Canada\" and \"Air\" cannot be easily combined to obtain \"Air Canada\". Motivated by this example, we present a simple method for finding phrases in text, and show that learning good vector representations for millions of phrases is possible.", "arxiv_id": "1310.4546", "paper_id": 4983, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1310.4546", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2153579005", "cited_by_count": 24515, "publication_date": "2013-10-16"}, {"doi": "10.48550/arxiv.1905.11946", "title": "EfficientNet: Rethinking Model Scaling for Convolutional Neural Networks", "abstract": "Convolutional Neural Networks (ConvNets) are commonly developed at a fixed resource budget, and then scaled up for better accuracy if more resources are available. In this paper, we systematically study model scaling and identify that carefully balancing network depth, width, and resolution can lead to better performance. Based on this observation, we propose a new scaling method that uniformly scales all dimensions of depth/width/resolution using a simple yet highly effective compound coefficient. We demonstrate the effectiveness of this method on scaling up MobileNets and ResNet. To go even further, we use neural architecture search to design a new baseline network and scale it up to obtain a family of models, called EfficientNets, which achieve much better accuracy and efficiency than previous ConvNets. In particular, our EfficientNet-B7 achieves state-of-the-art 84.3% top-1 accuracy on ImageNet, while being 8.4x smaller and 6.1x faster on inference than the best existing ConvNet. Our EfficientNets also transfer well and achieve state-of-the-art accuracy on CIFAR-100 (91.7%), Flowers (98.8%), and 3 other transfer learning datasets, with an order of magnitude fewer parameters. Source code is at https://github.com/tensorflow/tpu/tree/master/models/official/efficientnet.", "arxiv_id": "1905.11946", "paper_id": 4984, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1905.11946", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2946948417", "cited_by_count": 16836, "publication_date": "2019-05-28"}, {"doi": "10.4230/lipics.cp.2025.31", "title": "HISTORIAE, History of Socio-Cultural Transformation as Linguistic Data Science. A Humanities Use Case", "abstract": "Given a combinatorial optimisation problem, there are typically multiple ways of modelling it for presentation to an automated solver. Choosing the right combination of model and target solver can have a significant impact on the effectiveness of the solving process. The best combination of model and solver can also be instance-dependent: there may not exist a single combination that works best for all instances of the same problem. We consider the task of building machine learning models to automatically select the best combination for a problem instance. Critical to the learning process is to define instance features, which serve as input to the selection model. Our contribution is the automatic learning of instance features directly from the high-level representation of a problem instance using a transformer encoder. We evaluate the performance of our approach using the Essence modelling language via a case study of three problem classes.", "arxiv_id": "1907.11692", "paper_id": 4985, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1907.11692", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2965373594", "cited_by_count": 16507, "publication_date": "2019-07-26"}, {"doi": "10.48550/arxiv.1606.09375", "title": "Convolutional Neural Networks on Graphs with Fast Localized Spectral Filtering", "abstract": "In this work, we are interested in generalizing convolutional neural networks (CNNs) from low-dimensional regular grids, where image, video and speech are represented, to high-dimensional irregular domains, such as social networks, brain connectomes or words' embedding, represented by graphs. We present a formulation of CNNs in the context of spectral graph theory, which provides the necessary mathematical background and efficient numerical schemes to design fast localized convolutional filters on graphs. Importantly, the proposed technique offers the same linear computational complexity and constant learning complexity as classical CNNs, while being universal to any graph structure. Experiments on MNIST and 20NEWS demonstrate the ability of this novel deep learning system to learn local, stationary, and compositional features on graphs.", "arxiv_id": "1606.09375", "paper_id": 4988, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1606.09375", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2468907370", "cited_by_count": 4885, "publication_date": "2016-06-30"}, {"doi": "10.48550/arxiv.1312.6203", "title": "Spectral Networks and Locally Connected Networks on Graphs", "abstract": "Convolutional Neural Networks are extremely efficient architectures in image and audio recognition tasks, thanks to their ability to exploit the local translational invariance of signal classes over their domain. In this paper we consider possible generalizations of CNNs to signals defined on more general domains without the action of a translation group. In particular, we propose two constructions, one based upon a hierarchical clustering of the domain, and another based on the spectrum of the graph Laplacian. We show through experiments that for low-dimensional graphs it is possible to learn convolutional layers with a number of parameters independent of the input size, resulting in efficient deep architectures.", "arxiv_id": "1312.6203", "paper_id": 4990, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1312.6203", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W1662382123", "cited_by_count": 3820, "publication_date": "2013-12-21"}, {"doi": "10.48550/arxiv.1509.09292", "title": "Convolutional Networks on Graphs for Learning Molecular Fingerprints", "abstract": "We introduce a convolutional neural network that operates directly on graphs. These networks allow end-to-end learning of prediction pipelines whose inputs are graphs of arbitrary size and shape. The architecture we present generalizes standard molecular feature extraction methods based on circular fingerprints. We show that these data-driven features are more interpretable, and have better predictive performance on a variety of tasks.", "arxiv_id": "1509.09292", "paper_id": 4992, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1509.09292", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2173027866", "cited_by_count": 2623, "publication_date": "2015-09-30"}, {"doi": "10.1126/science.1127647", "title": "Reducing the Dimensionality of Data with Neural Networks", "abstract": "High-dimensional data can be converted to low-dimensional codes by training a multilayer neural network with a small central layer to reconstruct high-dimensional input vectors. Gradient descent can be used for fine-tuning the weights in such \"autoencoder\" networks, but this works well only if the initial weights are close to a good solution. We describe an effective way of initializing the weights that allows deep autoencoder networks to learn low-dimensional codes that work much better than principal components analysis as a tool to reduce the dimensionality of data.", "arxiv_id": null, "paper_id": 4998, "venue_id": 27, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1126/science.1127647", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2100495367", "cited_by_count": 20912, "publication_date": "2006-07-27"}, {"doi": "10.1609/aaai.v31i1.11231", "title": "Inception-v4, Inception-ResNet and the Impact of Residual Connections on Learning", "abstract": "Very deep convolutional networks have been central to the largest advances in image recognition performance in recent years. One example is the Inception architecture that has been shown to achieve very good performance at relatively low computational cost. Recently, the introduction of residual connections in conjunction with a more traditional architecture has yielded state-of-the-art performance in the 2015 ILSVRC challenge; its performance was similar to the latest generation Inception-v3 network. This raises the question: Are there any benefits to combining Inception architectures with residual connections? Here we give clear empirical evidence that training with residual connections accelerates the training of Inception networks significantly. There is also some evidence of residual Inception networks outperforming similarly expensive Inception networks without residual connections by a thin margin. We also present several new streamlined architectures for both residual and non-residual Inception networks. These variations improve the single-frame recognition performance on the ILSVRC 2012 classification task significantly. We further demonstrate how proper activation scaling stabilizes the training of very wide residual Inception networks. With an ensemble of three residual and one Inception-v4 networks, we achieve 3.08% top-5 error on the test set of the ImageNet classification (CLS) challenge.", "arxiv_id": null, "paper_id": 5006, "venue_id": 239, "oa_status": "GREEN", "paper_url": "https://ojs.aaai.org/index.php/AAAI/article/view/11231", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2964350391", "cited_by_count": 13486, "publication_date": "2017-02-12"}, {"doi": "10.1162/neco.1989.1.4.541", "title": "Backpropagation Applied to Handwritten Zip Code Recognition", "abstract": "The ability of learning networks to generalize can be greatly enhanced by providing constraints from the task domain. This paper demonstrates how such constraints can be integrated into a backpropagation network through the architecture of the network. This approach has been successfully applied to the recognition of handwritten zip code digits provided by the U.S. Postal Service. A single network learns the entire recognition operation, going from the normalized image of the character to the final classification.", "arxiv_id": null, "paper_id": 5011, "venue_id": 46, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1162/neco.1989.1.4.541", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2147800946", "cited_by_count": 11884, "publication_date": "1989-12-01"}, {"doi": "10.1109/cvpr.2018.00913", "title": "Path Aggregation Network for Instance Segmentation", "abstract": "The way that information propagates in neural networks is of great importance. In this paper, we propose Path Aggregation Network (PANet) aiming at boosting information flow in proposal-based instance segmentation framework. Specifically, we enhance the entire feature hierarchy with accurate localization signals in lower layers by bottom-up path augmentation, which shortens the information path between lower layers and topmost feature. We present adaptive feature pooling, which links feature grid and all feature levels to make useful information in each level propagate directly to following proposal subnetworks. A complementary branch capturing different views for each proposal is created to further improve mask prediction. These improvements are simple to implement, with subtle extra computational overhead. Yet they are useful and make our PANet reach the 1st place in the COCO 2017 Challenge Instance Segmentation task and the 2nd place in Object Detection task without large-batch training. PANet is also state-of-the-art on MVD and Cityscapes.", "arxiv_id": "1803.01534", "paper_id": 5012, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2018.00913", "work_type": "OTHER", "open_access": true, "openalex_id": "W2963857746", "cited_by_count": 9969, "publication_date": "2018-06-01"}, {"doi": "10.1109/tpami.2009.167", "title": "Object Detection with Discriminatively Trained Part-Based Models", "abstract": "We describe an object detection system based on mixtures of multiscale deformable part models. Our system is able to represent highly variable object classes and achieves state-of-the-art results in the PASCAL object detection challenges. While deformable part models have become quite popular, their value had not been demonstrated on difficult benchmarks such as the PASCAL data sets. Our system relies on new methods for discriminative training with partially labeled data. We combine a margin-sensitive approach for data-mining hard negative examples with a formalism we call latent SVM. A latent SVM is a reformulation of MI--SVM in terms of latent variables. A latent SVM is semiconvex, and the training problem becomes convex once latent information is specified for the positive examples. This leads to an iterative training algorithm that alternates between fixing latent values for positive examples and optimizing the latent SVM objective function.", "arxiv_id": null, "paper_id": 5013, "venue_id": 3, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/tpami.2009.167", "work_type": "ARTICLE", "open_access": false, "openalex_id": "W2168356304", "cited_by_count": 9801, "publication_date": "2009-09-24"}, {"doi": "10.48550/arxiv.1409.3215", "title": "Sequence to Sequence Learning with Neural Networks", "abstract": "Deep Neural Networks (DNNs) are powerful models that have achieved excellent performance on difficult learning tasks. Although DNNs work well whenever large labeled training sets are available, they cannot be used to map sequences to sequences. In this paper, we present a general end-to-end approach to sequence learning that makes minimal assumptions on the sequence structure. Our method uses a multilayered Long Short-Term Memory (LSTM) to map the input sequence to a vector of a fixed dimensionality, and then another deep LSTM to decode the target sequence from the vector. Our main result is that on an English to French translation task from the WMT'14 dataset, the translations produced by the LSTM achieve a BLEU score of 34.8 on the entire test set, where the LSTM's BLEU score was penalized on out-of-vocabulary words. Additionally, the LSTM did not have difficulty on long sentences. For comparison, a phrase-based SMT system achieves a BLEU score of 33.3 on the same dataset. When we used the LSTM to rerank the 1000 hypotheses produced by the aforementioned SMT system, its BLEU score increases to 36.5, which is close to the previous best result on this task. The LSTM also learned sensible phrase and sentence representations that are sensitive to word order and are relatively invariant to the active and the passive voice. Finally, we found that reversing the order of the words in all source sentences (but not target sentences) improved the LSTM's performance markedly, because doing so introduced many short term dependencies between the source and the target sentence which made the optimization problem easier.", "arxiv_id": "1409.3215", "paper_id": 5037, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/1409.3215", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W2130942839", "cited_by_count": 17296, "publication_date": "2014-09-10"}, {"doi": "10.1109/cvpr.2018.00907", "title": "Learning Transferable Architectures for Scalable Image Recognition", "abstract": "Developing neural network image classification models often requires significant architecture engineering. In this paper, we study a method to learn the model architectures directly on the dataset of interest. As this approach is expensive when the dataset is large, we propose to search for an architectural building block on a small dataset and then transfer the block to a larger dataset. The key contribution of this work is the design of a new search space (which we call the \"NASNet search space\") which enables transferability. In our experiments, we search for the best convolutional layer (or \"cell\") on the CIFAR-10 dataset and then apply this cell to the ImageNet dataset by stacking together more copies of this cell, each with their own parameters to design a convolutional architecture, which we name a \"NASNet architecture\". We also introduce a new regularization technique called ScheduledDropPath that significantly improves generalization in the NASNet models. On CIFAR-10 itself, a NASNet found by our method achieves 2.4% error rate, which is state-of-the-art. Although the cell is not searched for directly on ImageNet, a NASNet constructed from the best cell achieves, among the published works, state-of-the-art accuracy of 82.7% top-1 and 96.2% top-5 on ImageNet. Our model is 1.2% better in top-1 accuracy than the best human-invented architectures while having 9 billion fewer FLOPS - a reduction of 28% in computational demand from the previous state-of-the-art model. When evaluated at different levels of computational cost, accuracies of NASNets exceed those of the state-of-the-art human-designed models. For instance, a small version of NASNet also achieves 74% top-1 accuracy, which is 3.1% better than equivalently-sized, state-of-the-art models for mobile platforms. Finally, the image features learned from image classification are generically useful and can be transferred to other computer vision problems. On the task of object detection, the learned features by NASNet used with the Faster-RCNN framework surpass state-of-the-art by 4.0% achieving 43.1% mAP on the COCO dataset.", "arxiv_id": "1707.07012", "paper_id": 5106, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr.2018.00907", "work_type": "OTHER", "open_access": true, "openalex_id": "W2736941579", "cited_by_count": 6574, "publication_date": "2018-06-01"}, {"doi": "10.1109/cvpr46437.2021.01625", "title": "Bottleneck Transformers for Visual Recognition", "abstract": "We present BoTNet, a conceptually simple yet powerful backbone architecture that incorporates self-attention for multiple computer vision tasks including image classification, object detection and instance segmentation. By just replacing the spatial convolutions with global self-attention in the final three bottleneck blocks of a ResNet and no other changes, our approach improves upon the baselines significantly on instance segmentation and object detection while also reducing the parameters, with minimal overhead in latency. Through the design of BoTNet, we also point out how ResNet bottleneck blocks with self-attention can be viewed as Transformer blocks. Without any bells and whistles, BoTNet achieves 44.4% Mask AP and 49.7% Box AP on the COCO Instance Segmentation benchmark using the Mask R-CNN framework; surpassing the previous best published single model and single scale results of ResNeSt [67] evaluated on the COCO validation set. Finally, we present a simple adaptation of the BoTNet design for image classification, resulting in models that achieve a strong performance of 84.7% top-1 accuracy on the ImageNet benchmark while being up to 1.64x faster in \"compute\"1time than the popular EfficientNet models on TPU-v3 hardware. We hope our simple and effective approach will serve as a strong baseline for future research in self-attention models for vision.2", "arxiv_id": "2101.11605", "paper_id": 5169, "venue_id": 1035, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1109/cvpr46437.2021.01625", "work_type": "OTHER", "open_access": true, "openalex_id": "W3122484828", "cited_by_count": 1384, "publication_date": "2021-06-01"}, {"doi": "10.1109/cvpr52688.2022.01167", "title": "A ConvNet for the 2020s", "abstract": "The “Roaring 20s” of visual recognition began with the introduction of Vision Transformers (ViTs), which quickly superseded ConvNets as the state-of-the-art image classification model. A vanilla ViT, on the other hand, faces difficulties when applied to general computer vision tasks such as object detection and semantic segmentation. It is the hierarchical Transformers (e.g., Swin Transformers) that reintroduced several ConvNet priors, making Transformers practically viable as a generic vision backbone and demonstrating remarkable performance on a wide variety of vision tasks. However, the effectiveness of such hybrid approaches is still largely credited to the intrinsic superiority of Transformers, rather than the inherent inductive biases of convolutions. In this work, we reexamine the design spaces and test the limits of what a pure ConvNet can achieve. We gradually “modernize” a standard ResNet toward the design of a vision Transformer, and discover several key components that contribute to the performance difference along the way. The outcome of this exploration is a family of pure ConvNet models dubbed ConvNeXt. Constructed entirely from standard ConvNet modules, ConvNeXts compete favorably with Transformers in terms of accuracy and scalability, achieving 87.8% ImageNet top-1 accuracy and outperforming Swin Transformers on COCO detection and ADE20K segmentation, while maintaining the simplicity and efficiency of standard ConvNets.", "arxiv_id": null, "paper_id": 5334, "venue_id": 1035, "oa_status": "CLOSED", "paper_url": "https://doi.org/10.1109/cvpr52688.2022.01167", "work_type": "OTHER", "open_access": false, "openalex_id": "W4312443924", "cited_by_count": 8404, "publication_date": "2022-06-01"}, {"doi": "10.1016/j.patcog.2017.10.013", "title": "Recent advances in convolutional neural networks", "abstract": null, "arxiv_id": "1512.07108", "paper_id": 5336, "venue_id": 205, "oa_status": "GREEN", "paper_url": "https://doi.org/10.1016/j.patcog.2017.10.013", "work_type": "ARTICLE", "open_access": true, "openalex_id": "W2962949934", "cited_by_count": 6571, "publication_date": "2017-10-13"}, {"doi": "10.48550/arxiv.2108.07258", "title": "On the Opportunities and Risks of Foundation Models", "abstract": "AI is undergoing a paradigm shift with the rise of models (e.g., BERT, DALL-E, GPT-3) that are trained on broad data at scale and are adaptable to a wide range of downstream tasks. We call these models foundation models to underscore their critically central yet incomplete character. This report provides a thorough account of the opportunities and risks of foundation models, ranging from their capabilities (e.g., language, vision, robotics, reasoning, human interaction) and technical principles(e.g., model architectures, training procedures, data, systems, security, evaluation, theory) to their applications (e.g., law, healthcare, education) and societal impact (e.g., inequity, misuse, economic and environmental impact, legal and ethical considerations). Though foundation models are based on standard deep learning and transfer learning, their scale results in new emergent capabilities,and their effectiveness across so many tasks incentivizes homogenization. Homogenization provides powerful leverage but demands caution, as the defects of the foundation model are inherited by all the adapted models downstream. Despite the impending widespread deployment of foundation models, we currently lack a clear understanding of how they work, when they fail, and what they are even capable of due to their emergent properties. To tackle these questions, we believe much of the critical research on foundation models will require deep interdisciplinary collaboration commensurate with their fundamentally sociotechnical nature.", "arxiv_id": "2108.07258", "paper_id": 5420, "venue_id": 21, "oa_status": "GREEN", "paper_url": "http://arxiv.org/abs/2108.07258", "work_type": "PREPRINT", "open_access": true, "openalex_id": "W3195577433", "cited_by_count": 2669, "publication_date": "2021-08-16"}]$fx$);
