INSERT INTO method (method_id, method_name, method_category, description, introduced_year, pwc_slug) OVERRIDING SYSTEM VALUE
SELECT method_id, method_name, method_category, description, introduced_year, pwc_slug FROM jsonb_populate_recordset(NULL::method, $fx$[{"pwc_slug": "transformer", "method_id": 1, "description": "A **Transformer** is a model architecture that eschews recurrence and instead relies entirely on an [attention mechanism](https://paperswithcode.com/methods/category/attention-mechanisms-1) to draw global dependencies between input and output. Before Transformers, the dominant sequence transduction models were based on complex recurrent or convolutional neural networks that include an encoder and a decoder. The Transformer also employs an encoder and decoder, but removing recurrence in favor of [attention mechanisms](https://paperswithcode.com/methods/category/attention-mechanisms-1) allows for significantly more parallelization than methods like [RNNs](https://paperswithcode.com/methods/category/recurrent-neural-networks) and [CNNs](https://paperswithcode.com/methods/category/convolutional-neural-networks).", "method_name": "Transformer", "introduced_year": 2000, "method_category": "Autoregressive Transformers"}, {"pwc_slug": null, "method_id": 2, "description": null, "method_name": "Self-Attention", "introduced_year": null, "method_category": null}, {"pwc_slug": "bert", "method_id": 3, "description": "**BERT**, or Bidirectional Encoder Representations from Transformers, improves upon standard [Transformers](http://paperswithcode.com/method/transformer) by removing the unidirectionality constraint by using a *masked language model* (MLM) pre-training objective. The masked language model randomly masks some of the tokens from the input, and the objective is to predict the original vocabulary id of the masked word based only on its context. Unlike left-to-right language model pre-training, the MLM objective enables the representation to fuse the left and the right context, which allows us to pre-train a deep bidirectional Transformer. In addition to the masked language model, BERT uses a *next sentence prediction* task that jointly pre-trains text-pair representations. \r\n\r\nThere are two steps in BERT: *pre-training* and *fine-tuning*. During pre-training, the model is trained on unlabeled data over different pre-training tasks. For fine-tuning, the BERT model is first initialized with the pre-trained parameters, and all of the parameters are fine-tuned using labeled data from the downstream tasks. Each downstream task has separate fine-tuned models, even though they\r\nare initialized with the same pre-trained parameters.", "method_name": "BERT", "introduced_year": 2000, "method_category": "Autoencoding Transformers"}, {"pwc_slug": "gpt", "method_id": 4, "description": "**GPT** is a [Transformer](https://paperswithcode.com/method/transformer)-based architecture and training procedure for natural language processing tasks. Training follows a two-stage procedure. First, a language modeling objective is used on\r\nthe unlabeled data to learn the initial parameters of a neural network model. Subsequently, these parameters are adapted to a target task using the corresponding supervised objective.", "method_name": "GPT", "introduced_year": 2000, "method_category": "Autoregressive Transformers"}, {"pwc_slug": "vision-transformer", "method_id": 7, "description": "The **Vision Transformer**, or **ViT**, is a model for image classification that employs a [Transformer](https://paperswithcode.com/method/transformer)-like architecture over patches of the image.  An image is split into fixed-size patches, each of them are then linearly embedded, position embeddings are added, and the resulting sequence of vectors is fed to a standard [Transformer](https://paperswithcode.com/method/transformer) encoder. In order to perform classification, the standard approach of adding an extra learnable “classification token” to the sequence is used.", "method_name": "Vision Transformer", "introduced_year": 2000, "method_category": "Vision Transformers"}, {"pwc_slug": null, "method_id": 8, "description": null, "method_name": "ResNet", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 9, "description": null, "method_name": "YOLO", "introduced_year": null, "method_category": null}, {"pwc_slug": "faster-r-cnn", "method_id": 10, "description": "**Faster R-CNN** is an object detection model that improves on [Fast R-CNN](https://paperswithcode.com/method/fast-r-cnn) by utilising a region proposal network ([RPN](https://paperswithcode.com/method/rpn)) with the CNN model. The RPN shares full-image convolutional features with the detection network, enabling nearly cost-free region proposals. It is a fully convolutional network that simultaneously predicts object bounds and objectness scores at each position. The RPN is trained end-to-end to generate high-quality region proposals, which are used by [Fast R-CNN](https://paperswithcode.com/method/fast-r-cnn) for detection. RPN and Fast [R-CNN](https://paperswithcode.com/method/r-cnn) are merged into a single network by sharing their convolutional features: the RPN component tells the unified network where to look.\r\n\r\nAs a whole, Faster R-CNN consists of two modules. The first module is a deep fully convolutional network that proposes regions, and the second module is the Fast R-CNN detector that uses the proposed regions.", "method_name": "Faster R-CNN", "introduced_year": 2000, "method_category": "Object Detection Models"}, {"pwc_slug": "mask-r-cnn", "method_id": 11, "description": "**Mask R-CNN** extends [Faster R-CNN](http://paperswithcode.com/method/faster-r-cnn) to solve instance segmentation tasks. It achieves this by adding a branch for predicting an object mask in parallel with the existing branch for bounding box recognition. In principle, Mask R-CNN is an intuitive extension of Faster [R-CNN](https://paperswithcode.com/method/r-cnn), but constructing the mask branch properly is critical for good results. \r\n\r\nMost importantly, Faster R-CNN was not designed for pixel-to-pixel alignment between network inputs and outputs. This is evident in how [RoIPool](http://paperswithcode.com/method/roi-pooling), the *de facto* core operation for attending to instances, performs coarse spatial quantization for feature extraction. To fix the misalignment, Mask R-CNN utilises a simple, quantization-free layer, called [RoIAlign](http://paperswithcode.com/method/roi-align), that faithfully preserves exact spatial locations. \r\n\r\nSecondly, Mask R-CNN *decouples* mask and class prediction: it predicts a binary mask for each class independently, without competition among classes, and relies on the network's RoI classification branch to predict the category. In contrast, an [FCN](http://paperswithcode.com/method/fcn) usually perform per-pixel multi-class categorization, which couples segmentation and classification.", "method_name": "Mask R-CNN", "introduced_year": 2000, "method_category": "Object Detection Models"}, {"pwc_slug": null, "method_id": 12, "description": null, "method_name": "U-Net", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 13, "description": null, "method_name": "Generative Adversarial Network", "introduced_year": null, "method_category": null}, {"pwc_slug": "lstm", "method_id": 17, "description": "An **LSTM** is a type of [recurrent neural network](https://paperswithcode.com/methods/category/recurrent-neural-networks) that addresses the vanishing gradient problem in vanilla RNNs through additional cells, input and output gates. Intuitively, vanishing gradients are solved through additional *additive* components, and forget gate activations, that allow the gradients to flow through the network without vanishing as quickly.\r\n\r\n(Image Source [here](https://medium.com/datadriveninvestor/how-do-lstm-networks-solve-the-problem-of-vanishing-gradients-a6784971a577))\r\n\r\n(Introduced by Hochreiter and Schmidhuber)", "method_name": "LSTM", "introduced_year": 1997, "method_category": "Recurrent Neural Networks"}, {"pwc_slug": "gru", "method_id": 18, "description": "A **Gated Recurrent Unit**, or **GRU**, is a type of recurrent neural network. It is similar to an [LSTM](https://paperswithcode.com/method/lstm), but only has two gates - a reset gate and an update gate - and notably lacks an output gate. Fewer parameters means GRUs are generally easier/faster to train than their LSTM counterparts.\r\n\r\nImage Source: [here](https://www.google.com/url?sa=i&url=https%3A%2F%2Fcommons.wikimedia.org%2Fwiki%2FFile%3AGated_Recurrent_Unit%2C_type_1.svg&psig=AOvVaw3EmNX8QXC5hvyxeenmJIUn&ust=1590332062671000&source=images&cd=vfe&ved=0CA0QjhxqFwoTCMiev9-eyukCFQAAAAAdAAAAABAR)", "method_name": "GRU", "introduced_year": 2000, "method_category": "Recurrent Neural Networks"}, {"pwc_slug": null, "method_id": 19, "description": null, "method_name": "Graph Convolutional Network", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 20, "description": null, "method_name": "Graph Attention Network", "introduced_year": null, "method_category": null}, {"pwc_slug": "graphsage", "method_id": 21, "description": "GraphSAGE is a general inductive framework that leverages node feature information (e.g., text attributes) to efficiently generate node embeddings for previously unseen data.\r\n\r\nImage from: [Inductive Representation Learning on Large Graphs](https://arxiv.org/pdf/1706.02216v4.pdf)", "method_name": "GraphSAGE", "introduced_year": 2000, "method_category": "Graph Models"}, {"pwc_slug": "node2vec", "method_id": 23, "description": "**node2vec** is a framework for learning graph embeddings for nodes in graphs. Node2vec maximizes a likelihood objective over mappings which preserve neighbourhood distances in higher dimensional spaces. From an algorithm design perspective, node2vec exploits the freedom to define neighbourhoods for nodes and provide an explanation for the effect of the choice of neighborhood on the learned representations. \r\n\r\nFor each node, node2vec simulates biased random walks based on an efficient network-aware search strategy and the nodes appearing in the random walk define neighbourhoods. The search strategy accounts for the relative influence nodes exert in a network. It also generalizes prior work alluding to naive search strategies by providing flexibility in exploring neighborhoods.", "method_name": "Node2Vec", "introduced_year": 2000, "method_category": "Graph Embeddings"}, {"pwc_slug": null, "method_id": 27, "description": null, "method_name": "Actor-Critic", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 32, "description": null, "method_name": "Spike-Timing-Dependent Plasticity", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 34, "description": null, "method_name": "ANN-to-SNN Conversion", "introduced_year": null, "method_category": null}, {"pwc_slug": "logistic-regression", "method_id": 38, "description": "**Logistic Regression**, despite its name, is a linear model for classification rather than regression. Logistic regression is also known in the literature as logit regression, maximum-entropy classification (MaxEnt) or the log-linear classifier. In this model, the probabilities describing the possible outcomes of a single trial are modeled using a logistic function.\r\n\r\nSource: [scikit-learn](https://scikit-learn.org/stable/modules/linear_model.html#logistic-regression)\r\n\r\nImage: [Michaelg2015](https://commons.wikimedia.org/wiki/User:Michaelg2015)", "method_name": "Logistic Regression", "introduced_year": 2000, "method_category": "Generalized Linear Models"}, {"pwc_slug": "softmax", "method_id": 43, "description": "The **Softmax** output function transforms a previous layer's output into a vector of probabilities. It is commonly used for multiclass classification.  Given an input vector $x$ and a weighting vector $w$ we have:\r\n\r\n$$ P(y=j \\mid{x}) = \\frac{e^{x^{T}w_{j}}}{\\sum^{K}_{k=1}e^{x^{T}wk}} $$", "method_name": "Softmax", "introduced_year": 2000, "method_category": "Output Functions"}, {"pwc_slug": null, "method_id": 44, "description": null, "method_name": "Residual Connection", "introduced_year": null, "method_category": null}, {"pwc_slug": "dense-connections", "method_id": 45, "description": "**Dense Connections**, or **Fully Connected Connections**, are a type of layer in a deep neural network that use a linear operation where every input is connected to every output by a weight. This means there are $n\\_{\\text{inputs}}*n\\_{\\text{outputs}}$ parameters, which can lead to a lot of parameters for a sizeable network.\r\n\r\n$$h\\_{l} = g\\left(\\textbf{W}^{T}h\\_{l-1}\\right)$$\r\n\r\nwhere $g$ is an activation function.\r\n\r\nImage Source: Deep Learning by Goodfellow, Bengio and Courville", "method_name": "Dense Connections", "introduced_year": 2000, "method_category": "Feedforward Networks"}, {"pwc_slug": "convolution", "method_id": 46, "description": "A **convolution** is a type of matrix operation, consisting of a kernel, a small matrix of weights, that slides over input data performing element-wise multiplication with the part of the input it is on, then summing the results into an output.\r\n\r\nIntuitively, a convolution allows for weight sharing - reducing the number of effective parameters - and image translation (allowing for the same feature to be detected in different parts of the input space).\r\n\r\nImage Source: [https://arxiv.org/pdf/1603.07285.pdf](https://arxiv.org/pdf/1603.07285.pdf)", "method_name": "Convolution", "introduced_year": 1980, "method_category": "Convolutions"}, {"pwc_slug": "dropout", "method_id": 47, "description": "**Dropout** is a regularization technique for neural networks that drops a unit (along with connections) at training time with a specified probability $p$ (a common value is $p=0.5$). At test time, all units are present, but with weights scaled by $p$ (i.e. $w$ becomes $pw$).\r\n\r\nThe idea is to prevent co-adaptation, where the neural network becomes too reliant on particular connections, as this could be symptomatic of overfitting. Intuitively, dropout can be thought of as creating an implicit ensemble of neural networks.", "method_name": "Dropout", "introduced_year": 2000, "method_category": "Regularization"}, {"pwc_slug": null, "method_id": 48, "description": null, "method_name": "Attention", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 49, "description": null, "method_name": "Adam", "introduced_year": null, "method_category": null}, {"pwc_slug": "linear-layer", "method_id": 50, "description": "A **Linear Layer** is a projection $\\mathbf{XW + b}$.", "method_name": "Linear Layer", "introduced_year": 2000, "method_category": "Feedforward Networks"}, {"pwc_slug": "layer-normalization", "method_id": 51, "description": "Unlike [batch normalization](https://paperswithcode.com/method/batch-normalization), **Layer Normalization** directly estimates the normalization statistics from the summed inputs to the neurons within a hidden layer so the normalization does not introduce any new dependencies between training cases. It works well for [RNNs](https://paperswithcode.com/methods/category/recurrent-neural-networks) and improves both the training time and the generalization performance of several existing RNN models. More recently, it has been used with [Transformer](https://paperswithcode.com/methods/category/transformers) models.\r\n\r\nWe compute the layer normalization statistics over all the hidden units in the same layer as follows:\r\n\r\n$$ \\mu^{l} = \\frac{1}{H}\\sum^{H}\\_{i=1}a\\_{i}^{l} $$\r\n\r\n$$ \\sigma^{l} = \\sqrt{\\frac{1}{H}\\sum^{H}\\_{i=1}\\left(a\\_{i}^{l}-\\mu^{l}\\right)^{2}}  $$\r\n\r\nwhere $H$ denotes the number of hidden units in a layer. Under layer normalization, all the hidden units in a layer share the same normalization terms $\\mu$ and $\\sigma$, but different training cases have different normalization terms. Unlike batch normalization, layer normalization does not impose any constraint on the size of the mini-batch and it can be used in the pure online regime with batch size 1.", "method_name": "Layer Normalization", "introduced_year": 2000, "method_category": "Normalization"}, {"pwc_slug": null, "method_id": 52, "description": null, "method_name": "Multi-Head Attention", "introduced_year": null, "method_category": null}, {"pwc_slug": "bpe", "method_id": 53, "description": "**Byte Pair Encoding**, or **BPE**, is a subword segmentation algorithm that encodes rare and unknown words as sequences of subword units. The intuition is that various word classes are translatable via smaller units than words, for instance names (via character copying or transliteration), compounds (via compositional translation), and cognates and loanwords (via phonological and morphological transformations).\r\n\r\n[Lei Mao](https://leimao.github.io/blog/Byte-Pair-Encoding/) has a detailed blog post that explains how this works.", "method_name": "BPE", "introduced_year": 2000, "method_category": "Subword Segmentation"}, {"pwc_slug": "relu", "method_id": 54, "description": "How Do I Communicate to Expedia?\r\nHow Do I Communicate to Expedia? – Call **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   for Live Support & Special Travel Discounts!Frustrated with automated systems? Call **☎️ **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   now to speak directly with a live Expedia agent and unlock exclusive best deal discounts on hotels, flights, and vacation packages. Get real help fast while enjoying limited-time offers that make your next trip more affordable, smooth, and stress-free. Don’t wait—call today!\r\n\r\n\r\nHow Do I Communicate to Expedia?\r\nHow Do I Communicate to Expedia? – Call **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   for Live Support & Special Travel Discounts!Frustrated with automated systems? Call **☎️ **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   now to speak directly with a live Expedia agent and unlock exclusive best deal discounts on hotels, flights, and vacation packages. Get real help fast while enjoying limited-time offers that make your next trip more affordable, smooth, and stress-free. Don’t wait—call today!", "method_name": "ReLU", "introduced_year": 2000, "method_category": "Activation Functions"}, {"pwc_slug": "label-smoothing", "method_id": 55, "description": "**Label Smoothing** is a regularization technique that introduces noise for the labels. This accounts for the fact that datasets may have mistakes in them, so maximizing the likelihood of $\\log{p}\\left(y\\mid{x}\\right)$ directly can be harmful. Assume for a small constant $\\epsilon$, the training set label $y$ is correct with probability $1-\\epsilon$ and incorrect otherwise. Label Smoothing regularizes a model based on a [softmax](https://paperswithcode.com/method/softmax) with $k$ output values by replacing the hard $0$ and $1$ classification targets with targets of $\\frac{\\epsilon}{k}$ and $1-\\frac{k-1}{k}\\epsilon$ respectively.\r\n\r\nSource: Deep Learning, Goodfellow et al\r\n\r\nImage Source: [When Does Label Smoothing Help?](https://arxiv.org/abs/1906.02629)", "method_name": "Label Smoothing", "introduced_year": 1985, "method_category": "Regularization"}, {"pwc_slug": null, "method_id": 56, "description": null, "method_name": "Position-Wise Feed-Forward Layer", "introduced_year": null, "method_category": null}, {"pwc_slug": "absolute-position-encodings", "method_id": 57, "description": "**Absolute Position Encodings** are a type of position embeddings for [[Transformer](https://paperswithcode.com/method/transformer)-based models] where positional encodings are added to the input embeddings at the bottoms of the encoder and decoder stacks. The positional encodings have the same dimension $d\\_{model}$ as the embeddings, so that the two can be summed. In the original implementation, sine and cosine functions of different frequencies are used:\r\n\r\n$$ \\text{PE}\\left(pos, 2i\\right) = \\sin\\left(pos/10000^{2i/d\\_{model}}\\right) $$\r\n\r\n$$ \\text{PE}\\left(pos, 2i+1\\right) = \\cos\\left(pos/10000^{2i/d\\_{model}}\\right) $$\r\n\r\nwhere $pos$ is the position and $i$ is the dimension. That is, each dimension of the positional encoding corresponds to a sinusoid. The wavelengths form a geometric progression from $2\\pi$ to $10000 \\dot 2\\pi$. This function was chosen because the authors hypothesized it would allow the model to easily learn to attend by relative positions, since for any fixed offset $k$,  $\\text{PE}\\_{pos+k}$ can be represented as a linear function of $\\text{PE}\\_{pos}$.\r\n\r\nImage Source: [D2L.ai](https://d2l.ai/chapter_attention-mechanisms/self-attention-and-positional-encoding.html)", "method_name": "Absolute Position Encodings", "introduced_year": 2000, "method_category": "Position Embeddings"}, {"pwc_slug": "max-pooling", "method_id": 58, "description": "**Max Pooling** is a pooling operation that calculates the maximum value for patches of a feature map, and uses it to create a downsampled (pooled) feature map.  It is usually used after a convolutional layer. It adds a small amount of translation invariance - meaning translating the image by a small amount does not significantly affect the values of most pooled outputs.\r\n\r\nImage Source: [here](https://computersciencewiki.org/index.php/File:MaxpoolSample2.png)", "method_name": "Max Pooling", "introduced_year": 2000, "method_category": "Pooling Operations"}, {"pwc_slug": null, "method_id": 59, "description": null, "method_name": "Weight Decay", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 60, "description": null, "method_name": "Batch Normalization", "introduced_year": null, "method_category": null}, {"pwc_slug": "1x1-convolution", "method_id": 61, "description": "A **1 x 1 Convolution** is a [convolution](https://paperswithcode.com/method/convolution) with some special properties in that it can be used for dimensionality reduction, efficient low dimensional embeddings, and applying non-linearity after convolutions. It maps an input pixel with all its channels to an output pixel which can be squeezed to a desired output depth. It can be viewed as an [MLP](https://paperswithcode.com/method/feedforward-network) looking at a particular pixel location.\r\n\r\nImage Credit: [http://deeplearning.ai](http://deeplearning.ai)", "method_name": "1x1 Convolution", "introduced_year": 2000, "method_category": "Convolutions"}, {"pwc_slug": null, "method_id": 62, "description": null, "method_name": "Average Pooling", "introduced_year": null, "method_category": null}, {"pwc_slug": "global-average-pooling", "method_id": 63, "description": "**Global Average Pooling** is a pooling operation designed to replace fully connected layers in classical CNNs. The idea is to generate one feature map for each corresponding category of the classification task in the last mlpconv layer. Instead of adding fully connected layers on top of the feature maps, we take the average of each feature map, and the resulting vector is fed directly into the [softmax](https://paperswithcode.com/method/softmax) layer. \r\n\r\nOne advantage of global [average pooling](https://paperswithcode.com/method/average-pooling) over the fully connected layers is that it is more native to the [convolution](https://paperswithcode.com/method/convolution) structure by enforcing correspondences between feature maps and categories. Thus the feature maps can be easily interpreted as categories confidence maps. Another advantage is that there is no parameter to optimize in the global average pooling thus overfitting is avoided at this layer. Furthermore, global average pooling sums out the spatial information, thus it is more robust to spatial translations of the input.", "method_name": "Global Average Pooling", "introduced_year": 2000, "method_category": "Pooling Operations"}, {"pwc_slug": "gelu", "method_id": 64, "description": "“How do I get a full refund from Expedia?\r\nHow do I get a full refund from Expedia? – Call **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   for Quick Help & Exclusive Travel Deals!Have a question about your booking? Call **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   now to get live, expert support and unlock exclusive best deal discounts on flights, hotels, and vacation packages. Get clear answers fast and access limited-time travel offers that make your next trip easier, cheaper, and stress-free. Don’t wait—call today and save!\r\n\r\n\r\n“How do I get a full refund from Expedia?\r\nHow do I get a full refund from Expedia? – Call **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   for Quick Help & Exclusive Travel Deals!Have a question about your booking? Call **☎️ +1-(888) 829 (0881) or  +1-805-330-4056 or  +1-805-330-4056**   now to get live, expert support and unlock exclusive best deal discounts on flights, hotels, and vacation packages. Get clear answers fast and access limited-time travel offers that make your next trip easier, cheaper, and stress-free. Don’t wait—call today and save!", "method_name": "Refunds@Expedia|||How do I get a full refund from Expedia?", "introduced_year": 2000, "method_category": "Activation Functions"}, {"pwc_slug": "attention-dropout", "method_id": 65, "description": "**Attention Dropout** is a type of [dropout](https://paperswithcode.com/method/dropout) used in attention-based architectures, where elements are randomly dropped out of the [softmax](https://paperswithcode.com/method/softmax) in the attention equation. For example, for scaled-dot product attention, we would drop elements from the first term:\r\n\r\n$$ {\\text{Attention}}(Q, K, V) = \\text{softmax}\\left(\\frac{QK^{T}}{\\sqrt{d_k}}\\right)V $$", "method_name": "Attention Dropout", "introduced_year": 2018, "method_category": "Regularization"}, {"pwc_slug": null, "method_id": 66, "description": null, "method_name": "Kaiming Initialization", "introduced_year": null, "method_category": null}, {"pwc_slug": "residual-block", "method_id": 67, "description": "**Residual Blocks** are skip-connection blocks that learn residual functions with reference to the layer inputs, instead of learning unreferenced functions. They were introduced as part of the [ResNet](https://paperswithcode.com/method/resnet) architecture.\r\n \r\nFormally, denoting the desired underlying mapping as $\\mathcal{H}({x})$, we let the stacked nonlinear layers fit another mapping of $\\mathcal{F}({x}):=\\mathcal{H}({x})-{x}$. The original mapping is recast into $\\mathcal{F}({x})+{x}$. The $\\mathcal{F}({x})$ acts like a residual, hence the name 'residual block'.\r\n\r\nThe intuition is that it is easier to optimize the residual mapping than to optimize the original, unreferenced mapping. To the extreme, if an identity mapping were optimal, it would be easier to push the residual to zero than to fit an identity mapping by a stack of nonlinear layers. Having skip connections allows the network to more easily learn identity-like mappings.\r\n\r\nNote that in practice, [Bottleneck Residual Blocks](https://paperswithcode.com/method/bottleneck-residual-block) are used for deeper ResNets, such as ResNet-50 and ResNet-101, as these bottleneck blocks are less computationally intensive.", "method_name": "Residual Block", "introduced_year": 2000, "method_category": "Image Model Blocks"}, {"pwc_slug": "bottleneck-residual-block", "method_id": 68, "description": "A **Bottleneck Residual Block** is a variant of the [residual block](https://paperswithcode.com/method/residual-block) that utilises 1x1 convolutions to create a bottleneck. The use of a bottleneck reduces the number of parameters and matrix multiplications. The idea is to make residual blocks as thin as possible to increase depth and have less parameters. They were introduced as part of the [ResNet](https://paperswithcode.com/method/resnet) architecture, and are used as part of deeper ResNets such as ResNet-50 and ResNet-101.", "method_name": "Bottleneck Residual Block", "introduced_year": 2000, "method_category": "Image Model Blocks"}, {"pwc_slug": null, "method_id": 69, "description": null, "method_name": "Sigmoid Activation", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 70, "description": null, "method_name": "Bitcoin Customer Service Number +1-833-534-1729", "introduced_year": null, "method_category": null}, {"pwc_slug": "graph-neural-network", "method_id": 71, "description": "", "method_name": "Graph Neural Network", "introduced_year": 2000, "method_category": "Graph Representation Learning"}, {"pwc_slug": "speed", "method_id": 72, "description": "The monocular depth estimation (MDE) is the task of estimating depth from a single frame. This information is an essential knowledge in many computer vision tasks such as scene understanding and visual odometry, which are key components in autonomous and robotic systems. \r\nApproaches based on the state of the art vision transformer architectures are extremely deep and complex not suitable for real-time inference operations on edge and autonomous systems equipped with low resources (i.e. robot indoor navigation and surveillance). This paper presents SPEED, a Separable Pyramidal pooling EncodEr-Decoder architecture designed to achieve real-time frequency performances on multiple hardware platforms. The proposed model is a fast-throughput deep architecture for MDE able to obtain depth estimations with high accuracy from low resolution images using minimum hardware resources (i.e. edge devices). Our encoder-decoder model exploits two depthwise separable pyramidal pooling layers, which allow to increase the inference frequency while reducing the overall computational complexity. The proposed method performs better than other fast-throughput architectures in terms of both accuracy and frame rates, achieving real-time performances over cloud CPU, TPU and the NVIDIA Jetson TX1 on two indoor benchmarks: the NYU Depth v2 and the DIML Kinect v2 datasets.", "method_name": "SPEED", "introduced_year": 2000, "method_category": null}, {"pwc_slug": "cosine-annealing", "method_id": 73, "description": "**Cosine Annealing** is a type of learning rate schedule that has the effect of starting with a large learning rate that is relatively rapidly decreased to a minimum value before being increased rapidly again. The resetting of the learning rate acts like a simulated restart of the learning process and the re-use of good weights as the starting point of the restart is referred to as a \"warm restart\" in contrast to a \"cold restart\" where a new set of small random numbers may be used as a starting point.\r\n\r\n$$\\eta\\_{t} = \\eta\\_{min}^{i} + \\frac{1}{2}\\left(\\eta\\_{max}^{i}-\\eta\\_{min}^{i}\\right)\\left(1+\\cos\\left(\\frac{T\\_{cur}}{T\\_{i}}\\pi\\right)\\right)\r\n$$\r\n\r\nWhere where $\\eta\\_{min}^{i}$ and $ \\eta\\_{max}^{i}$ are ranges for the learning rate, and $T\\_{cur}$ account for how many epochs have been performed since the last restart.\r\n\r\nText Source: [Jason Brownlee](https://machinelearningmastery.com/snapshot-ensemble-deep-learning-neural-network/)\r\n\r\nImage Source: [Gao Huang](https://www.researchgate.net/figure/Training-loss-of-100-layer-DenseNet-on-CIFAR10-using-standard-learning-rate-blue-and-M_fig2_315765130)", "method_name": "Cosine Annealing", "introduced_year": 2000, "method_category": "Learning Rate Schedules"}, {"pwc_slug": null, "method_id": 74, "description": null, "method_name": "SGD with Momentum", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 75, "description": null, "method_name": "Tanh Activation", "introduced_year": null, "method_category": null}, {"pwc_slug": "linear-warmup-with-linear-decay", "method_id": 76, "description": "**Linear Warmup With Linear Decay** is a learning rate schedule in which we increase the learning rate linearly for $n$ updates and then linearly decay afterwards.", "method_name": "Linear Warmup With Linear Decay", "introduced_year": 2000, "method_category": "Learning Rate Schedules"}, {"pwc_slug": null, "method_id": 77, "description": null, "method_name": "WordPiece", "introduced_year": null, "method_category": null}, {"pwc_slug": "linear-warmup-with-cosine-annealing", "method_id": 78, "description": "**Linear Warmup With Cosine Annealing** is a learning rate schedule where we increase the learning rate linearly for $n$ updates and then anneal according to a cosine schedule afterwards.", "method_name": "Linear Warmup With Cosine Annealing", "introduced_year": 2000, "method_category": "Learning Rate Schedules"}, {"pwc_slug": null, "method_id": 79, "description": null, "method_name": "Step Decay", "introduced_year": null, "method_category": null}, {"pwc_slug": "randomhorizontalflip", "method_id": 80, "description": "**RandomHorizontalFlip** is a type of image data augmentation which horizontally flips a given image with a given probability.\r\n\r\nImage Credit: [Apache MXNet](https://mxnet.apache.org/versions/1.5.0/tutorials/gluon/data_augmentation.html)", "method_name": "Random Horizontal Flip", "introduced_year": 2000, "method_category": "Image Data Augmentation"}, {"pwc_slug": "gcn", "method_id": 81, "description": "A **Graph Convolutional Network**, or **GCN**, is an approach for semi-supervised learning on graph-structured data. It is based on an efficient variant of [convolutional neural networks](https://paperswithcode.com/methods/category/convolutional-neural-networks) which operate directly on graphs. The choice of convolutional architecture is motivated via a localized first-order approximation of spectral graph convolutions. The model scales linearly in the number of graph edges and learns hidden layer representations that encode both local graph structure and features of nodes.", "method_name": "GCN", "introduced_year": 2000, "method_category": "Graph Models"}, {"pwc_slug": null, "method_id": 82, "description": null, "method_name": "Random Resized Crop", "introduced_year": null, "method_category": null}, {"pwc_slug": "depthwise-convolution", "method_id": 83, "description": "**Depthwise Convolution** is a type of convolution where we apply a single convolutional filter for each input channel. In the regular 2D [convolution](https://paperswithcode.com/method/convolution) performed over multiple input channels, the filter is as deep as the input and lets us freely mix channels to generate each element in the output. In contrast, depthwise convolutions keep each channel separate. To summarize the steps, we:\r\n\r\n1. Split the input and filter into channels.\r\n2. We convolve each input with the respective filter.\r\n3. We stack the convolved outputs together.\r\n\r\nImage Credit: [Chi-Feng Wang](https://towardsdatascience.com/a-basic-introduction-to-separable-convolutions-b99ec3102728)", "method_name": "Depthwise Convolution", "introduced_year": 2016, "method_category": "Convolutions"}, {"pwc_slug": "q-learning", "method_id": 84, "description": "**Q-Learning** is an off-policy temporal difference control algorithm:\r\n\r\n$$Q\\left(S\\_{t}, A\\_{t}\\right) \\leftarrow Q\\left(S\\_{t}, A\\_{t}\\right) + \\alpha\\left[R_{t+1} + \\gamma\\max\\_{a}Q\\left(S\\_{t+1}, a\\right) - Q\\left(S\\_{t}, A\\_{t}\\right)\\right] $$\r\n\r\nThe learned action-value function $Q$ directly approximates $q\\_{*}$, the optimal action-value function, independent of the policy being followed.\r\n\r\nSource: Sutton and Barto, Reinforcement Learning, 2nd Edition", "method_name": "Q-Learning", "introduced_year": 1984, "method_category": "Off-Policy TD Control"}, {"pwc_slug": "rpn", "method_id": 85, "description": "A **Region Proposal Network**, or **RPN**, is a fully convolutional network that simultaneously predicts object bounds and objectness scores at each position. The RPN is trained end-to-end to generate high-quality region proposals. RPN and algorithms like [Fast R-CNN](https://paperswithcode.com/method/fast-r-cnn) can be merged into a single network by sharing their convolutional features - using the recently popular terminology of neural networks with attention mechanisms, the RPN component tells the unified network where to look.\r\n\r\nRPNs are designed to efficiently predict region proposals with a wide range of scales and aspect ratios. RPNs use anchor boxes that serve as references at multiple scales and aspect ratios. The scheme can be thought of as a pyramid of regression references, which avoids enumerating images or filters of multiple scales or aspect ratios.", "method_name": "RPN", "introduced_year": 2000, "method_category": "Region Proposal"}, {"pwc_slug": "fixed-factorized-attention", "method_id": 86, "description": "How to file a dispute with Expedia?\r\n\r\n\r\nTo file a complaint against Expedia, first try contacting their customer service directly. You can reach them by phone at +(1)(888)(829)(0881) or +(1)(888)(829)(0881), via their online chat support, or through their online help center. If the issue persists, you can escalate it by contacting their corporate office via email or filing a complaint with your payment provider or a consumer protection agency.", "method_name": "{Dispute@FaQ-s}How to file a dispute with Expedia?", "introduced_year": 2000, "method_category": "Attention Patterns"}, {"pwc_slug": null, "method_id": 87, "description": null, "method_name": "15 Ways to Contact How can i speak to someone at Delta Airlines", "introduced_year": null, "method_category": null}, {"pwc_slug": "grouped-convolution", "method_id": 88, "description": "A **Grouped Convolution** uses a group of convolutions - multiple kernels per layer - resulting in multiple channel outputs per layer. This leads to wider networks helping a network learn a varied set of low level and high level features. The original motivation of using Grouped Convolutions in [AlexNet](https://paperswithcode.com/method/alexnet) was to distribute the model over multiple GPUs as an engineering compromise. But later, with models such as [ResNeXt](https://paperswithcode.com/method/resnext), it was shown this module could be used to improve classification accuracy. Specifically by exposing a new dimension through grouped convolutions, *cardinality* (the size of set of transformations), we can increase accuracy by increasing it.", "method_name": "Grouped Convolution", "introduced_year": 2000, "method_category": "Convolutions"}, {"pwc_slug": null, "method_id": 89, "description": null, "method_name": "GPT-3", "introduced_year": null, "method_category": null}, {"pwc_slug": "concatenated-skip-connection", "method_id": 90, "description": "A **Concatenated Skip Connection** is a type of skip connection that seeks to reuse features by concatenating them to new layers, allowing more information to be retained from previous layers of the network. This contrasts with say, residual connections, where element-wise summation is used instead to incorporate information from previous layers. This type of skip connection is prominently used in DenseNets (and also Inception networks), which the Figure to the right illustrates.", "method_name": "Concatenated Skip Connection", "introduced_year": 2000, "method_category": "Skip Connections"}, {"pwc_slug": null, "method_id": 91, "description": null, "method_name": "FPN", "introduced_year": null, "method_category": null}, {"pwc_slug": "pointwise-convolution", "method_id": 92, "description": "**Pointwise Convolution** is a type of [convolution](https://paperswithcode.com/method/convolution) that uses a 1x1 kernel: a kernel that iterates through every single point. This kernel has a depth of however many channels the input image has. It can be used in conjunction with [depthwise convolutions](https://paperswithcode.com/method/depthwise-convolution) to produce an efficient class of convolutions known as [depthwise-separable convolutions](https://paperswithcode.com/method/depthwise-separable-convolution).\r\n\r\nImage Credit: [Chi-Feng Wang](https://towardsdatascience.com/a-basic-introduction-to-separable-convolutions-b99ec3102728)", "method_name": "Pointwise Convolution", "introduced_year": 2016, "method_category": "Convolutions"}, {"pwc_slug": "experience-replay", "method_id": 93, "description": "**Experience Replay** is a replay memory technique used in reinforcement learning where we store the agent’s experiences at each time-step, $e\\_{t} = \\left(s\\_{t}, a\\_{t}, r\\_{t}, s\\_{t+1}\\right)$ in a data-set $D = e\\_{1}, \\cdots, e\\_{N}$ , pooled over many episodes into a replay memory. We then usually sample the memory randomly for a minibatch of experience, and use this to learn off-policy, as with Deep Q-Networks. This tackles the problem of autocorrelation leading to unstable training, by making the problem more like a supervised learning problem.\r\n\r\nImage Credit: [Hands-On Reinforcement Learning with Python, Sudharsan Ravichandiran](https://subscription.packtpub.com/book/big_data_and_business_intelligence/9781788836524)", "method_name": "Experience Replay", "introduced_year": 1993, "method_category": "Replay Memory"}, {"pwc_slug": null, "method_id": 94, "description": null, "method_name": "Graph Convolutional Networks", "introduced_year": null, "method_category": null}, {"pwc_slug": "depthwise-separable-convolution", "method_id": 96, "description": "While [standard convolution](https://paperswithcode.com/method/convolution) performs the channelwise and spatial-wise computation in one step, **Depthwise Separable Convolution**  splits the computation into two steps: [depthwise convolution](https://paperswithcode.com/method/depthwise-convolution) applies a single convolutional filter per each input channel and [pointwise convolution](https://paperswithcode.com/method/pointwise-convolution) is used to create a linear combination of the output of the depthwise convolution. The comparison of standard convolution and depthwise separable convolution is shown to the right.\r\n\r\nCredit: [Depthwise Convolution Is All You Need for Learning Multiple Visual Domains](https://paperswithcode.com/paper/depthwise-convolution-is-all-you-need-for)", "method_name": "Depthwise Separable Convolution", "introduced_year": 2000, "method_category": "Convolutions"}, {"pwc_slug": null, "method_id": 97, "description": null, "method_name": "RoIPool", "introduced_year": null, "method_category": null}, {"pwc_slug": "feedforward-network", "method_id": 98, "description": "A **Feedforward Network**, or a **Multilayer Perceptron (MLP)**, is a neural network with solely densely connected layers. This is the classic neural network architecture of the literature. It consists of inputs $x$ passed through units $h$ (of which there can be many layers) to predict a target $y$. Activation functions are generally chosen to be non-linear to allow for flexible functional approximation.\r\n\r\nImage Source: Deep Learning, Goodfellow et al", "method_name": "Feedforward Network", "introduced_year": 2000, "method_category": "Feedforward Networks"}, {"pwc_slug": "resnext-block", "method_id": 99, "description": "A **ResNeXt Block** is a type of [residual block](https://paperswithcode.com/method/residual-block) used as part of the [ResNeXt](https://paperswithcode.com/method/resnext) CNN architecture. It uses a \"split-transform-merge\" strategy (branched paths within a single module) similar to an [Inception module](https://paperswithcode.com/method/inception-module), i.e. it aggregates a set of transformations. Compared to a Residual Block, it exposes a new dimension,  *cardinality* (size of set of transformations) $C$, as an essential factor in addition to depth and width. \r\n\r\nFormally, a set of aggregated transformations can be represented as: $\\mathcal{F}(x)=\\sum_{i=1}^{C}\\mathcal{T}_i(x)$, where $\\mathcal{T}_i(x)$ can be an arbitrary function. Analogous to a simple neuron, $\\mathcal{T}_i$ should project $x$ into an (optionally low-dimensional) embedding and then transform it.", "method_name": "ResNeXt Block", "introduced_year": 2000, "method_category": "Image Model Blocks"}, {"pwc_slug": "rmsprop", "method_id": 100, "description": "**RMSProp** is an unpublished adaptive learning rate optimizer [proposed by Geoff Hinton](http://www.cs.toronto.edu/~tijmen/csc321/slides/lecture_slides_lec6.pdf). The motivation is that the magnitude of gradients can differ for different weights, and can change during learning, making it hard to choose a single global learning rate. RMSProp tackles this by keeping a moving average of the squared gradient and adjusting the weight updates by this magnitude. The gradient updates are performed as:\r\n\r\n$$E\\left[g^{2}\\right]\\_{t} = \\gamma E\\left[g^{2}\\right]\\_{t-1} + \\left(1 - \\gamma\\right) g^{2}\\_{t}$$\r\n\r\n$$\\theta\\_{t+1} = \\theta\\_{t} - \\frac{\\eta}{\\sqrt{E\\left[g^{2}\\right]\\_{t} + \\epsilon}}g\\_{t}$$\r\n\r\nHinton suggests $\\gamma=0.9$, with a good default for $\\eta$ as $0.001$.\r\n\r\nImage: [Alec Radford](https://twitter.com/alecrad)", "method_name": "RMSProp", "introduced_year": 2013, "method_category": "Stochastic Optimization"}, {"pwc_slug": "resnext", "method_id": 101, "description": "A **ResNeXt** repeats a building block that aggregates a set of transformations with the same topology. Compared to a [ResNet](https://paperswithcode.com/method/resnet), it exposes a new dimension,  *cardinality* (the size of the set of transformations) $C$, as an essential factor in addition to the dimensions of depth and width. \r\n\r\nFormally, a set of aggregated transformations can be represented as: $\\mathcal{F}(x)=\\sum_{i=1}^{C}\\mathcal{T}_i(x)$, where $\\mathcal{T}_i(x)$ can be an arbitrary function. Analogous to a simple neuron, $\\mathcal{T}_i$ should project $x$ into an (optionally low-dimensional) embedding and then transform it.", "method_name": "ResNeXt", "introduced_year": 2000, "method_category": "Convolutional Neural Networks"}, {"pwc_slug": "squeeze-and-excitation-block", "method_id": 102, "description": "The **Squeeze-and-Excitation Block** is an architectural unit designed to improve the representational power of a network by enabling it to perform dynamic channel-wise feature recalibration. The process is:\r\n\r\n- The block has a convolutional block as an input.\r\n- Each channel is \"squeezed\" into a single numeric value using [average pooling](https://paperswithcode.com/method/average-pooling).\r\n- A dense layer followed by a [ReLU](https://paperswithcode.com/method/relu) adds non-linearity and output channel complexity is reduced by a ratio.\r\n- Another dense layer followed by a sigmoid gives each channel a smooth gating function.\r\n- Finally, we weight each feature map of the convolutional block based on the side network; the \"excitation\".", "method_name": "Squeeze-and-Excitation Block", "introduced_year": 2000, "method_category": "Image Model Blocks"}, {"pwc_slug": null, "method_id": 145, "description": null, "method_name": "Convolutional Neural Network", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 146, "description": null, "method_name": "Recurrent Neural Network", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 147, "description": null, "method_name": "Multilayer Perceptron", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 148, "description": null, "method_name": "Support Vector Machine", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 149, "description": null, "method_name": "Attention Mechanism", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 151, "description": null, "method_name": "Autoencoder", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 152, "description": null, "method_name": "Transfer Learning", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 153, "description": null, "method_name": "Fine-Tuning", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 155, "description": null, "method_name": "Data Augmentation", "introduced_year": null, "method_category": null}, {"pwc_slug": null, "method_id": 158, "description": null, "method_name": "Policy Gradient", "introduced_year": null, "method_category": null}, {"pwc_slug": "gpt-4", "method_id": 218, "description": "**GPT-4** is a transformer based model pre-trained to predict the next token in a document.", "method_name": "GPT-4", "introduced_year": 2000, "method_category": "Language Models"}, {"pwc_slug": "non-maximum-suppression", "method_id": 219, "description": "**Non Maximum Suppression** is a computer vision method that selects a single entity out of many overlapping entities (for example bounding boxes in object detection). The criteria is usually discarding entities that are below a given probability bound. With remaining entities we repeatedly pick the entity with the highest probability, output that as the prediction, and discard any remaining box where a $\\text{IoU} \\geq 0.5$ with the box output in the previous step.\r\n\r\nImage Credit: [Martin Kersner](https://github.com/martinkersner/non-maximum-suppression-cpp)", "method_name": "Non Maximum Suppression", "introduced_year": 2000, "method_category": "Proposal Filtering"}]$fx$);
