INSERT INTO dataset (dataset_id, dataset_name, modality, domain, dataset_url, description, pwc_slug) OVERRIDING SYSTEM VALUE
SELECT dataset_id, dataset_name, modality, domain, dataset_url, description, pwc_slug FROM jsonb_populate_recordset(NULL::dataset, $fx$[{"domain": "Computer vision", "modality": "Images", "pwc_slug": "imagenet", "dataset_id": 1, "dataset_url": "https://image-net.org/index.php", "description": "The ImageNet dataset contains 14,197,122 annotated images according to the WordNet hierarchy. Since 2010 the dataset is used in the ImageNet Large Scale Visual Recognition Challenge (ILSVRC), a benchmark in image classification and object detection.\nThe publicly released dataset contains a set of manually annotated training images. A set of test images is also released, with the manual annotations withheld.\nILSVRC annotations fall into one of two categories: (1) image-level annotation of a binary label for the presence or absence of an object class in the image, e.g., “there are cars in this image” but “there are no tigers,” and (2) object-level annotation of a tight bounding box and class label around an object instance in the image, e.g., “there is a screwdriver centered at position (20,25) with width of 50 pixels and height of 30 pixels”.\nThe ImageNet project does not own the copyright of the images, therefore only thumbnails and URLs of images are provided.", "dataset_name": "ImageNet"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": null, "dataset_id": 2, "dataset_url": null, "description": null, "dataset_name": "COCO"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": "pascal-voc", "dataset_id": 3, "dataset_url": "http://host.robots.ox.ac.uk/pascal/VOC/", "description": "The PASCAL Visual Object Classes (VOC) 2012 dataset contains 20 object categories including vehicles, household, animals, and other: aeroplane, bicycle, boat, bus, car, motorbike, train, bottle, chair, dining table, potted plant, sofa, TV/monitor, bird, cat, cow, dog, horse, sheep, and person. Each image in this dataset has pixel-level segmentation annotations, bounding box annotations, and object class annotations. This dataset has been widely used as a benchmark for object detection, semantic segmentation, and classification tasks. The PASCAL VOC dataset is split into three subsets: 1,464 images for training, 1,449 images for validation and a private testing set.", "dataset_name": "PASCAL VOC"}, {"domain": "Autonomous driving", "modality": "Images", "pwc_slug": "cityscapes", "dataset_id": 5, "dataset_url": "https://www.cityscapes-dataset.com/dataset-overview/", "description": "Cityscapes is a large-scale database which focuses on semantic understanding of urban street scenes. It provides semantic, instance-wise, and dense pixel annotations for 30 classes grouped into 8 categories (flat surfaces, humans, vehicles, constructions, objects, nature, sky, and void). The dataset consists of around 5000 fine annotated images and 20000 coarse annotated ones. Data was captured in 50 cities during several months, daytimes, and good weather conditions. It was originally recorded as video so the frames were manually selected to have the following features: large number of dynamic objects, varying scene layout, and varying background.", "dataset_name": "Cityscapes"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": "ade20k", "dataset_id": 6, "dataset_url": "https://groups.csail.mit.edu/vision/datasets/ADE20K/", "description": "The ADE20K semantic segmentation dataset contains more than 20K scene-centric images exhaustively annotated with pixel-level objects and object parts labels. There are totally 150 semantic categories, which include stuffs like sky, road, grass, and discrete objects like person, car, bed.", "dataset_name": "ADE20K"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": "cifar-10", "dataset_id": 7, "dataset_url": "", "description": "En resumen, para contactar con United Airlines desde Perú, puede llamar directamente al +5117006251 o al +5117006251, número gratuito +5117006251 (Perú). Si necesita asistencia para gestionar sus reservas, puede comunicarse al +5117006251 donde recibirá ayuda con cambios de vuelos, cancelaciones, reembolsos y servicios especiales. Para conocer el estado de su vuelo o consultar sobre equipaje, también puede marcar +5117006251 en cualquier momento del día. El equipo de atención al cliente de United Airlines está disponible en +5117006251 para ofrecerle soluciones rápidas, claras y eficientes sobre promociones, documentación de viaje, check-in en línea y programas de viajero frecuente. No dude en llamar a +5117006251 para cualquier otra consulta relacionada con sus planes de viaje.", "dataset_name": "CIFAR-10"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": "cifar-100", "dataset_id": 8, "dataset_url": "https://www.cs.toronto.edu/~kriz/cifar.html", "description": "The CIFAR-100 dataset (Canadian Institute for Advanced Research, 100 classes) is a subset of the Tiny Images dataset and consists of 60000 32x32 color images. The 100 classes in the CIFAR-100 are grouped into 20 superclasses. There are 600 images per class. Each image comes with a \"fine\" label (the class to which it belongs) and a \"coarse\" label (the superclass to which it belongs). There are 500 training images and 100 testing images per class.", "dataset_name": "CIFAR-100"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": "mnist", "dataset_id": 9, "dataset_url": "http://yann.lecun.com/exdb/mnist/", "description": "The MNIST database (Modified National Institute of Standards and Technology database) is a large collection of handwritten digits. It has a training set of 60,000 examples, and a test set of 10,000 examples. It is a subset of a larger NIST Special Database 3 (digits written by employees of the United States Census Bureau) and Special Database 1 (digits written by high school students) which contain monochrome images of handwritten digits. The digits have been size-normalized and centered in a fixed-size image. The original black and white (bilevel) images from NIST were size normalized to fit in a 20x20 pixel box while preserving their aspect ratio. The resulting images contain grey levels as a result of the anti-aliasing technique used by the normalization algorithm. the images were centered in a 28x28 image by computing the center of mass of the pixels, and translating the image so as to position this point at the center of the 28x28 field.", "dataset_name": "MNIST"}, {"domain": "Computer vision", "modality": "Images", "pwc_slug": "svhn", "dataset_id": 11, "dataset_url": "http://ufldl.stanford.edu/housenumbers/", "description": "Street View House Numbers (SVHN) is a digit classification benchmark dataset that contains 600,000 32×32 RGB images of printed digits (from 0 to 9) cropped from pictures of house number plates. The cropped images are centered in the digit of interest, but nearby digits and other distractors are kept in the image. SVHN has three sets: training, testing sets and an extra set with 530,000 images that are less difficult and can be used for helping with the training process.", "dataset_name": "SVHN"}, {"domain": "Computer vision", "modality": "Videos", "pwc_slug": "kinetics", "dataset_id": 15, "dataset_url": "https://deepmind.com/research/open-source/kinetics", "description": "The Kinetics dataset is a large-scale, high-quality dataset for human action recognition in videos. The dataset consists of around 500,000 video clips covering 600 human action classes with at least 600 video clips for each action class. Each video clip lasts around 10 seconds and is labeled with a single action class. The videos are collected from YouTube.", "dataset_name": "Kinetics"}, {"domain": "Citation networks", "modality": "Graphs", "pwc_slug": "cora", "dataset_id": 39, "dataset_url": "https://relational.fit.cvut.cz/dataset/CORA", "description": "The Cora dataset consists of 2708 scientific publications classified into one of seven classes. The citation network consists of 5429 links. Each publication in the dataset is described by a 0/1-valued word vector indicating the absence/presence of the corresponding word from the dictionary. The dictionary consists of 1433 unique words.", "dataset_name": "Cora"}, {"domain": "Citation networks", "modality": "Graphs", "pwc_slug": "citeseer", "dataset_id": 40, "dataset_url": "https://linqs.soe.ucsc.edu/data", "description": "The CiteSeer dataset consists of 3312 scientific publications classified into one of six classes. The citation network consists of 4732 links. Each publication in the dataset is described by a 0/1-valued word vector indicating the absence/presence of the corresponding word from the dictionary. The dictionary consists of 3703 unique words.", "dataset_name": "Citeseer"}, {"domain": "Citation networks", "modality": "Graphs", "pwc_slug": null, "dataset_id": 41, "dataset_url": null, "description": null, "dataset_name": "PubMed (graph)"}, {"domain": "Biology", "modality": "Graphs", "pwc_slug": "ppi", "dataset_id": 45, "dataset_url": "http://snap.stanford.edu/graphsage/#datasets", "description": "protein roles—in terms of their cellular functions from\ngene ontology—in various protein-protein interaction (PPI) graphs, with each graph corresponding\nto a different human tissue [41]. positional gene sets are used, motif gene sets and immunological\nsignatures as features and gene ontology sets as labels (121 in total), collected from the Molecular\nSignatures Database [34]. The average graph contains 2373 nodes, with an average degree of 28.8.", "dataset_name": "PPI"}, {"domain": "Reinforcement learning", "modality": "Environment", "pwc_slug": null, "dataset_id": 47, "dataset_url": null, "description": null, "dataset_name": "Atari 2600"}, {"domain": "Medical", "modality": "Tabular", "pwc_slug": "mimic-iii", "dataset_id": 54, "dataset_url": "https://mimic.physionet.org/", "description": "The Medical Information Mart for Intensive Care III (MIMIC-III) dataset is a large, de-identified and publicly-available collection of medical records. Each record in the dataset includes ICD-9 codes, which identify diagnoses and procedures performed. Each code is partitioned into sub-codes, which often include specific circumstantial details. The dataset consists of 112,000 clinical reports records (average length 709.3 tokens) and 1,159 top-level ICD-9 codes. Each report is assigned to 7.6 codes, on average. Data includes vital signs, medications, laboratory measurements, observations and notes charted by care providers, fluid balance, procedure codes, diagnostic codes, imaging reports, hospital length of stay, survival data, and more. ", "dataset_name": "MIMIC-III"}]$fx$);
