SELECT setval(pg_get_serial_sequence('venue', 'venue_id'), coalesce((SELECT max(venue_id) FROM venue), 1));
SELECT setval(pg_get_serial_sequence('author', 'author_id'), coalesce((SELECT max(author_id) FROM author), 1));
SELECT setval(pg_get_serial_sequence('topic', 'topic_id'), coalesce((SELECT max(topic_id) FROM topic), 1));
SELECT setval(pg_get_serial_sequence('paper', 'paper_id'), coalesce((SELECT max(paper_id) FROM paper), 1));
